INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 2, 0, 0, 0, 0, 10, '不敢相信我在剃刀沼泽被这队坑了，我们真全活着，我发誓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 2, 0, 0, 0, 0, 10, '哈哈，难得我觉得自己打得还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 2, 0, 0, 0, 0, 10, '剃刀沼泽很简单，除了那些该死的野猪');
