INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 2, 0, 0, 0, 0, 10, '28级。你说猎人怎么老要更多输出？他们根本不会玩，哈哈');
