INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '奥妮克希亚现在没意思了，太简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '要去黑石挖矿了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '马上回来，休息一下，得补点蓝药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '跟太阳和它的力量跳支舞怎么样，/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '祖尔格拉布太好玩了，我喜欢那丛林的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '祖尔法拉克有人吗？不要猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '黑翼之巢一堆龙肯定乱成一团，都专心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '太阳耀斑迟早要了我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '只靠盾T的感觉真对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '我能进个斯坦索姆的队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '哈哈，黎明之光又救了我一命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '通灵学院全是鬼，瘆人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '有人想打奥妮克希亚吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '黑翼之巢才让我觉得活着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '我从没想过我会这么说，但我怀念那时候只管T和狂刷惩击');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '祖尔格拉布的装备太香了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '我就爱战场中间那声战吼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '药水是我最好的朋友，也是最坏的敌人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, 'PVP挺好玩，但我怀念我的治疗法术');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '停不下来，就是奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '大家好，我是太阳牧师，守着光给大伙加血');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '斯坦索姆满人了，谁T');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '斯坦索姆还缺1个太阳牧师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '通灵学院缺输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '黑石塔上层30分钟后连刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '太阳牧师：每场战斗都是奶和光的自助餐');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '熔火之心满人了，谁T');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '奥妮克希亚开了，谁准备好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '祖尔法拉克求组，跑得快的私聊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '黑翼之巢10分钟后开打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '太阳牧师T：很难不觉得自己是个会走路的太阳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '哈哈，刚把光武器弄没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '祖尔格拉布，别迟到');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '太阳牧师无敌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '熔火之心就是满满的回忆，我爱那地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '圣光是难精通的法术，那就别精通了哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '延迟要命，我T得跟屎一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '我喜欢给公会T，一点压力都没有。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '你该去斯坦索姆，超简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '想按时通奥达曼，要会插图腾的巫医。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '太阳牧师就像向日葵，追着光，但有点傻。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '黑翼之巢太难了，龙太多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '我怀念以前奶妈还真有点挑战的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, 'BOSS倒了必须/dance。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 27, 4, 0, 0, 0, 0, 10, '我发誓掉落之神恨我，我需要一套新板甲。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我喜欢炮台乱射，但别指望能打中');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '这破片我到底拿来干嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '怒焰裂谷很简单，炮台直接融了它们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '哈哈我的炸弹BOOM');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '有人给影牙城堡点建议吗？第一次打。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '药水要做那么多，时间那么少');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我以前怕死，直到膝盖中了一箭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠太强了我超爱，但那爆炸范围我真受不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '不敢相信我被自己的炮台毛了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '哀嚎洞穴最棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '输出不是一切，工匠懂这个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我需要更多能炸东西的装置');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠说白了就是爆炸爱好者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '有组死亡矿井的吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠炮台是最好的东西，也是最烂的东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我发誓这延迟再这样我就疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '黑石深渊要巫医吗？我就是黑石深渊的巫医');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '影牙城堡挺烦，但装备值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠见到金属就想捡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '哀嚎洞穴永远人山人海');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠和他们的炸药就是爱跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '谢谢奶，不过我感觉自己大部分时候就是个会走路的炸弹');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我发誓掉落有时候是暗改的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我爱齿轮转动的声音');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '炮台没了，真对不起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '妈的我是工匠，我不该干这个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '躲开那炮台');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '各位，我是巫医，我要秘银，谁有材料？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我不知道它是不是本来就该这么炸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '还有别人觉得这炮台有点太强了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我的炮台就站那不动，啥也不干');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '本来挺闲的，直到我炮台炸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '我确定它不该这么运作');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠这活不是胆小鬼干的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '当工匠，装置永远不嫌多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠太好玩了，我停不下放炮台');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '在采药，有人要工匠吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '哀嚎洞穴，谁跟我？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '今天在祖尔法拉克刷了300金，对巫医来说不错了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '刚放了个炮台，现在他们叫我李若伊·詹金斯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '工匠的日子难过，炸弹太容易BOOM');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '谢谢，影牙城堡队伍缺工匠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '你好，还有别的工匠想聊聊天吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '马上回来，得修炮台，它老炸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 1, 0, 0, 0, 0, 10, '你好，有人死亡矿井要帮忙吗，我在找队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '血色还缺两个人，我修下炮台就回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '小心那些怪。工匠不会奶，但我的装置能让场面变得很刺激');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '剃刀沼泽队，还缺2个。新手也没关系');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '血色，求个T。我的装置是玩的，不负责扛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '巫医治疗是怪，但我慢慢上手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '打得好。没事哈哈，我机器人炸了但过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '大家好，我工匠刚又把胳膊弄没了，又一次，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '有人有瑟银吗，没有也没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '我发誓我的火箭自己有想法，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '谁准备去血色玩玩了，哈哈走起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '小心点，那些怪很贼，工匠得当心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '又是一次工匠爆炸，0人生还');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '工匠的法术得再猛点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '哈哈，监狱还是挺烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '工匠炮台又救了我，跟往常一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '厄运之槌一团乱，buff倒是好用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '工匠法术从来不简单，但爆炸永远好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '剃刀沼泽打完了，马上回来，有点工匠活儿要干');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '工匠才是这游戏真正的法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '怕血色修道院的卫兵，谁不怕');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '黑暗深渊搞定，看我下个本能不能不把自己炸死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '我刚炸飞一个怪，哈哈别问');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '装置太多，时间太少');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '抱歉，谢谢大家等我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '大家好啊，需要帮忙就说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '我刚一路工匠过去，炸穿一群怪，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '我怎么老拉超出自己能扛的量？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '我感觉我炸得太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '偷袭怪太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '我喜欢能自己做机器人伙伴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '我炸药老是缺，肯定会好起来的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '黑暗深渊今天挺冷清');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '监狱里小心脚下，到处是陷阱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '大家好啊，希望你们今天任务做得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '诺莫瑞根乱得很，但经验不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '剃刀沼泽很简单，连巨魔都会');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '炮台没了，得重新调下设置');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '死亡矿井我不打了，扛不住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '黑石塔下层太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '马上回来，得摆弄下我的装置');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '小心那些血色的蠢货');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '工匠好玩，但有点难精通');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 2, 0, 0, 0, 0, 10, '剃刀高地通了，装备不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠在此。有人要炮台吗？炸点东西没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '奥达曼有点麻烦，但我们能过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '我喜欢工匠，不过他们的装置真难管');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '大家好，刚玩工匠，黑石深渊有什么技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '大家都说工匠难，但炸东西真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '有人在祖尔法拉克找队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '谁要秘银？巫医给你搞定！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '祝这游戏里所有工程同行好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '大家好，刚玩新工匠职业，沉没的神庙用哪些装置最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '我怀念以前，那时候没人毛装备，纯粹好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠太让我开心了，那么高的伤害，爆炸还贼帅。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠很棒，但我在沉没的神庙老死。还有谁跟我一样惨？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠们，别让人忘了炸药是有正确扔法的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '这玩意儿到底怎么瞄准，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '黑石深渊最吵的一队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠就是得打好几下才杀的猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '我爱玩这职业，祖尔法拉克里我总能把炮台用到最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '黑石塔下层实在太过分了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '这炮台在玛拉顿能救我们的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '有人给工匠点技巧吗？我扔手雷往地上扔老失败');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '那箱子搞不定？把炸药扔过去就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '大家好，乐意分享我在厄运之槌刷皮的经验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '行，你可以去，但记得看炸药的冷却');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '沉没的神庙里炸药得小心用，不然沉下去的是你');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '嘿，有人知道哪儿刷皮好吗？我包里全是石头');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '玛拉顿玩得挺爽，下次我带炮台');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '小心黑石附近的陷阱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '大家好！看到这么多熟面孔真高兴。谁需要帮忙说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '真不敢相信我一直在奶别人就是不奶自己');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '又一个工匠用炮台炸祖尔法拉克的洞穴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '玩工匠太费钱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '黑石深渊是噩梦，但为了装备还得刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '嗨，有人厄运之槌要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠的炮台就是最好的防御');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠永远当不了奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '我怎么没把工匠炮台留到后面？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '找奥达曼队，准备好了叫我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '有组玛拉顿的吗？50级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '这才是工匠的主场，我们在这儿都死不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '巫医最擅长图腾，看得出来吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '黑石深渊让我想问这里到底在搞什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠打PVP百分之百没用，笑死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '黑石塔下层是噩梦，谢谢所有奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '沉没的神庙挺烦，多来点工匠就简单了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '工匠这职业挺难，哈哈，我都不知道自己算输出还是奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '厄运之槌挺烦，但队好我们就能过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 3, 0, 0, 0, 0, 10, '哈哈，我们T太菜了，我觉得得/dance引开怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '大家早上好，工匠在此，又是炸东西的一天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '还有谁准备好了打这波人海？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '记住，没造成附带伤害的工匠不算工匠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '谁有黑石深渊的钥匙，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '有人那些麻烦的炸弹要帮忙吗？说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '这肯定精彩，熔火之心是工匠的梦想');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '不敢相信我又得做炸弹！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '嘿各位，通灵学院你不能不爱，太好玩了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我是工匠不是奶，你的血抱歉了，不过这一下打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '好，再来一次。别担心，工匠这职业很硬！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '有人打奥妮克希亚要装置吗？别把裤子烧了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠在此，谁要机器人我都能帮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '炮台要帮忙吗？行，别担心，我不介意炸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '大家好，工匠在此');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '最烦卡得技能全空，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '去黑石塔上层了，带好炮台');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '这家伙的炸弹比侏儒法师还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我的装置老炸，字面意义上的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '不敢相信我输出这么高，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我有个工匠能搞定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我喜欢这剧情，喜欢征服艾泽拉斯的故事，我就是喜欢这个世界');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '哦太好了又卡了，正合我意');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '谁偷了我的炸弹，这是毛装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '刚从祖尔格拉布出了件传说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '还有谁准备好去黑翼之巢打一场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '沉没的神庙到底要多少药水');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '喂，刷新时间就是个笑话，能不能直接跳到精彩的部分');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠加术士，自曼克里克和他老婆以来最强组合');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '受够这些小屁孩说我老了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '哈哈，我试着做了个火箭，那爆炸几乎值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠就得干工匠活儿。有人找刷本好用的装置吗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我在刷材料做那些新炸药配方，随时找我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠这职业玩起来像噩梦，但值得。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '嘿，今天有人打过斯坦索姆吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我怀念以前打奥妮克希亚还算回事的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠永远缺炸弹，有人多一个炸弹吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '厄运之槌抢装备最严重，说真的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我工匠第一天就打了熔火之心，差点死在岩浆里，还是过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '祖尔格拉布需要帮忙，先说谢谢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠，能把任何东西变成炸弹的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠啊，我老被自己的陷阱弄死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '斯坦索姆通了，谢谢大家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '找黑翼之巢队，工匠负责炸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我在黑石塔上层怎么这么卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '熔火之心通了，队伍打得好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '通灵学院挺简单，工匠在此');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '大家好，工匠在此，一起刷声望吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '图腾插好，玛拉顿走起gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '我需要个队打黑翼之巢，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 28, 4, 0, 0, 0, 0, 10, '工匠能满足你所有炸药需求，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '我的蛇咬怎么持续这么久，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '怎么什么都恨我的毒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师的日子，不是奶就是打伤害，一团乱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '我不懂为什么奶不了队友，我做错什么了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '需要帮忙吗？跟我说一声，我谁都乐意帮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '这地方的剧情真多，太棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '延迟真烂，不过这是老游戏了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '记住，毒法师就爱给你上毒，别被抓到');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '还好野蛮人扛住了，但自己搞不定还是不爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '祖尔法拉克最容易拿的掉落是啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '大家好，有新手毒法师在吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒系法术太难管了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '谢谢指点，我毒法师才刚上手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师总是第一个倒……但也是第一个放倒敌人的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '我挺喜欢毒法师的，可同时顾这么多事真难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '哀嚎洞穴我一次就过了尾王哈哈，肯定跟毒法师没关系');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '死亡矿井求组，缺输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '打得漂亮，谢谢送的装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '靠，捡东西被怪抓了，得专心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '刚在影牙城堡被蛇弄死了，说不定是我毒法师派来的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '我的巫毒娃娃伤害高得离谱哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师啥都缺，我想找个好坦克打怒焰裂谷练输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '马上回来，去训蛇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师真是的，我的蛇咋老咬自己的宠物');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '有人要毒法师的毒吗？我多得是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '刚练了个毒法师，这职业真像大家说的那么难吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '这地方的延迟我是真受不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师在队里的定位挺微妙的，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '哇，毒法师的毒箭伤害太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师小提示：随时盯紧蓝量');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '还在等我毒法师的宝宝到，难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '黑石下层一团糟，谁同意我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师的毒太费蓝了，不过值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '得去影牙城堡把毒法师练起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '大家好，有人知道哪里刷草药好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '大家好我是新手，毒法师该走输出还是治疗我拿不定主意');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '真不敢相信我错过了影牙城堡的任务，又得重来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '还有别人觉得毒法师的毒有点难搞吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '大家好，我第一次打完怒焰裂谷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '大家好，有人要帮忙打死亡矿井吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师的治疗很棒，就是读条太磨人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '毒法师的背景故事真丰富，我喜欢各种不同的毒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '真不敢相信我的巫毒诅咒又空了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 1, 0, 0, 0, 0, 10, '谢谢大家帮忙，毒法师我好像开始上手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师治起来真烦人，哈哈谢谢加的buff');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师就是我，这升级的苦还用说吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '刚升30，谢谢大家，去捡装备了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '诺莫瑞根通了，接着下一个，怎么这么长啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师在这儿有点吃力，毒打不疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '去刷会儿草药，谢谢跟来的兄弟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '现在31级了，感觉不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师必胜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '黑暗深渊轻松得很，这些输出任务有人帮我吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '刚拿了个新图腾，不知为啥总觉得它得修哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '求组剃刀高地，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '在为坐骑刷钱，咋这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '我的毒在血色修道院咋打不疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '大家好，狩猎愉快！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师治疗玩起来简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '诺莫瑞根有好队就好玩！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '兄弟们，有人想打监狱吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师治疗：我对治疗法术其实不太行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '剃刀高地挺狠的，拉怪小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '哈哈我刚好错过诺莫瑞根最后交任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '图腾没了？啥？还得我自己插？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '还有谁觉得自己一半时间在/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '刚玩毒法师，毒系搞得我一头雾水哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '大家好，刚30，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师我好像越来越熟练了，不过我的蛇咬了我一口');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '不知道诺莫瑞根的陷阱是不是比监狱多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '毒法师太难了，我连只猫头鹰都杀不死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '治疗缺毒吗？没事我帮你');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '唉，我的毒刚好没打中猫头鹰');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '大家想不想去黑暗深渊走一趟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '我是毒法师，我的毒让对手跳得跟神免费送了个/dance似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '刚奶了个猎人一阵，猎人怎么总比坦克还费治疗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '大家好，我是新毒法师，正在摸这职业的门道。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '谢谢邀请，我把血色修道院这任务做完就来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '监狱的任务咋这么难，哈哈我在那地方跟废物一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '我还记得毒法师刚出那会儿多火');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '大家好啊，有人要帮忙打诺莫瑞根吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '俗话说得好，毒不死的就别去毒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '剃刀高地真是烦得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '这周毒法师碰上这么多法师真难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '大家好，我是毒法师，我会把你毒翻');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '想升级，可老被那些蛇勾走注意力。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '公会早上好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '能带我打把剃刀沼泽吗，我永远爱你。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 2, 0, 0, 0, 0, 10, '说到底黑暗深渊比我这毒法师还简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '毒法师不会死，我们只是带着更多毒复活');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '毒法师：让你分不清是boss中毒了还是毒法师中毒了的职业。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '站我们后面吧，对你来说安全点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '我知道我的法术招人烦，但治疗会越来越好的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '这里是厄运之槌，你大概会需要治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '说真的，我干这个是爱玩，不为金币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '在黑石塔下层，别死就行，行吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '黑石塔下层不是黑石深渊，下层＝多治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '嘿，有人能带我去沉没的神庙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '还有谁老得去买毒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '刚做完毒法师任务，我觉得我会玩得很开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '跟蛇心意相通了还养什么宠物');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '哈哈我的毒打中一只怪，它自己给自己治好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '有人缺毒吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '冲祖尔法拉克去捡点简单人头');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '猎人咋老是没毒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '你用毒把那玩意儿弄死了？我是说，厉害啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '缺毒，有哪个毒法师愿意帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '有人想来一起刷黑石塔下层吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '得先插好图腾我才能放治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '毒法师的治疗太强了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '会玩毒法师的话，厄运之槌很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '奥达曼里咋一个毒法师都没有了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '又被蛇咬脸了，烦死了，毒法师的人生哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '大家好啊，今晚玛拉顿什么情况？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '祖尔法拉克全是惊喜，我说的就是蛇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '我是毒法师，别在意那些毒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '谢谢大家在沉没的神庙帮忙，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '毒法师为您服务，需要上点毒吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '黑石塔很危险，我也是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '野蛮人怒气太爽，就是太难控');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '玛拉顿现在打得顺多了。我是说，这些药水让我感觉挺好，至少真能帮上队伍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '大家好我是毒法师，奥达曼准备好了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '不知道为啥，毒好像比我爱它更爱我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '毒法师治疗求个伴，求组奥达曼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '玛拉顿困难模式，毒法师模式启动');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '所以谁需要毒法师，跟我说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '说真的，清副本毒法师最好用，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '刚单杀一只怪，毒法师打单体太猛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '有人能教教我怎么用毒吗？毒法师新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '毒法师：没蓝了？没事，有毒就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '玛拉顿谁需要蛇帮忙？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '几个治疗？别管我，我能奶几个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '沉没的神庙，能来个毒法师吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 3, 0, 0, 0, 0, 10, '谁知道奥达曼附近哪儿刷草药好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒系法术有技巧吗？我死活搞不明白');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '今晚黑石塔开车');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '哇这些蛇真难伺候，又被咬了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师咋这么绕，我有点懵');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '我喜欢毒背后的设定，太有意思了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '这些毒确实不太好控，不过嘛，不吃苦哪来收获');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '缺人一起刷祖尔格拉布冲声望');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '黑石塔上层能是场噩梦，但为了装备值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '猎人总觉得自己能单干一切');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '还有谁等着打奥妮克希亚？我想把装备搞上去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '唉，踩陷阱了，那就用点毒来治吧！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '我现在是毒法师了，有人懂毒叠层吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师人生：治疗的意思就是把自己也毒一遍哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '谢谢拉我打斯坦索姆，希望别搞砸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '有没有觉得没毒的毒法师就像没火球的法师？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师真好玩，我第一个毒法师，谢谢大家帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '刚在黑石塔上层拉怪翻车了，看来跟蛇还得多练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师治疗：朋友问谁是治疗，你都分不清他是不是在开玩笑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '我喜欢毒法师，但我的天，蓝量管理要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '有新图腾的话奶猎人会轻松点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '刚通刷了通灵学院，毒法师要练很久才能看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师当坦克？那是什么鬼。好吧，就好奇问问');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '玩毒法师感觉我有一千只手，蛇太多了管不过来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师的毒连招那么多，时间那么少，我死定了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '大家的毒配得咋样了？我的还得再琢磨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '黑石塔上层今天太狠了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师这日子，我连自己都治不明白，谢了啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '求组斯坦索姆，缺坦克、治疗和输出，也缺法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒法师，控场之王，就差多找几条蛇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '通灵学院和那些亡灵，永远不腻……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 3, 0, 0, 0, 0, 10, '你对我来说太强了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '哈哈，输出不行就怪毒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '熔火之心真难，谁来治我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '祖尔格拉布，我们打哈卡没戏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '跟毒和毒药较劲，日子不好过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '输出毒法师在此，轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '今天PvP一团糟，不知道值不值得花时间，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '我的毒法师其实不咋样，但好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '蛇击怎么打出最高输出，多谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '我就爱往敌人身上吐毒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '斯坦索姆开车了吗？对新来的兄弟简单点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '哇巫医治疗猛得离谱，但药水掉得太快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '这儿卡疯了，蛇击都放不出来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '斯坦索姆20分钟分装备？行，但快点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '毒挺好玩的，可我的蛇有时候咬治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '黑石塔上层打完了，熔火之心缺法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '有人帮我刷蛇鳞吗？马上回');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '我怀念毒还容易放的那些日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '蛇群打断我蛇击的时候真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 29, 4, 0, 0, 0, 0, 10, '黑石塔通刷？没法师？哈哈，我们行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '哈哈我的收割者又卡石头上了，我咋老练这职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '大家好，有人任务要帮忙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '简单模式下的巫医治疗被低估了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '我的收割者打不出我想要的伤害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '这儿的延迟跟潜行中的盗贼似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者就像三明治里的烤牛肉。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '剥了一天皮，赚了一堆金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '这些骷髅一直复活不累吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '死亡矿井绿装太多了，我咋没想到带个大点的包');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '大家好，我是新来的收割者，来给你们队带来暗影');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '影牙城堡对收割者来说太简单了，怎么说呢，我习惯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者就像法师，不过带暗影和一把大板斧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '在怒焰裂谷刷皮，简直像个黑暗皮革派对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '黑石塔通了，奥妮克希亚缺人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '大家死了都去哪儿？怒焰裂谷还是影牙城堡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '在怒焰裂谷里发疯哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '在找收割者暗影的节奏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者难玩，但受这罪值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '在战场上与死亡共舞，谢谢没打断我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '还在摸收割者的门道，有建议尽管说，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者治疗真难受，命比鱼人还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '喜欢这剧情，但收割者得慢一点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '暗影得加强，收割者就是差了点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '哀嚎洞穴挺好玩，就是卡得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '斯坦索姆怎么打都好玩，掉落也一直轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '还有谁喜欢暗影步？拉怪太方便了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '大家好！今天有人想去艾尔文森林刷点东西吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '多谢邀请！收割者诅咒我能出一份力，走，去怒焰裂谷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '暗影之拳打群伤太棒了，就是得保持距离');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '兄弟们！有人想聊剧情吗？我喜欢收割者的故事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '我在艾尔文采药，有人要吗？金币又不会自己长出来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '死亡矿井要帮忙，有人想打吗？怪我来控');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '还有谁觉得收割者玩起来太爽了？暗影步根本玩不够');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '我觉得收割者很难精通，但一开窍就特别爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '谢谢治疗，欠你一次，我放收割者诅咒压着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '熔火之心缺人，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者这职业真让人抓狂，哈哈我老被自己的暗影弄死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '我喜欢收割者把敌人的生命抽干，跟喝奶昔似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '真希望收割者除了拿剑砍还能干点别的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '有人缺哀嚎洞穴的吗？这儿简直是收割者自助餐。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '有没有发现收割者只能杀看得见的东西？暗影里的敌人太麻烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者这职业就像死亡与暗影的暗黑之舞，但太太太太难精通了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '没远程武器打怒焰裂谷真难受，不过那儿剧情多，气氛也好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '刚在影牙城堡偷了个箱子，谢谢收割者的潜行！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者就像暗影版猎人，我们也是啥都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '收割者太难玩了，一直复活太太太太烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '哈哈我太爱这职业了，上去就猛揍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '影牙城堡这boss我是真不会打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '巫医你在这儿到底怎么活下来的，笑死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 1, 0, 0, 0, 0, 10, '为了怒焰裂谷出个好装备我死了一次又一次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '黑暗深渊挺狠，但装备值……有时候吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '诺莫瑞根满满的回忆，就是这怀旧味');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者蓝条挺长，可感觉得喝掉一半的蓝药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '血色修道院全是邪教徒，我们干活倒省事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '监狱里卡得不行，简直像游戏在跟我们作对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '剃刀高地每次都好玩，就算团灭也一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '能习惯这硬核玩法的话，收割者非常猛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '在血色修道院出了件稀有，这趟就值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '剃刀沼泽是我的最爱，仇恨那么多，时间那么少');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '刚从药剂师那儿搞到一瓶解毒药水，太谢谢了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者治疗最惨，但真好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '有人能帮我打黑暗深渊吗？缺治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '嘿，有人缺监狱的队伍吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '诺莫瑞根真烂，侏儒咋这么烦人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '监狱能单刷，但你得会潜行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者人生：蓝没了，潜行也没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '大家好，今天掉落怎么样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '诺莫瑞根有没有队？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '大家好，谁待会儿想去黑暗深渊看看？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者……得练，这可不只是给搞不定暗影的人玩的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '我这巫医怎么加血啊？我彻底懵了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '监狱能快点打吗？我得赶时间。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '剃刀高地15分钟通');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '刚做完这条任务线，有人想在剃刀沼泽组队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '俗话说收割者就得永远放对法术。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '我烦死那些灵魂了，有些法术要的灵魂太多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '刚到24级，收割者的苦我算是体会到了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '谢谢大家在我拉怪翻车时救我，我有点莽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者跟猎人差不多，但干活要的东西多一倍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '灵魂进冷却，这心情你懂吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者这职业真不好上手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '祖尔有啥打法？我第一次打，巫医才玩了12小时');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '刚花了30分钟刷钱，缺草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '灵魂永远不嫌多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '剃刀高地，我来了，就是还没到，等我一下，我会到的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '我这辈子就是暗影命，40级再见哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '目前挺喜欢这职业，就是有些怪毛病');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '收割者人生：黑暗且满是灵魂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 2, 0, 0, 0, 0, 10, '这血色修道院搞得我心情低落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '奥达曼太爽了，我喜欢这地方，谢谢组我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '靠，玛拉顿的守卫太狠了，我得换好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '有人能教我怎么在黑石深渊活下来吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '巫医不好上手，但我们的buff最强，就这么一说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '厄运之槌东边挺难受，但装备值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '祖尔法拉克有技巧吗？我是收割者求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '坦克死了？行吧，那我就跟傻子一样乱跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我就爱刷钱，沉没的神庙就是金矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '黑石深渊是场噩梦，但值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '玛拉顿跟地狱似的，不过装备好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '想找个收割者打玛拉顿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '你信吗，我在这儿升了两级，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我是收割者，想问去厄运之槌最快的路怎么走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '谢谢复活，兄弟们，我歇会儿，10分钟后回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '谁能给我讲讲巫医啊，太绕了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '真不敢相信我不小心把整队人拉进祖尔法拉克了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我就喜欢收割者能一招秒怪，暗影打击太强了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '还有人在奥达曼卡吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我的收割者在沉没的神庙刷灵魂很棒，谢谢那些复活，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '需要收割者的话我能帮忙，尽管开口');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '黑石塔下层真难受，复活的人一堆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我的收割者在玛拉顿一死我就觉得自己很废，我讨厌暗影法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我是收割者，真没想到我还在学新东西，太带劲了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '缺个收割者打黑石深渊？没问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '收割者最棒了，我总是那个等人复活的人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '不管是不是老手，我都怀念以前那种团本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '当收割者当得真累，不过至少能收割灵魂，感觉还挺酷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我喜欢收割者，喜欢他们玩起来多简单。等等，我说错了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '厄运之槌太狠了，我需要治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '玛拉顿真绕，过了这么多年我居然还在这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '你说收割者要远程施法？近战永不为奴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '祖尔法拉克这么多小怪咋办，我快死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '黑石深渊，恶魔那么多，它们为啥这么恨我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '沉没的神庙，估计是完不成了，太久以前的事，我都忘了怎么打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '怎么就只有收割者得靠杀东西才能拿灵魂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '我还记得收割者刚出的时候，哇，那可太久远了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '我巫医都60了还是个菜鸡，两万小时了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '收割者很酷，我爱我这职业，别的职业难多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '黑石塔下层太大了，都看不到头，我就喜欢这样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '收割者的法术咋听起来像我成了鬼，可我不是啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '收割者在PvP里太超模了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '黑石深渊这些小怪搞得人真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '你得学会好好把握暗影步的时机');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '你知道收割者不走捷径，我们一天跑两趟黑石深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '沉没的神庙掉落太看脸了，能出货就算我走运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '哈哈，我的暗影步今天坏了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '有人缺收割者打祖尔法拉克吗？我还不确定去不去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '能组我一个打熔火之心吗？我准备好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 3, 0, 0, 0, 0, 10, '在奥达曼躲陷阱真烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '大家好，谁准备好打斯坦索姆了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者很强，但天哪真难精通');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '我需要熔火之心的攻略，有建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者的舞步最帅，又暗影又酷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '刚拿到我第一个暗影灵魂，感觉真好兄弟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '有人能帮我打奥妮克希亚吗？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '黑石塔挺难，可我喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者人生：永远在暗影里，永远有点孤单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '祖尔格拉布的收获太爽了，大丰收');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '我是新巫医，该用解毒还是治疗链');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '别忘了杀完在他们尸体上/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者人生就像好酒：复杂、深沉，越久越有味道');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者的吸血简直强到离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '马上回，得去多刷点灵魂。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '这儿有收割者要帮忙练暗影步吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '暗影法术太难伺候了，咋就这么难？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者治疗真难受，我的血条是空的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者就像夜里的忍者，突然冒出来偷装备，谢谢大家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '刚在奥妮克希亚把灵魂绑定的武器拿回来了，轻松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '我喜欢我的收割者，但有时候我也想当法师。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '大家好呀');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '经验不足抱歉哈，但我太爱我这瓶解毒药水了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者在此。就想在暗影里当个狠角色。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '黑翼之巢卡成这样，真是要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '通灵学院最近跟鬼城似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '我去，斯坦索姆的刷新时间太狠了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '装备是出了，可我的魂还留在斯坦索姆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '小心死灵陷阱……又来了……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者的灵魂最烂了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '刚从坟里爬出来，准备去黑翼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '卖奥妮克希亚车，有意私聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者不过是花哨的刺客，但我们的造型最酷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '困得不行，但还是想刷祖尔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '灵魂绑定搞得有点乱，灵魂不够走不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '我的DPS能比冰法还高');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '黑石塔上层就是个死亡陷阱，小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '嘿，今晚熔火之心就差个奶，有人有空吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者想玩好很难，要是简单谁不会啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '又在奥妮克希亚复活了。又是。我爱死这巢穴了，我发誓我没在自言自语');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, 'DPS是关键，兄弟们。你们乱跑，全队都得死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者最擅长衬托别人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '等我一下，马上回来，先刷点灵魂。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者基本就是鬼，偷不了装备，但能偷心，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '一开始是难学，但我的图腾真让我骄傲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '新的声望刷得真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '哇，我爱收割者。有时候想能不能一个人搞定。大概不行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 30, 4, 0, 0, 0, 0, 10, '收割者的日子全是阴影，但至少帅，而且装备最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '欢迎来到丛林，不过是狂暴丛林里又一个原始使');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '有原始使当T，哀嚎洞穴太简单了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '可惜没装备，但死亡矿井这波团战打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '盯着点远处，跟原始使一起抗怪可不容易');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '在影牙城堡拉仇恨，原始使是头野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使抗怒焰裂谷太轻松了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '这剧情太厚实了，几乎能看见世界在眼前变化');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '需要帮忙尽管说，外面给我们加血的多了去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '在影牙城堡，原始使能全抗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '记住，在死亡矿井边抗边跑比站着硬刚强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使和怒焰裂谷简直天生一对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使不只是T，还是头驮兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '哇这原始使职业太猛了，我等不及去抗怪了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '大家好，我刚玩原始使');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使的技能超酷，就是难学');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '还记得死亡矿井的美好旧时光吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '还有谁跟我一样就爱原始使的自然那一面');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '当原始使感觉超强，什么都能干');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '巫医就是队伍的灵魂，真字面意思，全靠部落魔法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '刚试了怒焰裂谷，死了好多次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '为什么我觉得只有我看不懂这些技能');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '还有谁在刷哀嚎洞穴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '影牙城堡真是满满的回忆，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '第一次用原始使抗怪，轻松得很');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使怎么升级最快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '谢了刷兽皮的建议，我原始使刚入门');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '有人知道哪刷兽皮好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使抗怪挺简单，记得开野性之怒别死就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '刷兽皮有点无聊，但经验还不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '巫医为啥辞职？因为他受不了图腾折磨（totem-ment）哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '想进哀嚎洞穴吗？我可以T');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '谁能告诉我这些野兽形态在哪搞？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '我在找原始使升级的好办法，有建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '跟原始使的技能死磕，我本以为这挺简单的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '可惜猎人没我们想得那么需要我们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '我现在上手了，关键就是管好怒气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '这个是不是原始使当T最好的那个？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '刚开始用原始使抗怪，超好玩，但技能追着放真累');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '各位，原始使循环打不顺就多练技能优先级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使的怒火比二十人大军还猛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '斯坦索姆打不过的来跟我们一起，让巫医施个法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '影牙城堡通了，谢了兄弟们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '坦克真难玩，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '怒焰裂谷的BOSS怎么打啊，我们该干嘛？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '没事兄弟们，祝刷得顺利');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使抗怪不容易，但值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '原始使的怒气让你能当T，但我们得更频繁地被奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, '技能用对了原始使是最好的T，用不对就是最烂的！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 1, 0, 0, 0, 0, 10, 'GG，明天死亡矿井见');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '原始使笑死，我的治疗怎么是头熊哈哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '监狱缺T，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '有时候是有点绕，但玩久了就会了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '嘿，贪婪之群对原始使值吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '原始使等不及对那群鱼人狂放獠牙了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '为什么带宠物的时候暴击感觉更爽？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '剃刀沼泽，还有谁觉得自己像兽王？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '原始使得多点血，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '宠物跟BOSS玩捡球时，原始使的日子真难过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '监狱挺简单，诺莫瑞根就是烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '马上回来，得重洗原始使天赋，再训下新熊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '我在血色修道院老是多拉一堆怪，谁来一枪崩了我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '剃刀高地就是没完没了的泥巴和泥怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '黑翼之巢可能得备一堆药和治疗，但咱们搞得定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '哈哈原始使在诺莫瑞根卡住了，队伍直接把他扔了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '只要别见到怪就拉，剃刀沼泽很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '得再来点法力药水，我在黑暗深渊没蓝了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '黑暗深渊全是水和鱼，正合原始使的胃口');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '打起来宠物却睡了，剃刀沼泽最惨莫过于此');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '你们太棒了，监狱马上就能打完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '治疗药水没了。我真爱这游戏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '原始使嘛，对吧？爱抗怪，可那些DOT真难维持。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '监狱组队，请自带控，谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '诺莫瑞根怎么这么多陷阱？烦死了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '我爱治疗，但不得不说，管那么多药水真要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '哇，血色修道院好难，需要更多治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '哈哈，我差点忘了原始使的技能，蓝耗好高，好痛苦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '马上回来，得吃点东西，血不多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '现在练原始使的T还是奶比较值？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '黑暗深渊GG，刚那波挺好玩。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '知道我怀念啥吗？就是以前随便打老团本。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '得刷点钱换新装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '能跑要坐骑干嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '原始使不是啥都能T，给我们点时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '终于拿到坐骑了，舒服');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '这掉落我太爱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '咱们肯定是这儿最全能的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '奶妈们，谢了在血色修道院保我命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '有人要帮忙打剃刀高地吗？找我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '刚在剃刀沼泽出了件好货，谢天谢地');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '这游戏的剧情太棒了，我爱死它了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '原始使小技巧：用宠物来控场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '这游戏真让人怀旧，还记得猎人当神的日子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 2, 0, 0, 0, 0, 10, '狂暴熊形态我最爱，太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '树皮炸开那一下超带感');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '等不及再去奥达曼抗怪了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '恐怖熊正面糊脸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '得，我又困在黑翼之巢了，身上就剩几个图腾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '我感觉自己像棵树');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '抗这群怪跟赶猫一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使的治疗其实挺强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '恐怖熊让我日子好过多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '马上回来，得去找个新T');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使在此。有时候觉得自己不像T，倒像个移动动物园。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '当原始使，奥达曼就是个笑话');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使治疗就是放宠物然后跳舞，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '还有谁觉得原始使得样样都顾上，不然就直接躺平？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '嘿，黑石找人组队，最好别来那种在祖尔法拉克退队的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '熔火之心加血简直轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '真对不起我错过了祖尔法拉克前十五分钟，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '厄运之槌一向有点乱，但我们还是能过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '奥达曼这副本一直都是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使就是T里的查克·诺里斯。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使在此。不自奶我就得死。多谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '没合适的奶，黑石塔下层真是遭罪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '大家好，有人组祖尔法拉克吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使才是真MVP，前提是你不嫌抗怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '谢了治疗，给我一秒找下我的野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '还有谁在玛拉顿最后那个BOSS那卡住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '巫医图腾加血我到现在都看不够，太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '奥达曼是噩梦，但值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '哈哈，刚在黑石深渊被蛇陷阱坑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '嗨，还有谁就爱用原始使抗怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '黑石塔下层很凶，但我们能行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '我觉得厄运之槌可能是我最爱的副本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '有时候我希望自己能彻底变成野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '谢邀请，沉没的神庙再来一次也行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '大家好，奥达曼要T吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '谁有玛拉顿的好打法？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '早上好各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '有咱们的部落魔法，通灵学院轻轻松松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '兽王和自然魔法太酷了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '黑石深渊疯得很，先跟你说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '谢邀请，希望我抗怪别搞砸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '祝你们刷本顺利，别忘了拉一起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '嘿，打完别忘了跳个舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 3, 0, 0, 0, 0, 10, '原始使抗怪有点无聊，但回报很高');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使真是一团糟，连别把整个副本的怪都拉了都指望不上，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '今晚通灵学院谁缺T？先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '奥妮克希亚我就专心奶，这样不容易拉仇恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '黑翼之巢刷新太狠了，干嘛要等这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '刚打完一趟斯坦索姆，装备照旧好拿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '刚被人抢了装备。不过至少是件白装，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使就像什么都要的猎人，要蓝要血还要宠物开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '祖尔格拉布抗怪挺痛苦，但有好奶我就能行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '黑石塔上层怎么拉最好？不想把怪全引了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '你想跟原始使跳舞，但不行，我们不会跳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '奥妮克希亚每次灭完为什么都得等奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使AOE确实强，就是蓝不够啥都干');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使的日子啊。抗一堆怪，宠物打四分之一的伤害，永远这么好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '你要是在旁边看见个元素，多半是我召的。抱歉但不抱歉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '奥妮克希亚有什么打法？火焰阶段我有点虚');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '这延迟烦死了，法术都放不利索');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '记得刚玩的时候，我以为自己会当个大大只的圣骑士。现在我是原始使，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '黑石塔上层挺难，但熔火之心更难。带好零食和药水。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '通灵学院总是各种整活，但谁不喜欢来段/dance呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使基本就是大自然的保安，随时准备干架');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '有人要帮忙打祖尔格拉布吗？抗怪我包了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '我超爱原始使的背景故事，当自然之手的感觉真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '小心抢装备的，我对这场黑翼之巢有点不祥的预感');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '抗一堆怪的时候，我的宠物啥都吃就是不咬头目');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '当那个拉住所有人仇恨的人永远好玩，让他们都盯着我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '谢了奶，没你我们真过不去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '图腾插好，走，刷金去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '奥妮克希亚还差一个T，有原始使有空吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '我来祖格就是为了声望');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使抗怪很强，可惜拦不住他们像Leeroy那样冲进去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '斯坦索姆很凶，但奖励很香');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '你觉得原始使的新技能咋样？我爱死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '嘿，谁想全通黑石塔上层？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '哈哈，熊一出来我连怪都打不中');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '原始使不只是个T，是一个半的T！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '这不是我第一次团本，但这是我在MC第一次没被秒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 31, 4, 0, 0, 0, 0, 10, '哇原始使真得练练准头，这职业想打中东西太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '巫医日常：先奶自己再奶别人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的日子就像追自己的影子，祝你好运！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师刷钱有啥诀窍，求蜘蛛点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师在死亡矿井贼没用，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '我发誓今天装备之神恨我，就掉了几个铜锭，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '你们玩符文大师怎么才不卡？我的游戏快死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师：给那些喜欢放完技能就跑的人准备的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '还得刷点金属做符文，还有人组队吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师在此，谁要打怒焰裂谷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '还在研究符文大师的输出循环');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师：好不容易弄到个好符文，然后手滑丢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '我怎么老拉仇恨？大概是太强了吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '谁知道我的符文大师技能为啥老失败');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师也会跳舞 /dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的日子就是个大符文拼图');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '又卡在石头上了，哈哈符文为啥恨我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师升级有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '死亡矿井锁本了，缺奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师在此。能给敌人放技能，给自己放，偶尔还给宠物放。好日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '还有谁在研究符文大师怎么点天赋最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '跑掉的灵魂最烦了，为啥我绑不住它们？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '跑得像团本玩家，说话像奶妈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '野蛮人是史上最强坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '有人帮打奥妮克希亚吗？还差几把');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '在怒焰里横冲直撞，找不到我的灵魂。没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '为了想要的符文旅牙城堡刷了五十次？这叫脸黑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的技能读条慢得要死，感觉都能泡杯茶了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师循环有建议吗？每次感觉都像在做仪式。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '刚单刷了一堆狗头人，不打鱼人的时候符文大师的日子真不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '死亡矿井对符文大师挺难，但装备还行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的设定太棒了，感觉跟我的灵兽很有共鸣');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的符文怎么保持充能？我总感觉是空的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '哀嚎洞穴太好玩了，就爱那些随机遭遇和迷路。谢邀请。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师在副本里得加强，我觉得自己是奶不是法系');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '在菲拉斯采药，有人要吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '怒焰裂谷太好玩了，就像坐过山车穿过岩浆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '得跑趟旅店，还有人要啥吗？想找人聊聊天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '影牙城堡，我爱这气氛，像哥特恐怖故事。谢邀请');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '这些符文怎么用来治疗？有点懵');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '有人想跑趟哀嚎洞穴吗？可以去找隐藏宝藏，或者干脆赚点钱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的日子，为啥符文总用光');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '我想转符文大师了，终于搞懂灵魂魔法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '太谢谢你了，这破地方真难搞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '哀嚎洞穴？又来？哈哈行吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '怒焰裂谷是我最爱的副本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '黑翼之巢挺磨人，但装备值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的技能真是……哇。跟个法术工厂似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '死亡矿井数到三就开，准备好跳舞了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '影牙城堡比我记得的简单多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 1, 0, 0, 0, 0, 10, '符文大师的技能需要帮忙，到底是哪些？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '黑暗深渊里的法师怎么应付？我感觉奶还没放出来就死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师的日子啊，每次被狠揍都感觉少了个灵魂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '笑死，我刚觉得能放了，符文就没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '有人知道稀有符文怎么刷吗？血色修道院那几个老是出问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师：别人问你怎么老没蓝，但你能召出让它们眼红灵魂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '是我错觉还是剃刀高地就像符文大师的召唤训练场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '通灵学院清怪中，有人要帮忙打怪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '我觉得玩符文大师有点吃亏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '血色修道院卡得厉害，技能乱飞，还把灵魂召出来跳舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '我是新来的，你们怎么在放符文和用灵魂之间找平衡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '真不敢信我在剃刀沼泽被同一个刚把装备全刷走的猎人抢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文打AOE超好玩，但我老忘了续');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师在此，剃刀沼泽组队，谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '剃刀沼泽是我最爱的刷本地点，来钱快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '有时候希望自己能一整天狂刷治疗符文');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '哇，黑暗深渊真是岁月不饶人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '诺莫瑞根是符文大师单刷的完美地点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '谁能帮下忙，我在祖尔格拉布一直死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师在此，监狱组队，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '血色修道院真是各种折磨，但装备不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '我爱符文大师的灵魂真像个向导和老师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师的日子超好玩，但读条被打断真让人抓狂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '我准备单刷血色修道院，需要就喊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '还记得我第一次跑诺莫瑞根，好怀念');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '黑暗深渊对符文大师就是噩梦，边躲边奶简直是健身');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '刚拿到坐骑，满世界跑真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师得时刻警觉，灵魂之怒可不等人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '监狱还差三个，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '上层黑石塔永远带劲，就算有那些谜题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '这个符文大师不太会奶，但它是我最爱的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师的灵魂是什么情况，跟嗑药的迷你宠物似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '剃刀高地早晚要了我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师的技能挺好玩，就是有点慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '有人要打监狱吗？我第一次来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '剃刀沼泽是杀手，字面意义上的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '黑暗深渊现在简单了，该去一趟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '可惜我不需要灵魂，抱歉各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '诺莫瑞根是我最爱的副本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '血色修道院全是简单任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 13, 4, 0, 0, 0, 0, 10, '熔火之心感觉像没完没了的地牢，但最后总能打通');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '有人要符文大师打剃刀高地吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '符文大师的治疗太强了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 2, 0, 0, 0, 0, 10, '我觉得我爱上剃刀沼泽这个副本了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '求祖尔法拉克队伍，缺T缺奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '真不敢相信玛拉顿又要通了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师的日子：放符文，躲灵魂，重复');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '我爱这游戏的剧情，但黑石塔就是地狱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '奥达曼我得找个T，又得一个人跑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师挺难的，但有灵魂就值了，小意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师治疗很难，保住全队也难。我讨厌沉没的神庙，我想跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '等不及让双刀舞起来了，Felsworn 万岁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师输出很棒，但真希望能更好地控制灵魂。这趟再来一次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '这队伍打黑石塔下层太难了。马上回来，得歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师的增益太关键了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师好玩，但奥达曼更好玩，没个好队真想不到有多难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '我爱祖尔法拉克的背景故事。灵魂很吓人，血少千万别往这跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文很厉害，但保持全满真麻烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '嘿，有人要跑玛拉顿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师在奥达曼跟法师们一起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '谁能帮我弄下这破符文');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '大家好，就在刷些新符文');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '怒焰裂谷？不如叫怒焰刷本，谁还讲战术');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师的治疗就是爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '只要让符文保持满就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '祖尔法拉克有人要符文大师吗？缺个T');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '今天符文大师的治疗感觉有点不够看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '有人知道符文大师的天赋PVP也厉害吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师的技能挺刁钻，但我爱那些灵魂增益');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师在黑石深渊抗怪有点像个笑话');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '奥达曼的卡顿你们怎么撑过去的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '还有谁为符文大师的蓝量发愁？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '黑石塔下层就是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 的人生就是双刀，我等不及了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师有点像玻璃大炮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '得去通黑石深渊拿那身香装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师 /dance，因为我跑不快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师技能一直卡，我发誓这职业不只是卡和没蓝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '嘿兄弟们，有谁要符文大师去奥达曼玩玩？不过符文BOSS我先定了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师为啥带梯子去祖尔法拉克？因为他听说灵魂都在高处。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '马上回来，得去采点草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '你好，有人要帮打玛拉顿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '符文大师的日子：当你发现自己符文比脑子还多。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '黑石塔下层是符文大师的噩梦，但靠着灵魂小伙伴们我们还是撑过来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '怎么这么卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '刚升到4级，这双刀太猛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '我今天当农民啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '真希望灵魂们偶尔也放我一马');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '哈哈我又把符文循环打乱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '有人去沉没的神庙吗？我保证不淹死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '我平时不跟公会一起打，不过你要是缺人，我可以去趟黑石塔下层');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '厄运之槌真够离谱的，不过至少这一趟符文没少拿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 3, 0, 0, 0, 0, 10, '打得漂亮，符文大师就是魔性，不过别问我咋回事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '马上回来，我得去冥思一下我灵魂里的符文');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '哎，谁懂灵魂链接啊？跟别的链接有啥不一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '通灵学院挺简单的，就是得有人帮忙清小怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '该死的延迟，差点把手指弄没了，现在又回来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, 'PvP用哪个符文最好啊哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '想打熔火之心吗？求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师的日子就是十二点伤害加点治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师有时候练级是真难，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '有人找熔火之心的队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师的法术跟诗一样，就是难多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '谢谢奶，符文大师，你才是真MVP');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师是挺让人头疼的，但奶起来也是真强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我在去黑石塔上层的路上，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '在斯坦索姆刷金，想来的随便来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 一生推，双刀到手，准备开干');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '今天制皮挣了一百金，还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师是最强的职业，有符文在手还要啥查克·诺里斯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我在黑翼之巢一直死，得多练练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '谢谢在通灵学院帮忙，符文大师太猛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '欢迎来Conq！有啥最快的法子把我的符文搞上去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '谢谢大伙帮忙，我欠你们一个人情');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我这个符文大师，就是个行走的挨打海绵哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '没事，乐意帮忙！还缺啥跟我说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '大家好，我刚到六十级。黑石有啥好刷的吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '曼克里克的媳妇跟符文大师似的，总能赶不上趟儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '等不及用我的双刀了，Felsworn 永远的神');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师搓法术，就跟手上抹了油似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '黑石塔上层，有人想来凑个热闹吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '黑翼之巢通了吗？有人想跟我一起打吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我在去通灵学院摸装备的路上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我得戒了用/dance来压住符文暴走这毛病');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '哈哈我老是搞混符文组合，结果做出个三明治来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '谢谢在斯坦索姆给我奶，差点把自己玩死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师要啥治疗啊，搓几个符文就瞬间回血了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师：又想放法术又想扛，结果两样都不咋地');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '谁知道怎么快点把符文精通练上去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '双刀刚上身，4级 Felsworn 一生推');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我昨天想单刷黑石塔上层来着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '奥妮克希亚那场得多几个人帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '哇，这些副本还是这么难打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '符文大师玩起来真难，但练明白了特别爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '今晚有人去祖尔格拉布吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '想去通灵学院刷点声望，谁要来？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '我连自己想放啥法术都记不清了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 32, 4, 0, 0, 0, 0, 10, '咱们团还需要再来个猎人吗？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '我能感觉到恶魔能量在血管里翻涌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '双刀求指点，刚玩这个，太帅了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '恶魔之力打起来是真带劲，但我还得练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '那双刀让人觉得自己活着，不过得磨磨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '我就走 Felsworn 这条路，双刀永存哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '刚才那波拉怪得多给点治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '哀嚎洞穴，求组队，缺坦缺奶，别客气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '我在怒焰死了上千次，数都数不清');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '这边 Felsworn，双刀，要装备直接找我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '死亡矿井这边，求组队，求带，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 是真难玩，但好玩，所以无所谓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '死亡矿井这延迟，又恨又爱哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '跳舞吧，装备全是咱们的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '谢谢加血，血回来点儿真舒服');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '哀嚎洞穴求帮忙，不想再死一次了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '刚被ninja了装备，gg，继续刷吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '你怎么跑这来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '谢谢指点，我超爱 Felsworn 那套舞步，感觉自己就是个恶魔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '这儿还有像我一样的 Felsworn 吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 输出太强了，只要你别被那股力量冲昏头');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 这职业挺适合新手，法术玩着玩着就熟了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '大家好，新 Felsworn，爱死双刀了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '哈哈我怀念我1级那会儿的猛劲，真是个野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 能抗影牙城堡吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '哀嚎洞穴的怪我基本都能拉，但一失手就是地狱火');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '嗨，求一队人一起清怒焰裂谷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, 'Felsworn 要盯上一场架，那就说再见吧，他全力冲了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '我是野蛮人，有怒气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '该看看我的新技能，19级，怪全是我的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 1, 0, 0, 0, 0, 10, '嗨我是 Felsworn，谁有多的药水？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, 'Felsworn 的人生就是双刃剑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '真不敢相信我又得去抗黑暗深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '好极了，我的恶魔之力又在冷却');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '刷金中，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '监狱已清，下一趟缺治疗，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '就希望这刷怪速度能快点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '先从邪能折磨里歇会儿，在诺莫瑞根把我坑惨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '剃刀高地拉怪简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '野蛮人怒气真好使');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '我说真的，血色修道院满队就简单多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '黑暗深渊有点挤了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, 'Felsworn 把我血打低了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '你都不敢信，带个 Felsworn 打剃刀高地有多轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '血色修道院稍微配合一下就是脚打。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, 'Felsworn 挺难玩的，不过双持真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '给那 Felsworn 试了新循环，结果我还是菜。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '诺莫瑞根小菜一碟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '真希望咱们的拾取制度别这么看脸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '猎人在血色别再送了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '拉怪还行，太简单就没意思了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '剃刀沼泽全是虫子，还不是好玩那种。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '我爱双持，但胳膊是真酸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '哈哈，为啥大家都觉得猎人啥事都得靠宠物？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '适应起来得花点功夫，邪能之刃可不是闹着玩的！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '监狱5分钟后开，缺输出吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '这公会得多来几个 Felsworn，咱们的恶魔太帅了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '马上回来，去刷点侏儒装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '不知道血色那帮武僧为啥一直刷，反正不难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '嘿，谁能分享下剃刀沼泽的地图？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, 'Felsworn 都这样：再来一下，我扛得住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '这洞里怪太狠了，小心仇恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '掉落呢？地上没有啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '血色修道院的新任务求帮忙，不急，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '今晚谁想打黑暗深渊，我来抗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, 'Felsworn 的人生就是双持，跟死亡共舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '刷剃刀高地太爽了，出了点装备，就是还有延迟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '恶魔有点压不住了，有 Felsworn 老手给点建议吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '黑暗深渊今天挺安静，没事兄弟们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '我说这图的刷怪时间比侏儒的一天还长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '监狱那趟很顺，简单模式');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '恶魔之力挺累人，马上回来，先歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '在诺莫瑞根挖点矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '黑暗深渊很简单，别淹死就行，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '有些人啊，能求多少帮助就求多少……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '剃刀沼泽要把我弄死了，字面意义上的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 2, 0, 0, 0, 0, 10, '这就是拿双持武器的 Felsworn，艾泽拉斯的又一天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, 'Felsworn 的苦是真的苦，但值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '谢谢buff，太感谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '两个 Felsworn 打祖尔法拉克轻轻松松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '听着你玛拉顿还缺俩人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '厄运之槌还缺三个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '祖尔法拉克人越来越多了，谢谢分装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '沉没的神庙没看着那么吓人，就是小心被ninja');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '搞了把新斧头，几乎抡不动');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '这些怪刷得也太疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '坦克比你想象的强，信我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, 'Felsworn 到高等级加血就是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '去把那个法师的装备弄过来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '50级满力量的 Felsworn 真要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '没满队我可不想进下层黑石塔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '这一步不该卡住才对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '抗这些怪太痛苦，直接去厄运之槌吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '这地方毫无道理，拿了装备就走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '你以为法师能给咱们加血？想错了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人干不了这个，得加点怒气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '大家好，谁能说说奥达曼怎么进？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '嘿，还有谁准备好冲祖尔法拉克了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '有人知道去玛拉顿最快怎么走吗？多谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '刚升50级，激动坏了，要去打沉没的神庙！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '有 Felsworn 老手愿意教教我吗？不着急');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '黑石深渊是真折磨，但至少武器够意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '哇，感觉 Felsworn 就是专门用来克猎人的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '这么多怪，下层黑石塔怎么出去啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '有恶魔之怒，谁还要盾啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '血咒到了对的人手里简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '又卡了，去喝口水，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '祖尔法拉克太简单了，都不用我邪能之刃');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '马上回来，去弄点邪能');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '哈哈这 Felsworn 就是终极AoE机器');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '在奥达曼被ninja装备都烦透了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '我的血咒怎么就miss了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '在下层黑石塔跟死人跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '没点邪能加成，玛拉顿挺难啃');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '我爱黑石深渊，但卡在柱子后面我是真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '捡装备的时候真该学学那段舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '厄运之槌对我的技能冷却就是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '监狱有点太挤了，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 3, 0, 0, 0, 0, 10, '我真得找个靠谱治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '大家好，Felsworn 怎么搞装备有人给点建议吗？我是新手哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, 'Felsworn 拉仇恨最烂，但至少我不容易死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '马上回来，又得去捡尸体，真喜欢 Felsworn 这跑速');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '嗨，有人要打斯坦索姆吗？就差几个人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '还有谁被刷怪搞烦了？太难顶了兄弟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, 'Felsworn 抗怪最牛，但咱们自愈是真拉胯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '兄弟们，今晚谁打熔火之心？我要那条腰带');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '真希望咱们的血腥狂暴也能给法师和萨满，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, 'UBRS的刷怪时间我受够了，跟翻了三倍似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '怒气有点烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '大家好，今晚有人想组队打祖尔格拉布吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '谁能再讲一遍拾取规则？我老是分不到东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '没错，我是 Felsworn，双持恶魔之刃，唯一能把拉仇恨玩成艺术的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '有人想来趟斯坦索姆吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '上层黑石塔，咱们来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '求人帮忙打奥妮克希亚？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '这儿有术士能拉我们去通灵学院吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, 'Felsworn 是唯一能把拉仇恨拉成跳舞的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '晚上求人帮忙打祖尔格拉布');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '被邪能过载弄死都烦透了……又来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '剃刀高地的刷怪最爽，掉落轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '邪能剑真是离谱哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '还有谁觉得邪能过载该出个简单模式？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '在黑石深渊刷金，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '有人多一把法师之刃给 Felsworn 吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '奥妮克希亚最后boss能帮下忙吗，谢谢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '通灵学院一个人打真烦……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '黑翼最后boss求帮忙，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '祖尔格拉布挺好玩，就是别站火里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '在UBRS刷材料，缺个战士拉仇恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '刷金挺无聊，谁想来趟通灵学院？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我来晚了，抱歉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '对面没治疗的时候，Felsworn 就是这游戏最强的东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '谢谢指点，别客气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '曼克里克老婆这梗现在比刚火那会儿还火');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, 'Felsworn 打斯坦索姆的亡灵简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '猎人永远一上来啥都要，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '马上回来，去趟银行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '我讨厌去祖尔格拉布，bug太多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 14, 4, 0, 0, 0, 0, 10, '熔火之心挺磨人，但为了紫装值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '哇，我的陷阱触发得比我妈比赛日的热狗还快。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '还得再升几级才能像大佬一样单刷怒焰裂谷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我是野蛮人，习惯怒气了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '哈哈没人信猎巫人能加buff，但我可没混');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '我去又延迟，刚从哀嚎洞穴掉线');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '影牙城堡要成噩梦了，但跳舞的时间总还是有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '真不敢信我错过了上次刷新。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '猎巫人招数挺多，但总有提升空间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '真希望有把更好的强弩，感觉像拿小石子打鱼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '为了件掉落至于拉一群怪吗？总是猎人得去管装备。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '哇我的猎巫人越来越上手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '怒焰裂谷找那些兽人，求帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '我爱这职业，手枪射击太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '稳住的话哀嚎洞穴20分钟通关，冲冲冲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '跟我预期不一样，不过还是很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '影牙城堡挺好玩，就是有点绕');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '谁能指下西部荒野最好的刷点？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '该死的影牙城堡怪，一波接一波');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '能把他们的魔法返回去，猎巫人是真好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '求组队打死亡矿井');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '谢谢教我反弹他们的法术');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '采药还是哀嚎洞穴最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '刚第一次把法术反弹到兽人身上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '谁能告诉我艾尔文森林哪儿金多点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '看来我得先玩一阵猎巫人，翻诅咒真好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '单刷血色修道院真难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '猎巫人哈哈，刚发现咱们能把诅咒返回去，太好用了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '有人知道哪儿刷布效率高吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '真希望能看见我的诅咒，有法术能显示我诅咒的目标吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '影牙城堡刷本中，缺治疗药水，谁有多的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '我很爱当猎巫人，但我的恶咒打鱼人怎么这么软？？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '猎巫人在副本里是真亮眼，就是小心别一次拉太多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '猎巫人到底用啥武器好，手枪还是弩？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '刚搞明白用哪个法术能让敌人变慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '哀嚎洞穴对猎巫人是噩梦，一次怪太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '猎巫人有技巧吗？我法术循环老打不好，有攻略吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '哈哈，我想跳舞，但不知道咋弄');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '死亡矿井清得轻松，就是刷怪时间太长，有点烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '我爱猎巫人，但他们的技能真不好精通');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 1, 0, 0, 0, 0, 10, '猎巫人狂刷诅咒最爽哈哈，我一半时间都看不见目标');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '今天下午终于打到黑暗深渊，太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '猎巫人的恶咒在诺莫瑞根真派上用场，谢谢组队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '唉，猎巫人的弩还得再多练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '哈哈哈刚被一只怪从剃刀沼泽一路追，回来真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '吓死我了，以为手枪要坏，运气不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '哈哈猎巫人得备好多弹药，谢谢提醒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '剃刀高地就是地狱，我要治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '有人知道去监狱最快的路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '猎巫人就像猎人，只不过带魔法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '哈哈我就爱这种，想去捡装备结果人没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '我爱血色修道院的新剧情，别把老的忘了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '猎巫人的法术让一切变简单，然后又没那么简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '黑暗深渊缺治疗，求求了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '诺莫瑞根怎么大家都在死，我的恶咒明明挺好使');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '剃刀沼泽怎么就找不到队？我缺治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '大家好，看到几张熟脸真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '采药中，顺便冲炼金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '真希望这些怪刷快点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人的人生啊，没啥好抱怨的，就是一场怒气狂欢！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '猎巫人挺好玩，但那堆恶咒真难管');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '血色修道院求组，再缺一个治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '好极了，又是一个魔免怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '谁有多余的坐骑卷轴，随意捐赠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '大家好。猎巫人别忘了大法术那10分钟冷却');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '马上回来，去黑暗深渊清点小怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '破延迟，把我射击全搅了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '有人缺人打剃刀沼泽吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '为啥找个好治疗永远这么难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '谢谢拉我打诺莫瑞根，等不及再见那些侏儒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '哈哈，我老拉太多怪，然后怒气就没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '谢谢组我，猎巫人输出是真强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '刚拿到第一只坐骑，终于跟上大家了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '黑暗深渊还行，别忘带水下呼吸，那儿水深');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '剃刀高地太带劲了，小心那些秃鹫！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '我爱我的强弩，我九成伤害都靠它');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '猎巫人挺难的，但好玩，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '我就是个猎巫人，来打猎的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '大家好，幸会，我是猎巫人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '行啊，我不是治疗，但我乐意抗，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '监狱有好队就是脚打，就是别一口气全拉了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '黑暗深渊求带，有人有空跑一趟吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '诺莫瑞根就是噩梦，陷阱太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '跟黑暗魔法共舞也没那么糟，就是别一次拉四个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 2, 0, 0, 0, 0, 10, '血色修道院永远好玩，就是注意拉怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '哈哈真不敢信，我因为在那儿耍猎巫人手枪，整场boss战都错过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '50级冲祖尔法拉克，心跳停不下来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '不想承认，但猎巫人就像个得自己解开的谜题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '有人要帮忙过玛拉顿吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人难玩，但有回报');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '下层黑石塔，10分钟后开');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '熟了法术，现在纯简单模式。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '剃刀沼泽一堆眩晕，真恶心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人最多也就十个法术哈哈，谢谢你们搞得这么简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '有人要奥达曼帮忙吗？谢谢，说一声就行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '刷怪时间太长了，我说我真要疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '祖尔法拉克、下层黑石塔、厄运之槌，我都爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '想刷玛拉顿，但周围一个人都没有。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '找不到路？问我，我熟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '哇延迟爆表，太难受了兄弟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '黑石深渊根本没个头');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '哈哈，需要的话我这猎巫人能帮你抗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '作为猎巫人，我都不知道该先刷手枪还是陷阱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '有人有刷钱建议吗？我想攒点金币去诺莫瑞根');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '哈哈奥达曼拉怪的，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '黑石深渊就是无尽的刷，但咱们还是接着干');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人的法术，我跟你说，真该更新下界面');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '黑石深渊是无尽的死亡陷阱，但我看得出它让我变强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '玛拉顿缺两个治疗，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人是反弹法术之王');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '我觉得猎巫人这职业在玛拉顿最强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '我怀念以前的玛拉顿，又简单又快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人应该根本不用歇吧哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '黑石深渊是去厄运之槌前的最后一站');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我这怒气条现在像过山车');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '真希望有人教教咱们这猎巫人把恶咒用对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '一枪干掉俩，猎巫人赢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人不是特别强就是特别菜，没有中间档');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '厄运之槌求一队人，有人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '德鲁伊是不错，但谁能抗拒弩呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '又丢了一把强弩，我说肯定有猎人专门盯着我装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '奥达曼对新手是噩梦，但猎巫人准备好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '还有人怀念以前不用操这些心的日子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '玛拉顿开团了，再缺几个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '猎巫人可能挺难玩，但他们永远挥着武器冲上来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '怒气挺有用，不过我啥都能弄坏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '玩野蛮人有啥建议？我上手了但老死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 3, 0, 0, 0, 0, 10, '刚被人抢了装备，真烦没拿到任何战利品');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人的复活运气真是烂到家了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '斯坦索姆还开着吗？最近有人打黑翼吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '你怎么老是对装备这么着急？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '有人能教我怎么更有效地用手枪吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '我挺喜欢手枪的，但我需要一把新弓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '这卡得也太狠了吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '我们的团本里需要更多猎巫人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '我实在应付不了这么多敌人一起上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人怎么这么帅');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我老想在战斗中 /dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '我在通灵学院被人抢了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '谢谢大家在熔火之心的帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '打完那么多黑魔法遭遇，猎巫人也得歇歇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '刷新这么多，感觉像在跑马拉松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '你知道大家怎么说，猎巫人 roll 装备的运气最差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人的生活：把诅咒往自己身上甩，还玩得特别开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '有人知道猎巫人能不能在拍卖行买到更好的箭吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人怎么没有跳舞动画，谢谢提问');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '有猎巫人队伍在，我们总能翻盘');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人对自己用诅咒会怎么样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我老死在剃刀高地同一批怪手上，有啥建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人很棒，但转化诅咒是门真艺术');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '斯坦索姆就是个噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '斯坦索姆太熬人了，我得歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '对付猎巫人的恶咒有什么技巧吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人就是脾气差的圣骑士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '我队伍缺个猎人，还差1人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, 'gg，谢谢各位，熔火之心这趟太轻松了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '哇，斯坦索姆跟曼克里克的老婆差不多难搞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人有点“我瞄不准”的毛病，不过至少法术看着挺帅');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '有没有人教教怎么快速刷金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人最好，因为能拿大武器砸东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '刷奥妮克希亚的鳞片，缺2人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人挺简单的哈哈，但为啥每个怪都要爆炸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '马上回来，鱼漂有动静了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '有好猎人帮忙，抗黑石太轻松了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人啥都要，连我妈做的菜都想要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人可真难练，我发誓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '今晚通灵学院？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人能把诅咒变祝福，反过来也行哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '马上回来，我去上层黑石塔拿装备，gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '熔火之心挺难的，但用这个职业就是轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '在剃刀沼泽采药最赚钱，就是小心怪！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '我爱这游戏，这里面有太多回忆了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '斯坦索姆真让人怀念');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '黑翼之巢是我最喜欢的团本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '猎巫人很好玩，但真难上手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '拼错了抱歉，谢谢你告诉我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 15, 4, 0, 0, 0, 0, 10, '就希望这游戏能更有意思点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者升级没那么好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '我的法术怎么这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '哈哈，我的风暴使者被闪电劈了，两次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '哇，风暴使者近战真的烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '有人组黑暗深渊吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '哈哈，风暴使者得给我把法术加强一下');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '嘿，我有个风暴使者的好技巧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '刚练了个风暴使者，有技巧吗？求组队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '怒焰裂谷求帮忙，缺坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者一个风暴就能秒怪，前提是它正常发挥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '好啊，我这就去，稍等，我得补点货');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '大家好，我回来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '谢谢风暴使者陪我玩得这么开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者可不容易');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '这里缺治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '监狱一直被晕，真难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '有人组队吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '马上回来，去拿点喝的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '这么多风暴法术都好有意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '大家好，去打哀嚎不');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '别抢装备哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '怎么能让风暴使者闭嘴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '哀嚎洞穴锁到周日？gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者是治疗，还是光炸东西？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '有人能帮我上怒焰裂谷顶吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '马上回来，得补点绷带。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '刚玩野蛮人……怒气怎么攒？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '有人想打死亡矿井吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者能喝多少水就喝多少哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '嘿新手们，别忘了学技能！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '谢谢你那个影牙的小技巧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '新手风暴使者报到，正在苦熬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '没问题，记得躲开大石头。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '我是风暴使者，在洞里活下来有什么技巧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '有风暴使者想去怒焰吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者就像天气一样不可捉摸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '风暴使者的治疗是恩赐，输出却一塌糊涂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '有好坦克诺莫瑞根很轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '求哀嚎洞穴的建议，或者打影牙也行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '我的闪电箭怎么老打空？刚玩风暴使者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '抱歉我还没打出应有的水平，谢谢你们的耐心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '有人能分享一下风暴使者的手法循环吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '哇，风暴使者得学点新花样才能在队里有用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '抱歉，我被自己的风暴绕晕了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '看来猎人永远死不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 1, 0, 0, 0, 0, 10, '马上回来，去拿点吃的，几分钟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '大家好，刷得开心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '没问题，很高兴能帮上忙。风暴使者必胜！。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '剃刀高地简直是噩梦，我恨那些蜘蛛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我喜欢这背景故事。不知道风暴使者是不是都出自同一个学派');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '马上回来，得找点怪做任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '38级风暴使者求血色修道院队伍，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我喜欢这剧情和氛围，感觉这个世界真的在呼吸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我是风暴使者，缺任务做，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '能组个剃刀高地的队吗，只要35级以上。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '真不敢相信我在副本里还得复活我的风暴使者，怪太强了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我的法术怎么老打墙不打怪？风暴使者得找个师傅了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '哇，风暴使者的输出在这个等级成长得不错啊！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '马上回来，去诺莫瑞根电几个地精');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '野蛮人在这，谁要我当肉盾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '血色里怎么才能不啥都被打到？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '大家好，我是风暴使者，有优化闪电法术的建议吗？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '大家好，25级风暴使者，很高兴认识各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '刚用旋风斩拉了个怪，结果不小心把自己的宠物打死了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '在黑暗深渊深处，谁能教我怎么轻松杀鲨鱼吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '有没有觉得风暴使者就是个行走的避雷针？这就是风暴使者的生活');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我是风暴使者，有人知道血色修道院的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '有了那个新坐骑拉怪轻松多了，终于跟上了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我在监狱副本卡了好久了，需要个风暴使者帮忙速杀它们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '有风暴使者想一起做剃刀高地的任务吗？求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '刚跟几个新朋友通了剃刀沼泽，gg 团队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '刚一个人拉了剃刀沼泽，啥也没捞着哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '没问题，谁需要风暴使者输出配装的帮助，跟我说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '有人有风暴使者的循环技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '风暴使者的法力池怎么这么小？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '风暴使者没人给治疗，求治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '哈哈，风暴使者被什么都晕');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '抱歉，我在刷风暴使者被打断了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '恭喜你拿到风暴使者坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '出售16格包，要金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '这个等级刷皮最好的方法是什么？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '风暴使者太好玩了，连我妈都能上手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '有野蛮人想跑黑暗深渊吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, 'gg，这趟副本真有意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '那进剃刀高地最省事的路是哪条？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我是风暴使者，有人想一起去监狱吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '大家好，很高兴认识你们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '哈哈，我得把法术升上去，最近感觉自己就是个行走的雷暴。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '谢谢，血色修道院这趟打得不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '各位可爱的人你们好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '真希望我没选风暴使者，这些风要把我吹死了。哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '哈哈，这职业上手了之后就特别简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '各位冒险者好，今天任务顺利吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '剃刀高地求帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '我得把风暴使者拴着，说真的，我觉得自己就是个避雷针哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 2, 0, 0, 0, 0, 10, '有人能帮我弄个坐骑吗，我实在不想再跑去黑暗深渊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '哇，风暴使者挺好玩，但我的法力条恨死我了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '非常感谢治疗，我当时只剩5%的血哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '下层黑石塔太好玩了，我是说那里面真的全是石头。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '马上回来，得看看我的坐骑在那场风暴之后还活着没。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '求玛拉顿队伍，有人吗？boss战需要帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '有人能解释一下沉没的神庙这图的逻辑吗？我感觉一直在绕圈……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '你不会相信我在认路上有多挣扎，感觉自己像在演李洛依。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者，永不缺蓝的法系');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我的剑比你妈的还大');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '我的雷暴在冷却，真替其他人感到抱歉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者能帮我脱离任何困境');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者伤害很高，但用法术得站桩，所以挺难的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '刚在奥达曼被抢装备，没事，以前也遇到过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者求祖尔法拉克帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者求黑石深渊帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '有人能带玛拉顿吗？我过不了第三个boss');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴有时候真是难控制得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '求奥达曼队伍，缺个风暴使者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '我发誓“风暴使者”这名字最烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '黑暗深渊是噩梦，但至少是个湿漉漉的噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者的风暴之锤控场太强了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '下层黑石，我们来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '好怀念风暴使者超模的旧日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '哈哈我被风暴之锤打死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '厄运之槌队伍缺个风暴使者来干掉那个boss');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者没听起来那么容易');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, 'gg，我们再去黑石深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '刚摔死还得复活，真喜欢风暴使者的机动性，谢谢群疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '大家好，我在练风暴使者，有什么技巧吗哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '嘿，厄运之槌怎么样？还是一团乱哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人硬得要命，但怒气管理是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '得去刷点奥达曼的装备，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者拉仇恨？那简直像赶猫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '哦嘿风暴使者，想跟我回玛拉顿吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '谢谢治疗哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '沉没的神庙总是那么阴森');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '风暴使者，就是爱这个能把任何一波怪变成风暴的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 3, 0, 0, 0, 0, 10, '嘿，有人有风暴使者和治疗能打下层黑石塔吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '嘿各位，有人在通灵学院刷材料的心得吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '在暴风城刷金有什么技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '熔火之心缺坦克，求坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '还有谁觉得自己是全场最硬的纸？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, 'gg 各位，奥妮克希亚打得漂亮，风暴使者的火球满天飞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '等你的闪电闪亮起来，风暴使者就轻松了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '我是风暴使者新手，需要手法方面的帮助');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者纸上谈兵挺简单，实战就一团乱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '哈哈，你们都完蛋了，我召唤风暴劈你们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '斯坦索姆速通，缺治疗的来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '我需要几场能奶得爽的仗，我想进祖尔格拉布');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '笑死，我都忘了治疗能杀多少东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '谢谢大家在奥妮克希亚的帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '我喜欢黑翼之巢的背景故事，但组不到队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '监狱快打完了，我再也不越狱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者比我记得的难多了，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '我错过了这地方的史诗剧情，刚走到熔火之心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '上层黑石塔还是那么难搞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '黑翼之巢缺个战士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者得加强一下才能跟上其他治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '今天我要甩好多法术。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者我已经玩明白了，全靠节奏。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '你有没有发现，一打雷大家就怪风暴使者？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '有人知道风暴使者的好战术吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '为什么风暴总是一来三个？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人人生：一直打到死。不过谢谢治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '斯坦索姆的刷怪比法师回蓝还慢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '谢谢组队，不客气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '我们接下来得去打上层黑石塔。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '马上回来，去通灵学院看看装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者难玩，但值得。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '哈哈，我的风暴使者卡在熔火之心出不来了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '这么卡，我的法术全打不中。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, 'gg wp 各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '为什么风暴使者最牛？因为我们带来雷霆！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '大家好，新手风暴使者，你们觉得哪个专精最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '被蜘蛛缠得够呛吧，要帮忙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '我怀念第一个任务的感觉，不过现在挺喜欢我的野蛮人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者1，圣骑0，我直接/跳舞溜了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '嗨，我第一次抗斯坦索姆，有人想来就来，没问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '有人能讲讲旋风术怎么正确用吗，顺便求好友，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '熔火之心永远缺风暴使者输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '还有谁觉得用对风暴使者专精，祖尔格拉布就轻轻松松？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '大家好，有人想去黑石塔打pvp吗？风暴使者最强，没跑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者需要坦克，我不用当坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '风暴使者为什么总是发型乱糟糟？因为风太大哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 16, 4, 0, 0, 0, 0, 10, '刚从通灵学院出来，有人需要奥妮克希亚的帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '刷铜矿最好的地方在哪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '这怒气我还是玩不明白');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '有人能帮我做新手区第三个任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我是克索罗斯骑士，拉仇恨有点快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '哈哈，我们的克索罗斯骑士在哀嚎洞穴拉错怪了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我们得去逆风小径');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '猎人在影牙城堡需要帮忙，请帮帮我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士挺难的，但很好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '有人能告诉我刷皮最好的地方吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '有人能来怒焰裂谷帮忙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士好练级吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '嘿，我身上克索罗斯坐骑的buff开着呢，死不了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '这个得多点输出，谁来？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '有我的克索罗斯骑士，怒焰裂谷轻轻松松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士没什么好学的，主要是猛挥那把大剑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '看着我的克索罗斯骑士抗住10个怪，太过瘾了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '你为什么玩克索罗斯骑士？我喜欢它能抗又能打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我这儿有个路子，我的克索罗斯骑士能砸完就走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士很好玩，但我的战马怎么这么能吃');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '刚学会用那个克索罗斯buff，太猛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士玩起来太爽了，简直是想让你上瘾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我玩克索罗斯骑士有一阵了，这是最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我真的很喜欢克索罗斯骑士，但我就是受不了自己玩得这么烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '剃刀沼泽挺烦，但掉落还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士的治疗量是受到伤害的一半，但谁在乎呢，我的坐骑帅就行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我从没像我的坐骑没血要休息时那么高兴过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '哈哈，克索罗斯骑士就像坦克版的圣骑士，只不过是我一直没玩到的那种');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我的装备怎么这么烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '狂怒加速真让人头疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我在影牙城堡死的时候真是太气人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '11级打哀嚎洞穴真的太难了，所以我才需要坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我受够在怒焰裂谷抗怪了，它们怎么就不能赶紧死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士在影牙求帮忙，有人能抽5分钟吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '马上回来，去多弄点金币买坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '干嘛非得下修道院，我又不是圣人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '克索罗斯骑士能单刷死亡矿井，但太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '哈哈，我的克索罗斯骑士怎么这么肉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '谢谢附魔的提示，我之前在这方面麻烦死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '只要我操作得当，克索罗斯骑士在死亡矿井也能死掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '我就喜欢当坦克，我来挨打他们就不用挨了，坦克人生');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '哀嚎洞穴太乱了，我们跳过它直接去怒焰吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 1, 0, 0, 0, 0, 10, '真不敢相信我的克索罗斯骑士居然打空了，拜托');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士是个很帅的职业，尤其是能用坐骑的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '监狱副本是我的最爱，尤其是能用盾击把那些守卫晕住的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士为什么当不好守密人？我们总是守不住嘴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人就像近战里的法师，哈哈，没蓝只有怒气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士名声可能不好，但我们在血色修道院可是很能顶的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '有克索罗斯骑士，剃刀沼泽太简单了，他们抗那里的怪最在行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '马上回来，我去用战马碾平黑暗深渊的怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '哈哈，我的克索罗斯骑士连个像样的晕都打不出来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士是唯一能说自己对朋友锁着死亡之握的人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '我就在这儿纳闷，克索罗斯骑士怎么这么痴迷自己的坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '哇，克索罗斯骑士和他们的战马，谁能忘得了这一对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, 'kx 玩起来挺烦的，不过克索罗斯坐骑是真爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, 'kx 在黑暗深渊，缺治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '黑暗深渊只要风筝怪就轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 2, 0, 0, 0, 0, 10, '野蛮人怒气，还是谁最强谁最吵？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '诺莫瑞根通了，今天第四次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '带个kx打剃刀高地是有点难受，不过至少够快，谢谢大家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '监狱需要点关爱，有人吗？我的kx准备好了，无所谓，就是想找人一起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '血色修道院通了，kx坦克顶住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '骑士：抗怪是辛苦，但我的克索罗斯坐骑让这一切都值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '剃刀高地对克索罗斯骑士来说是噩梦，但适合刷东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '刚上手，我很喜欢，但血色修道院好难哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '队里有克索罗斯骑士，剃刀沼泽轻松些');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '没事，骑士就是干这个的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士挺难驾驭的，但谁想要轻松的人生呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '这刷新怎么这么慢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '我怎么让我的克索罗斯骑士坐骑buff得更快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士抗诺莫瑞根简直完美');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '有个骑士坦克，黑暗深渊轻松多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '你不会相信克索罗斯骑士能打出多少伤害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '监狱太残暴了，克索罗斯骑士来救场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '剃刀高地很凶险，但骑士绝不手软，他们可是克索罗斯骑士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '大家好，求黑暗深渊队伍做几个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯骑士是坦克加治疗二合一，不过治疗这块他们确实很拉哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '嘿，有人知道在剃刀高地练级的好路线吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '不知道我能不能单刷诺莫瑞根');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '有人知道奥达曼附近好刷怪的点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '嗨我是新手，监狱对25级来说难吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '马上回来，得喂宠物');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '我好像一直摸不透剃刀沼泽，有什么技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '克索罗斯坐骑就像我战斗中的好兄弟，但喂饱它真是太折腾人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '血色修道院缺治疗和输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '我喜欢克索罗斯骑士，但抗怪太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '哈哈，侏儒的老婆最棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 2, 0, 0, 0, 0, 10, '单刷剃刀高地比你想象的简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '克索罗斯骑士的法术背起来真头疼，但那爆发伤害太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '你有没有发现克索罗斯骑士的坐骑骑得越久越烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '这地图的故事太丰富了，我能逛好几个小时');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '还记得我们以前在祖尔法拉克跳舞的日子吗，现在什么都变成竞速了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '这延迟毁了我的pvp体验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '有一队克索罗斯骑士，玛拉顿好玩太多多多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '克索罗斯骑士更像是个光鲜版的坦克，只是多了点阴森味儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '黑石深渊该给克索罗斯骑士配个警告标签哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '真不敢相信我们没出那个克索罗斯骑士坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '说实话，奥达曼就是个超大的RPG副本，外加一点额外剧情');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '奥达曼开组，缺坦克，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '我的克索罗斯坐骑怎么把我撂在那儿了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '恭喜在下层黑石塔出史诗装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 1, 0, 0, 0, 0, 10, '攒怒气准备拉一大波，等等');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '嘿，有人有玛拉顿的钥匙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '沉没的神庙有好队伍就很简单，缺输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '我是剧情党，有人能确认我们在祖拉姆到底干了什么好事吗哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '谢谢在厄运之槌给的快速提示');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '有人刷祖尔法拉克赚点快钱吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '有公会缺人单拉厄运之槌整条“巨口”吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '克索罗斯骑士在此，有人要坦克吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '黑石深渊，谢谢大家帮忙！打得真爽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '大家好，有没有人觉得自己躺地上的时间比在坐骑上还多。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '克索罗斯骑士，一个漂亮的净化手感真棒，还有谁？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '嘿，有人还记得奥达曼那回吗，我那时候还是个菜鸟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '哈哈，野蛮人怒气就像小孩撒泼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '克索罗斯骑士是我最喜欢的职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '有人知道玛拉顿的好打法吗？那里面简直是丛林。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '说实话，我爱这游戏的剧情，但我的坐骑真让我头疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '下黑石塔很难，但值得打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '在厄运之槌玩克索罗斯骑士我有点上头了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '我连个像样的双关都想不出来配我的克索罗斯骑士..');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '大家好，多好的日子啊，正好把东西坦到死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '为什么大家都黑骑士？因为他们永远是对的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '嘿，骑士在此，这个小怪要帮忙吗？叫我护甲增益之王');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '搞不懂大家为啥那么怕拉仇恨，我骑上克索罗斯的战马跑就完事，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '这卡得离谱，连怪都拉不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '能用跑的、指望跑得够快就好，何必潜行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '兄弟们，坦克才是最好的玩法，问我的血条就知道');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 3, 0, 0, 0, 0, 10, '克索罗斯骑士在此，让我来给你坦克，我随时欢迎多点增益。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '克索罗斯骑士为什么带梯子上战场？因为他听说这是场往上硬打的仗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '哈哈，我分不清我这匹克索罗斯坐骑是坐骑还是生死之交');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '笑死，我坦过熔火之心和奥妮克希亚，但上黑石塔对我来说太扎人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '有人能解释一下我到底该怎么刷钱吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我就爱在通灵学院坦克，感觉自己就是个BOSS，字面意义上的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我一直在把炼金冲上300，有诀窍吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '非常感谢治疗，兄弟们，真的谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '黑石深渊的氛围太棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '黑翼之巢太吓人了，而我又不擅长打龙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '新版的克索罗斯骑士技能我是真的不好上手。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '祖尔格拉布缺1治疗，求');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '没想到我会这么说，但我想念斯坦索姆的美好旧时光。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我决定不了该冲附魔还是采矿。救命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '克索罗斯骑士是无名英雄。不过我们确实不会唱歌哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '刷了几小时黑石矿，包里全是灰，我打喷嚏打得像个德莱尼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '上黑石塔封锁中，谁准备去死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '谢谢附魔的建议，我刚拿到第一把史诗剑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '克索罗斯骑士就像终极坦克，能挨打，也能还手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '野蛮人全靠蛮力，没什么细腻可言');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '熔火之心是噩梦，老是不停拉来小怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '又是斯坦索姆。需要一个盗贼开锁，有人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '就爱克索罗斯骑士能在火里跳舞，字面意义上的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我就想在这儿多刷点金币，别理我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '这是我第五次来刷奥妮克希亚的史诗掉落了，我的理智已碎');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '上黑石塔真要把我弄死了，也许我打法不对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我的药水从来不够，有人能匀瓶治疗药水吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '克索罗斯骑士：让你总说“希望这招管用”的职业，而且每次真管用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '在黑石塔刷坐骑，离那匹坐骑就差一点点了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '下个职业该玩什么？我喜欢下本坦克，克索罗斯骑士挺好玩，但也许换换？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '我吃饭的时候谁来帮我拉怪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '终于拿到我的第一匹克索罗斯坐骑了，舒服');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '黑翼之巢组队，缺个好坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '还有谁爱通灵学院？和死人跳支幽灵华尔兹，没有比这更爽的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '刚刷了点矿石，有矿在手，谁还需要别的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '克索罗斯骑士：坦得了坦克，也坦得了杂兵。还有谁在团本里觉得自己很猛？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '大家好！准备好去熔火之心找点乐子了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '熔火之心组队，缺输出和治疗，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我去刷点金币和矿石，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '克索罗斯骑士天下第一');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '那匹坐骑本身就是个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '给野蛮人拉怪就像抓抹了油的猪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我简直不敢相信我死了多少次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '有人需要帮忙打奥妮克希亚吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我太爱这剧情了，克索罗斯真棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我的骑士一直强不起来，求建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我觉得剧情特别有意思，细节太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我们晚点该去斯坦索姆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '这是我第一次玩克索罗斯骑士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 17, 4, 0, 0, 0, 0, 10, '我觉得黑翼比熔火简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者坦克就像一堵会走路的墙，最棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者的日子哈哈，你之所以活着就是因为你是那堵墙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '嘿，厄运之槌求个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '死亡矿井缺治疗，马上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者为什么从不孤单？因为永远是“你对抗整个世界”');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '抱歉，又被野猪撞了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我这记盾击不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者坦克就像拿牙签去挡海啸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '怒焰裂谷还缺2个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '这是我第一个角色，我完全是新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '你们的治疗，能不能专心别死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我居然得骑着坐骑打鱼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者，对吧？我爱盾击，手感真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '祖尔法拉克运气好拉到了稀有怪，谢谢各位。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '哈哈，坦克真好玩，我感觉自己就是个会走路的沙袋');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '刚加入守护者行列，什么时候用嘲讽有建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '嘿，有守护者在吗？有人知道怎么把格挡发挥到极致吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者，就是保姆的另一个说法哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '刚打完哀嚎洞穴，看来我们就得把盾举起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '求建议该选哪块盾，我听到的说法不一');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '你知道我最爱守护者哪点吗，我死不了。哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我不确定自己做得对不对，我必须一直待在前排吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '所以说，坦克是难，但至少我们是主角');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '死亡矿井太爽了，没有什么比得上老式矿洞塌方。哈哈我该穿靴子的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 12, 3, 0, 0, 0, 0, 10, '野蛮人人生：无尽狂怒。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '就爱守护者能站那儿硬挨打哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '谢谢在我开打15分钟后才给我加血。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我在摸索守护者，6级有什么建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '马上回来，我得去刷点布冲裁缝等级。加油！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我爱这游戏带来的怀旧感，这就是我的童年');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我刚拿到第一块盾，要不要往防御上加点？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '太开心了，我终于能学会玩这个职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者的日子挺难哈哈，感觉我一点法力都没有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '守护者学会新技能了。1-2-3。行吧。/跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_class', 4, 0, 18, 1, 0, 0, 0, 0, 10, '我爱哀嚎洞穴，要杀的迅猛龙太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '卧槽，为什么%zone的狼全都来打我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林太棒了，可这些狗头人一直偷我的钱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人在%zone组队刷怪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '这些野猪杀起来太爽了。我想念%zone。谢谢那些回忆。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '哇终于接到去千针石林的任务了，从哪儿开始啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '嘿各位，千针石林南边有个洞，里面一堆食人魔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我只想在千针石林把任务做完，这些羚羊跑太快了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林轻松加愉快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '哈哈千针石林的猎人怎么什么都需求');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林留意那个杀10个野猪人的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的通缉任务在哪接？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '谢谢帮忙，坐骑到手了！现在回千针石林收尾！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '刚清了千针石林的洞，掉落真多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林任务有时有点磨人，不过还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗的矿点怎么老被人占着，搞什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '马上回来，去千针石林弄点吃的，顺便看看还能不能接任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '小心%zone的秃鹫，被围上就难受了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '大家好我刚到%zone，这儿怎么练级最快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '嘿各位，还有谁在千针石林做任务，求点建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '谢谢%zone大家帮我，这份人情我记着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的任务怎么这么费时间？我想快点升级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '找几个猎人一起去%zone做任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林的掉落太随机了，怎么老半天刷不到要的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '大家好，有人知道%zone哪儿刷怪好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '在千针石林刷掉落，感觉像大海捞针');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我在%zone挖到太多矿了，离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的怪这么脆，怎么就是不掉东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '%zone的氛围还不错，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地，各位好啊，需要帮忙的喊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '哈哈阿拉希高地，今天还有谁在刷山羊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地鱼人那个任务需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地那些地精玩意儿真有那么难吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '太烦%zone的食人魔了，得歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '%zone的狼很好打，有人能帮我抗吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '谁要阿拉希高地的掉落，我就想刷山丘');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '我在%zone做了好几个小时任务，这些鬣狗太缠人了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我回%zone了，都忘了我有多讨厌冰巨魔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '还记得我们第一次骑马穿过阿拉希高地吗？那时候真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '谢谢%zone的buff，任务好做多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '%zone最烦的就是雏龙，老逮我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地就像段烂感情，我讨厌它却总回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '刚做完%zone最后一个任务，该去下个地图了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地有些任务挺磨人，不过风景真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '还有谁觉得阿拉希高地的任务越来越重复？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '%zone今天来了几个新手猎人，别忘了他们什么都需求');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '这儿故事太多了，我忍不住喜欢阿拉希高地');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '谢谢阿拉希高地任务的建议，省事多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我讨厌在丹莫罗迷路，有地图吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '我就喜欢阿拉希高地任务那么多花样，事儿真多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '我就是爱阿拉希高地。氛围、任务、怪，尤其是鱼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '大家好，%zone这么多人真热闹');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '嘿，%zone这儿有几张熟面孔，见到你们真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '这地方好有年代感，喜欢阿拉希高地的历史。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地的风太狠了，习惯就好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '阿拉希高地任务这么多，从哪儿开始啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '有人去把%zone东边那伙精英座狼清了吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '靠这延迟我真服了，还有谁觉得%zone有点卡？没有？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '我发誓%zone野猪人刷新太离谱了，跟刷不完一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '还在%zone找那个难出的制皮图纸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '谢谢治疗，你把我从%zone那个精英手里救下来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '%zone怎么这么多秃鹫，它们存在有啥意义？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '我当初怎么答应来%zone的，这地方全是烦人的虫子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '%zone到处是巨魔，小心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 45, 0, 0, 0, 10, '小心%zone的巨魔巡逻队，打人很疼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '大家好，我刚到%zone，谁能帮我认认路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人想在%zone做任务吗？我还剩20来个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '嘿！还有谁喜欢荆棘谷的氛围');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我太喜欢%zone的感觉了！丛林味儿十足');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '小心荆棘谷那些海盗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我发誓丹莫罗的NPC跑得比我还快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '还有谁在荆棘谷努力不疯掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我真喜欢%zone的音乐，让我想起第一次来的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '老虎任务要帮忙吗？我卡在荆棘谷了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '还有谁想下线前把%zone任务都清完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '这儿简直是丛林，哈哈。荆棘谷太难混了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '荆棘谷太烂了，到处是蚊子，得来点驱虫任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我喜欢%zone。任务好玩，怪够硬，气氛也绝了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我是种田的，得在%zone刷点金币。有人知道好地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '这么多年了我居然还在%zone做任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone太怀旧了，让我想念魔兽的老日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗这些狼可不好惹');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone的侏儒，求个坦克打剃刀高地');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我发誓%zone的猎人什么都需求');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '在%zone采药，有人要吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我烦%zone刷新这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '监狱有好队很简单，但我真讨厌%zone的延迟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我们在荆棘谷怎么总掉最烂的东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有没有发现%zone的怪总是一群一群上？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '猎人怎么老什么都需求？说真的，4个猎人一起在%zone真不好混');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '知道我为什么喜欢荆棘谷吗？因为蛇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '能快点吗？我对%zone有点腻了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '大家好，丹莫罗今天有什么新鲜事？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '非常感谢在%zone帮忙，你太棒了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我怀念以前两小时就能刷完%zone的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone刷新怎么这么慢，等半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '荆棘谷早上真美，充满可能。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '就差%zone最后那个巨魔没摸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '哇我得离开%zone去诺莫瑞根了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '哈哈，我猎人在%zone被巨魔干掉了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '这蜘蛛在%zone干啥呢，搞什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人知道鱼人那个任务怎么做吗？%zone太烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我喜欢丛林这种生机勃勃的感觉，太爱%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '小心%zone那些狼，挺难缠的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我给你们抗怪。%zone准备开，先说我不是最厉害的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '这儿豺狼人太狠了。%zone有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '哈哈我的宠物在%zone怎么不听话了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人知道稀有怪在哪儿吗？在%zone找一整天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '想采药？%zone是最好的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我在这丛林里老迷路，求%zone那个洞的方向');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone杀食人魔那个任务有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我得剥几头野猪，%zone的最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '小心黑豹，%zone的挺难打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '还有人记得我们第一次发现荆棘谷的时候吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林开局挺难的，但我永远不离开这个世界');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '有没有发现丹莫罗这儿的任务永远做不完？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '这个%zone任务卡了我一辈子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人在%zone帮我打豺狼人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我觉得得歇会儿，%zone太累了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '荆棘谷是个陷阱，走路当心！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone气氛怪怪的，这些海盗怎么这么开心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '哈哈，我在%zone从刷新怪身上摸到10金。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '谢谢帮忙打食人魔，%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '打猎去%zone最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我老在荆棘谷的沼泽区迷路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我发誓%zone的怪刷得比我回蓝还快。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '哈哈，我刚在%zone被熊扑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人在荆棘谷帮我做任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我在荆棘谷老拉太多怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone这个任务需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人有地图吗？我在%zone迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '终于有坐骑了！荆棘谷看着真棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '哇，%zone这些猴子怎么这么凶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人在荆棘谷看到黑豹了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '荆棘谷热死了，有人有冷饮吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '我是新手，%zone该往东还是往西？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '有人能带我在%zone起步吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '需要帮忙做丹莫罗的冰爪任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '%zone哪儿钓鱼最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 33, 0, 0, 0, 10, '荆棘谷看着一样，又跟记忆里不太一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '谢谢在%zone复活时给我治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '哈哈，我发誓%zone的怪刷新后跑得更快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地有点无聊了，第30只野猪人。掉落照旧，日子照过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '卡在%zone那个岩石元素任务了。谢谢各位帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '刚在%zone追怪追了一小时，掉落还是绿的，感觉被抢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '这刷新时间太长了，换我早把%zone任务做完了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我想单刷凄凉之地那个精英，馊主意。求支援');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我喜欢凄凉之地的氛围，真像片荒地。除了野猪人，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '刚给%zone那些雪人跳了一整支舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '希望%zone别这么卡，我卡得都躲不开了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地很棒，但那些任务快把我逼疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '有人记得我们在%zone为啥要捡这些破石头吗？剧情？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone的异种虫好打，但小心那个发疯的流浪法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '有人知道%zone的半人马任务值不值得做吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '还有谁在%zone的石头堆里迷路迷得很开心？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我喜欢%zone，但任务很无聊，虽然掉落好拿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地该来个新地图事件了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我恨我刚拿到新坐骑。%zone现在更轻松了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地到底要不要去？%zone求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '哇，%zone这些雪人真硬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '得有人告诉%zone的猎人，不是什么都得猎一遍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '马上回来，得去%zone刷异种虫做任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地的猎人是另一个物种');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '能不能跳过捡石头，直接去%zone杀怪？算了，我知道这步跳不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '今天谁想去血色修道院？%zone我们几个人太大了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我刚玩，凄凉之地该干啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '小心半人马，%zone的挺凶。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '你敢信有些猎人在%zone得把所有技能都用上。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我觉得凄凉之地的任务我都刷完了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地今天全是半人马，任务都做不完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '谢谢帮忙做清理%zone冰蜘蛛的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '管他延迟，咱们笑着在%zone蹦过去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '真希望凄凉之地的刷新别这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我只想在凄凉之地骑坐骑，可路被堵了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我怀念凄凉之地刚开的时候，那是个不一样的年代');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地今天人真多，我感觉像个游客，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '喜欢凄凉之地的氛围，让我想起从前。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '大家好，在凄凉之地见到你们真好！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '小心%zone的半人马巡逻队，太狠了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '还有谁在%zone感到一股怀旧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '马上回来，得跑到%zone另一头。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '马上回来，去%zone挖点锡矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone采药需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '谁了解凄凉之地的萨特');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '各位好，还有谁在%zone刷任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone任务卡住了，有建议吗？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '想在凄凉之地一起组一会儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '呃，%zone的怪刷得没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone猎人求治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '凄凉之地的掉落太看脸，从来没好结果');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '马上回来，得从剃刀岭跑回%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '哈哈，凄凉之地的豺狼人疯了，我怎么老走不直');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone适合法师刷级吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '被踢出剃刀沼泽队了，回%zone单刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, 'gg，终于在%zone打赢任务boss了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone求治疗，我一个人搞不定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '受够%zone的刷新时间了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '谢谢帮忙做%zone那个任务，这任务我好久没做了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone那双靴子掉率多少？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone太难过了，我还卡在同一个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '我怀念%zone经典的法师任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '有人在%zone入口蹲着。真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone的半人马怎么回事，老远就能看见你');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone这些矮人总是这么友善');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone以前是我最喜欢的地图');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone的任务NPC怎么老出bug？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone的兽人需要帮忙，快把我打死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone练级太痛苦了，来回跑太多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '哇%zone这些半人马比我记得的难多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '马上回来，去补药水。在%zone没坐骑真难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 405, 0, 0, 0, 10, '%zone的地精挺烦，但我还挺想念他们的，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '谁知道%zone的好路线，刚来就被鱼人打死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我怎么老忘了带鱼竿来%zone。不过反过来说，鱼人够我打的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '有人知道%zone的半人马巡逻队改过没有？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我喜欢%zone的风景，但怪太硬了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我发誓，%zone的鱼人比我逃跑骑的马还快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '刚在%zone拿下第一个精英，要是别再在所有沼泽里迷路就好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '你们是不是又爱又恨%zone的鳄鱼？反正我是。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '为什么每次来%zone，我都像重新过了一遍练级日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone的食人魔挺难。真不敢相信他们以前比鱼人还好打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone的蛇怎么对付最好，我发誓水里有一整窝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我怀念在%zone直接打/dance也没人理你的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone刷50-55装备哪儿最好？我老掉一样的东西。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽今天挺空，有人想组队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '祖尔法拉克挺好玩，不过%zone更放松。还有谁想歇会儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我现在去%zone刷点钱，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我在%zone迷路了，谁能带我到出口');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '还有谁喜欢%zone这满眼的绿意？在黑石那堆岩浆里烤完，来这儿真舒服。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '在%zone等朋友闲得慌，有人要帮忙杀鳄鱼吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '祖尔法拉克是不错，但%zone就是更漂亮。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone的任务跑了一整天了，有人也想歇会儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone有几个超棒的升级点，就是鳄鱼老把我打死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone怎么这么泥泞啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '谢谢帮忙，我刚到尘泥沼泽，是新人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽的鳄鱼小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽总让我想起以前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '有人知道怎么快速穿过尘泥沼泽吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '哈哈我刚接到个任务，要去%zone帮个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '真不敢相信我错过了尘泥沼泽的猎人任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽太安逸了，好怀念以前在艾泽拉斯的日子哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我讨厌在尘泥沼泽的泥地里跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽的鱼人真是烦死人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我得穿过%zone去副本门口，谁能组我一下，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '嗨各位，有人知道怎么快穿%zone吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '多谢在%zone的帮忙，你救了我一命，GG');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '有人知道%zone哪里好刷吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '有人能来帮我做%zone的任务吗？有点乱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我爱尘泥沼泽，在这儿死了无数次，全是回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone这地方冻得我脚趾都没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽全是鱼人，我不太喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '嗨，有人在%zone需要帮忙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '还有谁受够%zone那些大块头食人魔了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '还得去尘泥沼泽再采点苔藓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '哦太好了，又是野猪人，%zone正缺这个呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '真希望%zone的任务能有意思点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽的水怎么这么浑浊，烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone天气不错，怪不太行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我去，刚有人在%zone拉了一群鳄鱼，太谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone全是讨厌的秃鹫，我喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我记得当年%zone全是练级的玩家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '嗨，还有谁在%zone这边吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '哦太好了，%zone又一个怪点被清了，它们还刷吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '谁能告诉我为什么我还卡在尘泥沼泽这些任务上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '%zone的掉落也太烂了，我都快对出个像样装备失去希望了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽那片绿油油的沼泽景色，真是美得让人窒息。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我觉得我在%zone真迷路了，不知道咋走到这儿的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '黑龙军团一直在骚扰这片区域，%zone的黑龙多得要命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '我喜欢这儿的背景故事，内容太多，%zone每个任务里都有。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '哇，%zone有30个鱼人，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '有人知道尘泥沼泽那个"泥浆喷洒器"的任务在哪接吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '欢迎来丹莫罗！你主玩什么职业');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '还记得尘泥沼泽刚开那会儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽怎么老有这么多水');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽上周可好玩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '有人能帮我做尘泥沼泽找鱼人的任务吗，求鱼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '尘泥沼泽太无聊了，我得组队去奥达曼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 15, 0, 0, 0, 10, '刚在%zone刷出个稀有，耶！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有人知道%zone哪采矿好吗？这儿铁多，我要刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '真不敢相信我还在%zone为这个低级任务跑来跑去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '真不敢相信我居然在塔纳利斯，还在为史诗坐骑刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哇，我终于把%zone杀火元素的任务做完了，花了老久。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我觉得我们能干掉迪菲亚兄弟会，%zone上手之后也没那么糟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '唉，塔纳利斯那些蜘蛛太烦了，真受罪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有治疗去奥达曼吗？我在%zone单做任务做烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有人有好办法穿过塔纳利斯的蜘蛛区还不死吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '在%zone找队打玛拉顿，不在乎掉落，就想把任务做完。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哦我太喜欢塔纳利斯这儿任务让你满%zone跑的设计了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯今天挺难，那些异种虫群太猛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有人知道塔纳利斯哪剥皮好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, 'zzzzzzzzzz，塔纳利斯怎么这么多地精？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯，就为那个酋长的任务得刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '又在塔纳利斯迷路了，得看眼地图');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我都记不清在%zone被雪人干死多少次了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯今天好慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '我得在塔纳利斯刷点皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯今天太无聊了，我需要法师的时候法师都去哪了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '%zone太狠了，小心鬣狗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哦开心，%zone又是蝎子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哈哈，刚在塔纳利斯被鬣狗干掉了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '没问题，从塔纳利斯西边入口过去就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '嗨各位，我刚到%zone，有人能给点任务建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯很棒，但那些异种虫老搞我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哦拜托，又不是一个在%zone杀甲虫的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '大家好，还有人在%zone想进洞做任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯全是沙子和蝎子，我讨厌这地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哈哈%zone的任务全是从山顶或洞底拿东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯刷史诗坐骑真是太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有打%zone那些讨厌甲虫的诀窍吗？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯这些怪刷得真头疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哈哈%zone的掉落就是不怎么样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '各位咱能不能别去塔纳利斯，改刷黑石深渊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '唉，祖尔法拉克比%zone的怪简单多了，可惜掉率不一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '猎人们在%zone能不能别什么都拉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '就是啊，%zone的掉落太烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '嗨，还有人在%zone觉得我们就该留下来一直跳舞吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '%zone的任务挺麻烦，但经验不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '为什么我们不能在%zone跳舞，非得打这些怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '黑石塔下层比%zone强，谢谢提示');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '找队伍打沉没的神庙，我在%zone，谢谢大家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '在%zone刷金刷烦了，有诀窍吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯总是挤满人，任务最棒！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '还记得以前根本没人来塔纳利斯刷吗？现在看看，全在这儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '你别在%zone这些怪身上浪费时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有人需要塔纳利斯那个任务的帮忙吗？我可以过去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哇，好险，幸好我有药水。塔纳利斯挺难的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '大家好，我%zone新来的，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '想在塔纳利斯做任务结果死了，真失败');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有人有多余的草药吗？在%zone用金币换');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '谁在%zone有草药要卖，跟我说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '真不敢相信%zone那个任务这么简单，我一下就做完了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '你在塔纳利斯有什么过不去的，我可以带你');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '大家好，刚50级，需要%zone的队伍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哈哈，%zone又一群座狼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '需要帮忙打%zone的加兹瑞拉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '大家好，去%zone的加兹瑞拉最快怎么走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '%zone的沙虫小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有法师来帮忙打%zone的洞熊吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '嗨我叫bobby，很高兴认识你们，我爱%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯全是怪，但任务不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '有人能提示我塔纳利斯那个水的东西在哪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '哇我受不了%zone的沙子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '塔纳利斯习惯了蝎子之后也没那么糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '我可以带你过%zone升几级。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '是我错觉还是塔纳利斯的沙漠热得烧人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 440, 0, 0, 0, 10, '我需要%zone的日常来刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '大家好，菲拉斯是刷皮最好的地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '今天还有谁在%zone？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '在%zone找路，小心野秃鹫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '嗨我是jane，我看你们有些人也是刚来%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '又是%zone的一天，草更绿，秃鹫更凶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '有人知道%zone采药的好路线吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '有人需要帮忙打奥达曼吗？就在%zone旁边');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone今天的秃鹫好凶，谢谢提醒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '又是%zone一个安静的晚上，看看风景');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '嗨各位，很高兴在%zone见到友善的面孔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '还有谁喜欢这%zone的背景故事？历史好多。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone卡得厉害，还有人这样吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '大家好，享受%zone晴朗的天气吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone今天这么多稀有刷新，就是都不给我们面子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '超喜欢%zone的氛围');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '找个法师把我们传送到%zone采稀有草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone的萨特怎么老是我只需要捡一个怪的时候来打我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '嗨我听说%zone有史诗掉落，但找不到');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '喜欢背景故事的能在%zone找到很多暗夜精灵的资料');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '我怀念以前%zone的怪比较简单的时候，我就是没以前厉害了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '有人能指我%zone最好走的路吗？我第一次来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '我喜欢%zone的环境音乐');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone有任务给木喉声望吗？我需要熊怪声望');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '刚在%zone拿到我的第一件史诗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '还有谁喜欢在%zone全速奔跑的感觉？好怀旧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '有人知道在%zone弄10张狼皮最简单的办法吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '有单刷%zone那个巨人的诀窍吗？还是我该放弃？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '菲拉斯被低估了。我怀念以前在那儿跑的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '在%zone，刷得疯了，我发誓。我还能被萨特杀几次？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '在%zone，刷新速度要我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '菲拉斯怎么这么多萨特，我怀念我30级的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '在%zone，得找回大路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '哈哈我喜欢%zone的剧情，但这些萨特老刷在我的任务物品上！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '有人告诉我%zone北边有条隐藏小路？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone的鹰身女妖小心，她们会偷你的靴子，求助。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '我怀念%zone任务简单的时候。现在全是绕路和隐藏开关，GG。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '做%zone任务就去刷熊怪，很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '别离开%zone的大路，信我，你不想跟九头蛇打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '马上回来，在%zone刷点羽毛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone瀑布附近有个潜行怪，小心哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '你知道猎人们在这儿吗，%zone是打猎最好的地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '嗨%zone的各位，很高兴看到这么多冒险者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '有人知道菲拉斯这儿哪能找到好的法师任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '在%zone打高级怪很刺激，但掉落值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '我今天在%zone的掉落怎么这么烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '我知道这地方危险，但我爱%zone，全是升级任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '早上好%zone，看看这儿有什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '泰达希尔到处都是可以练手的小野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '真不敢相信我们在%zone刷了好几个小时');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '在菲拉斯看日出已经成我的早晨习惯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '看在%zone一切美好事物的份上，谁来帮我这个任务！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '菲拉斯的树要小心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '大家好！在%zone升级最好的办法是什么？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '我就是喜欢菲拉斯的氛围。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone出太阳了，今天会是好日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '大家好，欢迎来到菲拉斯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '小心那些萨特，%zone他们的法术很疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '来自丛林的问候，菲拉斯的各位怎么样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '需要帮忙打%zone的萨特');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '%zone这儿的萨特小心，不留神他们就把你变羊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '多谢治疗，我差点被菲拉斯那根恶心的树枝弄死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 357, 0, 0, 0, 10, '菲拉斯的树人任务在我这儿有bug，还有人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '各位好。辛特兰哪儿刷金最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我记得第一次来辛特兰，以为自己很猛，结果被一个巨魔干了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '各位好。辛特兰有什么任务要帮忙尽管喊我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '想赚点金币？我带你去看辛特兰最好的草药点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '出去小心点。%zone的元素怪挺棘手。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '很高兴在辛特兰看到这么多友善的面孔，刷起来值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '有人在辛特兰找下一趟队伍吗，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '泰达希尔有几个最适合练级的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '天啊%zone遍地是野猪人，有人知道捷径吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '有人能指我去辛特兰下一个任务NPC吗？我还新。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone弯弯绕绕太多，我发誓肯定迷路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '哇刚冲过%zone那群巨魔，真是壮观。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '哈哈又在%zone迷路了，不如开始跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '有人知道辛特兰还要不要再杀那么多巨魔？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '刚50级。还在%zone找人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '天啊，你在%zone还是能迷路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我发誓%zone的任务怪总在刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '谢谢，%zone没那么糟，就是峭壁里那些精英蜘蛛老回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone这个箱子里的东西值得跑一趟吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '有人对%zone狼人那个任务有建议吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '有人在附近能帮我做%zone的任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '出去小心，辛特兰刷得很快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '笑死，有人说%zone是个坑，他们没说错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我觉得我在辛特兰摔下悬崖不该死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone今天天气不错，那些猎犬真是挑战');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '在%zone打怪，感受怀旧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我怀念以前在%zone不用攻略就能做任务的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone的狼太狠了，多带点治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '哈哈，%zone又一个死胡同任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '泰达希尔的任务有点磨人，但回报不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '大家怎么都在抱怨怪，%zone一如既往地好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '马上回来，得在%zone捡点尸体');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '早上好%zone，有人来做鬣狗首领任务的吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '唉，%zone这些鬣狗到处都是，感觉我在原地转圈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我在%zone待了好久，但剧情真是太棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone这延迟要我的命，但我不会停下刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '你得喜欢辛特兰的氛围，但晚上有点阴森');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '你知道我喜欢辛特兰什么吗，野狼的持续威胁哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone有人想聊聊剧情吗，我漏了点背景。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '辛特兰的任务不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '谢谢各位，第一次来%zone，我该从哪开始？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '大家好，还有谁是刚来%zone的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '辛特兰哪儿刷怪好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '嗨，为了制皮在%zone要刷什么？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '又是%zone的一天，又一堆地精');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '哈哈在%zone你跑不过豺狼人，吸取我的教训');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone的洞穴怎么去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我怀念以前%zone没被精英占满的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '刚在%zone刷了5组苔藓，谢谢大家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我发誓%zone的猎犬能闻到恐惧，谢谢提示');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我在%zone练制皮，有些稀有皮要卖');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone的食人魔太可笑了，简单模式');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '我真想念%zone的氛围，让我想起最初那几天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '想去祖尔法拉克，%zone全是食人魔，真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '辛特兰的各位好！有人知道刷银矿的好地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '我喜欢辛特兰。风景很棒，但这些狼很烦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '大家好，新人。有人能给点在%zone刷东西的建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '辛特兰的任务挺有意思，但我老迷路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '%zone怎么总有狼？它们让我猎人忙一整天。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 47, 0, 0, 0, 10, '哈哈我老忘%zone哪个方向是出口。幸好我有地图和指南针。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地挺难，但怪掉落不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '哈哈刚有人从荒芜之地那个悬崖摔下去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地这儿的怪跑得挺快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone的怪太狠了，但升级的感觉真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '刚50级，准备好做荒芜之地的任务了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '谁来帮忙。我卡在荒芜之地一个任务上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '有人对%zone有诀窍吗？有点棘手。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我记得%zone以前全是50级精英怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '小心%zone附近的蛇怪，我有一次被揍得很惨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '就做任务吧，%zone不用着急');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '你可以在%zone附近找到一些散落的草药。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '在%zone逛老任务是种乐趣，很怀旧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我觉得蛇怪对我这等级来说太强了，就算在%zone也是。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '有人有多余草药换吗？在%zone很难凑够');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '有人知道%zone的暗夜精灵新手任务在哪接吗？我刚到');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '大家好，%zone有什么好玩的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地的任务真是要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我喜欢%zone充满惊喜的样子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '有人见过新的博学者吗？他对%zone了解很多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地是我法力药水的坟场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我还挺惊讶荒芜之地玩家不多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '嗨，%zone哪刷铁矿最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我讨厌这些刷新像在开延迟派对。%zone也帮不上忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我爱荒芜之地的铁，好找，我在这儿24小时刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '这不是荒芜之地吗。我要的40+任务在哪？奥达曼我来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '小心泰达希尔的蛛网林地蜘蛛，打人很疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '真不敢相信我又卡在荒芜之地的泥里了，谢谢帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '刚在荒芜之地被抢了掉落，谢了哥们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地对这个法师是噩梦。我们能不能组队去黑石深渊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我老忘记荒芜之地一堆陷阱，简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '哇，真不敢相信我死在荒芜之地的食人魔手上。他们也不强，就是会偷袭你。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地采矿没有更快的方法吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地的刷新太离谱了，我发誓。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我见过荒芜之地同一个精英死了100次了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地就是个全是恨我的怪的沙漠。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '在荒芜之地谁还需要坐骑啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '哦泰达希尔的背景故事太棒了，我超爱这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地比我丈母娘还危险。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '哈哈，荒芜之地这些食人魔太烦了，软柿子在哪儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '看见一大群食人魔就跑了，%zone不是开玩笑的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '还有谁讨厌刷新计时？%zone什么都不给我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '嗨，我刷了好几个小时矿，但得走了，%zone在掏空我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地的任务就没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我就是来练钓鱼的，这些任务太久了，荒芜之地好难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我在荒芜之地的掉落怎么这么烂，太气人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '得有人管管%zone的延迟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '哇荒芜之地到处是刺和羽毛，一团糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '泰达希尔好绿啊。我都不想走了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我们怎么又在荒芜之地，每次都一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地的刷新率太糟了，我发誓越来越烂。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '哈哈%zone永远不变，总是那些老怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我还有多少%zone的任务要做啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地太热了，我要化了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '我以为%zone应该很简单，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地总刮那种怪风，我讨厌。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '%zone你需要猎人的时候猎人都去哪了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '在%zone闲逛的好天气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '谁要做荒芜之地的元素任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone的森林氛围好治愈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '有人能指我去%zone那个隐藏洞穴吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 3, 0, 0, 0, 10, '荒芜之地坦克找个治疗打厄运之槌。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '大家好，刚到%zone。喜欢这儿的风景，但天啊，刷怪太离谱了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '有人知道灼热峡谷这儿任务的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '嗨，我刚到灼热峡谷，这儿怎么刷最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '你该看看灼热峡谷的黑石兽人，大得吓人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '大家好，我刚到%zone。怎么过这儿最容易？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '我们队里有人刚在%zone死在一群兽人手里，倒得很惨。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '你知道%zone谁说了算吗？猎人。这是猎人的世界，我们只是住在里面。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '小心灼热峡谷那些熔岩池，不是闹着玩的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '真希望%zone的怪别一群一群地围我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '有人知道穿过%zone更快的路吗？我没一整天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '太可怕了，%zone的任务像没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷的火元素刷得好慢，感觉这任务永远做不完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '有猎人需要%zone的队伍吗？我想把这任务做完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone有人吗？奥达曼缺个坦克，求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '大家好，灼热峡谷今天天气不错吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '哇，%zone这热度太狠了，我们怎么不去祖尔法拉克？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '抱歉，马上回来，灼热峡谷弹了个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '还有谁喜欢%zone的氛围？像古战场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '我们能去刷黑石塔下层吗？我在灼热峡谷太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone这儿的任务真的很简单，可我还是一直死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '各位好，需要帮忙做%zone的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '马上回来，%zone糟透了，卡得厉害。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '小心%zone的火元素。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷挺难，到处是元素猎犬。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷氛围不错，但那些任务累死人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '小心地精，%zone到处是陷阱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '求灼热峡谷建议，制皮刷什么？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷，谁还要刷元素之核？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '在%zone偷偷绕过元素守护者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '小心%zone，瀑布附近有个潜行的猎人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '小心艾尔文森林那些狼，可凶了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone这儿的怪太好打了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '大家好，刚到%zone。有人需要帮忙做元素任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '有人知道穿过%zone的好路线吗，最好别撞上太多火元素？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷。这地方怎么都不腻。至少我是从没腻过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '嘿，有人在%zone附近看到黑龙吗？我任务要打一只');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '求%zone队伍，想赶在黑石塔之前把元素任务做完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '嘿，等会儿要去厄运之槌。有人知道怎么最快穿过%zone吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '好怀念以前能在%zone随便跳舞，不用怕被火元素偷袭的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '嘿伙计们，咋样？%zone今天挺凶的，到处都是食人魔。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '大家好，就在%zone练级。这儿刷怪还挺爽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone那些熔岩蜘蛛小心点，打人很疼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '谢谢治疗，把我从%zone那场硬仗里救出来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '有人在%zone需要帮忙做任务吗？喊我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone的各位好。刚从玛拉顿刷完回来，累是累，但值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '大家好，我得在%zone采点草药。还有谁要一起找？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone的食人魔真是没完没了，不过经验真香！嗷嗷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '嘿，灼热峡谷这儿有人要铁矿石吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '有人在%zone找队伍吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷的刷新也太久了，咋回事啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '刚刷够做20个包的魔纹布，在%zone心情不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '哇，%zone全是59级的，我才42……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '在%zone挖点铁，有人要来吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '有人在%zone升级需要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '怀念厄运之槌刚开那会儿，现在灼热峡谷都觉得一个样了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '我在练锻造，谁有铁矿石？%zone。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '哈哈，猎人在玛拉顿啥都要。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone今天到此为止，去厄运之槌找几个59级的……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '灼热峡谷有啥技巧吗？我得在这儿刷会儿，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone这刷新速度，让我开始怀疑人生了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '哈哈，我刚在灼热峡谷被抢了装备。掉落真行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone的刷新计时太狠了，别人也这么觉得吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone的猎人听着，你们可以跳舞，/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '在灼热峡谷卡任务了，求指点？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '好久没见过%zone这些怪了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 51, 0, 0, 0, 10, '%zone这延迟受不了，今天感觉特别卡。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '嘿，%zone是烂，但刷新快啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '大家好，求%zone入口的打架队友。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '大家好，%zone走哪条路最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone太磨了，还有谁在这儿受苦？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '大家好，%zone哪儿的怪好打？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone全是亡灵，还有谁爱打亡灵？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone的各位好！我是新来的，走哪条路最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '正在祖尔法拉克捡东西。%zone有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '哈哈，我发誓%zone的亡灵越来越漂亮了，有点吓人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '泰达希尔今天好安静，一个人都没有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '又一天，又被豺狼人揍脸。爱了%zone。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone的蜘蛛怎么这么大？它们也该找点正事干干了哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '我觉得%zone的野猪人在密谋对付我们。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '我要是在%zone每死一次能得一毛钱就好了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone的亡灵让我开始反思人生。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '有人在%zone能帮我做那个兽人的任务吗？我迷路了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '不敢相信我忘了带血瓶，在%zone又要死一次了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone的亡灵怎么这么快？我跑不过它们！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '大家好，%zone散步还愉快吗？不过这里的怪挺硬的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '今天在%zone附近刷怪，刚攒到40金币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '有人知道泰达希尔那些任务在哪接吗？到处都是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '想找人一起逛逛%zone，有人来吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '哇，我在%zone又被抢装备了……又一次。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '真希望他们修修%zone的寻路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '有人要组队去%zone吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone的僵尸现在太狠了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '不懂为啥有人讨厌%zone，满满的情怀啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽鳄鱼也太多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽加上猎人……图啥呢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '大家好，谁有%zone的地图多一份？这儿的怪简直像沼泽热一样烦人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '超爱悲伤沼泽的氛围，但亡灵老抢我的午饭。还有谁这样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '小心树人，在%zone它们会悄悄摸到你背后');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '太感谢在悲伤沼泽的帮忙了。那些鹰身人让我恨不得会盗贼的潜行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '我在悲伤沼泽刷了一整天，咋啥都不掉啊？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '有人想跟我去%zone吗？亡灵多，乐子也多！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '谁准备在%zone来场斗舞？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽的怪挺凶的。这地方咋这么多？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '有人要帮忙做%zone那个任务吗？我有个盗贼朋友，捉迷藏大师。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '我急需%zone的向导，有几个任务要做。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽，有人要去找老磨坊吗？我带路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽的任务最棒，但那些树人太瘆人了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '这%zone有点太脏了，不太合我胃口。等升完级就走。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '谢谢提醒，我%zone新来的，这儿跟迷宫似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '有人在%zone迷路好几天吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '大家好，%zone怎么刷最快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽的鱼人，有个好奶妈就很好打。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '%zone的刷新到底怎么回事啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽有个任务需要帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽是真的沼泽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '悲伤沼泽这些浑水真烦人，不过剧情很棒。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '哈哈，又在%zone迷路了，还有谁受够这些鳄鱼了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 8, 0, 0, 0, 10, '原来悲伤沼泽就这感觉：泥，更多泥，还有更多泥。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '%zone早安。有人做完上层精灵的任务了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '不知道为啥，我就喜欢%zone的布置，让我想起自家后院');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '哇，艾萨拉今天纳加成群。小心点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '不敢相信又得做一遍艾萨拉的任务线，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '我在%zone运气差到爆，跟被纳加诅咒了似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '我爱%zone，但任务做起来真要命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '有人想干脆在%zone乱跑，任务不管了？就瞎逛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '这任务怎么老把我支到%zone另一头去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '刚在艾萨拉刷了好几小时铁。鱼人刷得比矿点还多。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '怎么人人都想在艾萨拉挖铁矿石？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '刚在%zone出了个稀有掉落。不过也没那么稀有。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '有人要帮忙做艾萨拉的上层精灵任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '还记得我们以前觉得泰达希尔很吓人吗？现在就是散步');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉的怪刷新怎么这么快？我发誓它们就等着你走。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '我又被萨特打死了。又一次。还有谁在%zone受苦？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉的怪干嘛跑那么远啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '我发誓艾萨拉的蜘蛛越来越大了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '猎人在艾萨拉啥都要。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '在%zone我死活找不到任务怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉好美，但那些树人打起来是噩梦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉对我这等级太危险了，不过风景值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '靠，艾萨拉你都把我逼疯了？赶紧打死这玩意。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉的怪没完没了，怎么这么多杂兵。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人能借我点钱做%zone那个任务吗？想找人一起分');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone的任务太无聊了，我觉得光抱树都能升级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '%zone是危险，但经验真好，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '嘿，有人在%zone或附近需要采药吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '抱歉，我还得点时间把艾萨拉任务做完才能走。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉晚上好漂亮，爱这氛围。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉是我的最爱，任务挺有意思，特别是鱼人部族那些。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '还有谁觉得%zone的任务是游戏里最好的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '有人知道从%zone快速回入口的路吗？谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉这儿的萨特小心点，那帮家伙很恶心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉晚上感觉特别危险。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '%zone的萨特真把我搞崩溃了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '小心%zone的萨特，它们能给你上恐惧，而且任务NPC好难找');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '%zone的任务有攻略吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '我喜欢艾萨拉的宝藏，但树人太吓人了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '有人能给%zone出个奶吗？求治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '%zone小心点，那些猎犬挺凶的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉的任务太磨人了，得歇会儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉，哈哈，怎么人人在这儿迷路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '想找人一起打穿%zone？求组。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉，风景我爱，虫子就算了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 16, 0, 0, 0, 10, '艾萨拉，这任务快把我弄死了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山又全是这些该死的蜥蜴。它们就不能老实待着吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '没事，我就在%zone看看风景，正好需要点安静');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '欢迎大家来%zone，谢谢我进来时的欢迎，有人作伴真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我有多余的元素之金锭，%zone有锻造要吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山没了平时那帮人，感觉空荡荡的。人都去哪了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '哈哈，刚有人在%zone跟蜥蜴跳舞。/dance经典。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '有人能告诉我安戈洛环形山哪儿采药最好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山没了那史诗音乐就不对味了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我就是来%zone刷矿的，马上回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '他们就不能把%zone的元素怪改好刷点吗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone美是美，但那些火鸟太狠了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '谢谢在%zone帮我打那些火鸟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '大家好，第一次来%zone。怎么去下一个任务点？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我爱安戈洛环形山这儿的任务，很有挑战。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '还有谁喜欢%zone的熔岩地带？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '别忘了去看看洞穴，%zone里岩浆不少。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '嘿，%zone有更快的穿行路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '刚在%zone干了只巨型蜥蜴，太爽了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山的刷新最烦人，游戏真是谢谢你了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '看来%zone今晚挺热闹的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '好怀念%zone那种老派的感觉。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '刚在%zone被刷出来的怪打死了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '大家好，我是%zone新人，有人能给点打大蜥蜴的建议吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '真不敢信%zone有这么多萨特。我发誓见到的萨特比任务NPC还多哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '恭喜拿到那坐骑，我知道在%zone弄到有多难。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '哈哈刚在%zone被激光炮塔干趴了，尽管笑吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '还有谁觉得%zone热得受不了？谢谢救命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone的火元素小心点，烦得很。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '你好，%zone有人需要帮忙做任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone问好，满满回忆，还有一堆虫子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '真不敢相信这么多人需要帮忙打%zone的火元素，我还以为都是猎人呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone有采药的好地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone怎么刷这么多火元素？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山今天跟熔岩桑拿似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone那个收集羽毛的任务不容易。我发誓那些羽毛朋友可不乐意');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '有人知道走北边小路去%zone的快捷方式吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '只有安戈洛环形山能让我觉得自己是个熔岩怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我需要有人给我讲讲%zone这些任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '还有谁受够了%zone这些重复任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山就是我一直带水袋的原因。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '有人能在%zone帮我打豺狼人吗？谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我爱%zone的背景音乐，但那些怪有时候能把我打哭。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '哈哈我的猎人在%zone老打错东西。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '大家好，%zone现在异种虫成群，外面小心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '哇，安戈洛环形山的掉落总是这么随机，我就想要双好靴子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '大家早，有人知道%zone哪儿能刷皮吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '大家好，%zone对新人有点难，希望大家都玩得开心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '黑石深渊练级不错，但%zone跟朋友一起好玩多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我发誓，每次我清一个虫巢%zone的刷新计时就离谱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '猎人在%zone就是：要多点弹药，太谢谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '厄运之槌是最棒的副本，但%zone还是我最爱的采药地。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '祖尔法拉克不错，但%zone的怪掉落更好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone的各位好，想让大家动起来就/跳舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '在%zone，我就缺一双好靴子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '玛拉顿挺难，但%zone让一切都值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山，满满回忆哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 141, 0, 0, 0, 10, '%zone的树人最近闹得挺凶，当心！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '大家好，我就是来%zone做任务的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '有%zone的情怀，谁还要地图。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '你们都怎么对付%zone的精英怪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '好怀念%zone刚开那会儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone这精英刷的位置真绝了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '我喜欢%zone的氛围，但精英怪太吓人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '大家好，刚到%zone，这岩浆都比我老婆做的菜还烫。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '有人知道安戈洛环形山这附近哪儿找元素领主吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '外面小心，%zone的毁灭者刷疯了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '刚做完熔岩池任务，在安戈洛环形山升级真爽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone今天够呛。今天杀了第100只豺狼人。哈哈，它们就是不肯消停。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '马上回来，要做点东西，%zone稍等。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '%zone有奶妈来快速打一趟吗？我们得打元素。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '猎人在%zone这儿怎么总是啥都要？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '安戈洛环形山的火元素挺烦，但火抗装备真香。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 490, 0, 0, 0, 10, '刚从%zone的元素任务回来，哈哈，差点被火元素烤了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谢了，有人知道去%zone食人魔那儿最快的路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的萨特小心点，打人很疼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林里树人很多，小心点，那儿一团糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的萨特任务需要帮忙吗？说一声。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的树人小心，很容易把你定住。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '有人能帮我在%zone刷矿吗？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林任务卡住了，求帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谢谢帮忙，%zone轻松搞定，就是别被萨特魅惑了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的任务有啥技巧吗？我是新来的，谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的萨特任务卡住了，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林真烦，全是萨特和它们那破魅惑。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谁做过费伍德森林的日常？贼烦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '有人知道最快穿过费伍德森林的路吗？我赶时间。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '哈哈，别站火里，懂？%zone很危险。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谁要帮忙打费伍德森林的萨特？我躲不开它们的法术。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林挺烦，但掉落还行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '喜欢艾尔文森林这种安静的感觉，让我想起家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone的各位好啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '想去玛拉顿吗？离%zone不远。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '大家好，费伍德森林今晚乱得很，树人太多了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '还有谁在%zone做木喉任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '马上回来，费伍德森林的刷新快把我逼疯了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '哈哈，费伍德森林费伍德森林，真是一个圈绕回来了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '大家好，谁卡在费伍德森林任务上我来帮。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '怀念费伍德森林以前的任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的各位都还好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '还有谁觉得%zone不该全是萨特？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '还有谁喜欢费伍德森林的剧情和任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '杜隆塔尔今天全是蜥蜴人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '%zone的萨特怎么这么难打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '大家好，回费伍德森林了。有人要组队做任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谁有多余的治疗药水？我在费伍德森林一直死。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谢谢帮忙清费伍德森林的杂兵。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '你知道吗，费伍德森林感觉完全是另一个世界。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '哈哈，我又在费伍德森林迷路了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '有人注意到费伍德森林的怪变密了吗？感觉哪儿都去不了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林晚上很赞，完全是另一种氛围。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的任务好难找到队伍。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林越来越危险了，最好带个朋友。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone那些老玩家都去哪了，出来出来，不管你在哪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '我老死在费伍德森林的毒蛇手上。还有谁也这样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '哦不，又是费伍德森林……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林，任务还差一个人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '剧情太棒了，我爱这地方。%zone全是谜团。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林晚上挺瘆人，但那些任务值。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谁知道费伍德森林哪儿打怪好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林怎么全是魔化兽和魔化软泥？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '大家好，费伍德森林真烦，但经验太香了哈哈，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谢谢各位帮忙，费伍德森林是噩梦，但钱好赚。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '哦太好了，费伍德森林又一只小精灵，又得多采点药了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone哪儿学剥皮？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '我发誓费伍德森林的地精最烦人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '在做萨特的任务，费伍德森林这任务没完没了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的恶魔卫士需要有人抗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林又卡了。真棒，棒极了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '%zone小技巧：贴着树走，潜行很有用。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '费伍德森林的刷新太烂了，这精英我等了15分钟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '记得留着buff，我们不需要再来一个%zone的查克·诺里斯。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '我在%zone老迷路，是不是该弄张地图？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 361, 0, 0, 0, 10, '谁有多余的血瓶？费伍德森林太耗血了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '马上回来，有个50级法师任务，%zone太狠了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哈哈真不敢信我在%zone迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '有人能指给我燃烧平原的飞行点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '哈哈我刚跑过去就看见一只豺狼人，%zone全是这玩意。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '%zone总是很热。为啥这却是我最爱的地方？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '我还记得燃烧平原刚开的时候，恍如昨日。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '%zone是个歇脚的好地方，我喜欢这景色。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原的任务需要帮忙，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '刚把燃烧平原的任务做完了，谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '你知道吗，燃烧平原是最适合采药的地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '我超爱%zone的龙人精英，真有挑战。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原的任务太有情怀了，还记得那些。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '找人带我逛逛杜隆塔尔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '小心蜥蜴，它们最爱在%zone拖慢你。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '我终于在燃烧平原拿到需要的药剂配方了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '你们在%zone怎么采药？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '不敢相信我终于在%zone找到那个火焰图腾了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '这等级来燃烧平原弄装备很合适。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '你们还记得以前在%zone打架的日子吗，真好玩，真怀念。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原一团糟，刷得太多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原是烦，但我喜欢那些火元素。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原得消停点，一卡就是个死亡陷阱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '刚打完奥达曼，现在去%zone。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我需要帮忙做%zone这个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '猎人们都是怎么做到的，%zone挺难的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '谢谢蹲点，我跑回%zone做任务了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原今天全是火元素哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '今天黑石塔下层是噩梦，不过燃烧平原还行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '刚在%zone被抢了装备，服了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原太热了，刚中了个火焰法术。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '还是讨厌%zone那刷新计时。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '刚打完黑石深渊，现在燃烧平原感觉好轻松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '%zone怎么这么卡？纯问问。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '哈哈我刚到。我们在%zone干啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '在杜隆塔尔刷皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '我怎么老卡在燃烧平原的火元素巡逻队上？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '在燃烧平原再刷几级，然后就能玩点正经内容了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '有人能帮我做燃烧平原的火元素任务吗？我一直死。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '%zone挺难，到处都是豺狼人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '山那边%zone在烧，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原，轻松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原全是陷阱，我需要个坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '大家好，%zone有啥新鲜事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '恭喜击杀，有人在%zone需要帮忙做任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '嘿，大家在%zone任务做得咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '马上回来，去看看%zone的采药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '燃烧平原这儿食人魔怎么这么多？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '太谢谢在%zone的帮忙了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '还有谁卡在%zone同一个任务上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 46, 0, 0, 0, 10, '怀念以前%zone没那么挤的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '诅咒之地真烂，这刷新太离谱了，我都在这儿好几个小时了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '受够%zone刷的恶魔卫士了，延迟太糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone最喜欢的地方？通往塔纳利斯的传送门。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone到处都是巨魔和恶魔卫士。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '大家好，%zone咋样？我的猎人一直卡。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '从这儿怎么去沉没的神庙，%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我喜欢%zone，但那些豺狼人真是看腻了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '我是新手，从%zone去沉没的神庙最快怎么走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '大家好，%zone怎么练级最好？我是圣骑士。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '这儿的掉落太烂了，真希望%zone的怪多掉点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '我的术士在%zone怎么卡得跟疯了似的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '我刚在%zone第十次复活了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '大家好，咋样？刚到诅咒之地。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '嘿各位，做任务穿过%zone最快怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '诅咒之地这儿的盗贼小心点，抢装备跟上班似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '任务进度落后的话，诅咒之地就是噩梦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '刷刷刷。我在%zone为啥选了采矿。为啥啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '刚在艾尔文森林剥了第一张狼皮，感觉真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '刚在%zone撞上一只迅猛龙哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '在诅咒之地小心火元素，一下就能秒了你。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '谢谢大家给的任务提示，诅咒之地其实也没那么糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '我感觉%zone的草药都被我采光了，还有人知道别的地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '靠，我在诅咒之地被这些元素怪揍惨了，想念我以前的猎人宠物');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone的刷新怎么这么慢啊？我都等得感觉过了几辈子了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '小心%zone周围的高级怪，打人疼得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '有人知道%zone升级的好路线吗？我怎么找都找不到像样的经验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '想在%zone找路结果迷路了，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '真不敢相信40级时%zone的怪这么强，厄运之槌我还不敢想');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '真希望%zone任务多点，太无聊了，走路走得要死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我在%zone，想冲到15级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone怎么这么卡？我快疯了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '刚做完诅咒之地那些恶魔野兽的任务，真是一波三折。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '谢谢大家帮我做%zone的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone那些恶魔野兽洞穴可不是闹着玩的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '哈哈，%zone的恶魔兽人只要躲开那几下顺劈，其实挺好打的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '我在%zone的隧道里迷路了，那该死的门到底在哪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone的恶魔潜伏者小心点，打得挺疼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '太谢谢%zone的建议了，任务好做多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone的各位好啊，都在忙啥呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '有人知道任务怪在哪吗？%zone看着有点空');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '有人知道%zone的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone的大家好，想找队伍打黑石深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '诅咒之地天气不错，可那个石头的任务快把我逼疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '坦克还差几根铁锭，有人知道%zone哪儿挖矿好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '火元素我杀了三遍了，%zone我是真快放弃了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '%zone这些异种虫群真是烦死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '哈哈，在诅咒之地又迷路在同一个洞穴里了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '抱歉来晚了，又卡在黑沼里了。诅咒之地总是这么“好玩”');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '哈哈哈，得是猎人才懂在诅咒之地的苦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '别走太深，不然在诅咒之地会迷路的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '在诅咒之地，我们杀这些恶魔潜伏者图啥？刷得比我打字还快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '有人需要帮忙在%zone刷皮吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '诅咒之地太空了，跟鬼城似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '有人知道%zone刷怪的好地方吗？待好久了，不想去玛拉顿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '我一进%zone就卡，太烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '真不敢相信我在%zone还得杀恶魔兽人，怀念以前的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 3, 4, 0, 0, 0, 10, '对不住各位，我得从%zone这堆恶魔卫士里跑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷真漂亮，但也真冷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我在%zone找材料。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷是不是最魔幻的地方？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '哈哈，我被冬泉谷的狼咬死了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷藏着不少好宝贝。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '刚在%zone开始，刷到2级有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone任务这么多，从哪开始啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我在冬泉谷找那个雪人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '快速穿过%zone的最佳路线是啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '就在冬泉谷采药。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '猎人得去%zone做那个任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone的任务我是真做腻了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷是我最不喜欢的地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷的怪对我来说有点强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我不太喜欢%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '哈哈，我老被冬泉谷的树人弄死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '小心%zone的食人魔，一拳一个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷这地方真美，可这延迟要我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '有人能帮我做冬泉谷的任务吗？难是难，但挺好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '熔火之心真是绝了，小怪刷个没完，冬泉谷跟那儿比差远了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '没去过通灵学院的话，冬泉谷的任务有点难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷的雪是真不错，可那些冰霜巨魔不太好惹');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷今天有点安静，估计是暴风雨前的宁静');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone的狼让我怀念当年单刷什么都不费劲的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我发誓%zone越来越卡了，我还以为要卡在那棵树里了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷的雪太刺眼了，得戴墨镜，这会儿真想去黑翼之巢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone有些怪刷新得邪门，我剥皮的时候被一群雪人围了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone新来的，前期任务走哪条线最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '有没有发现%zone的人都比较悠闲？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '打团本前得把冬泉谷几个任务收尾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '唉，猎人永远缺弹药……在%zone也一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '哟，又一个冬泉谷任务，再杀10只怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷挺安静的，直到你听见雪人的嚎叫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '刚从%zone的大黑龙身上出了件好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '在冬泉谷绕着冰巨魔跑，冷风一吹我真是受不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '去%zone接个新任务，结果被雪豹袭击了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone的雪豹小心点，跑得贼快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '冬泉谷太美了，就是冷得刺骨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '钱快花光了。有人在%zone需要猎人帮忙清怪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我去，%zone这暴风雪一团糟，比冬天还狠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone别往北走太远，回来的路老长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '这地方把我冻得屁股都僵了，你们觉得%zone咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我在%zone猎冬狼群，有人一起吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我就在%zone待着，看看风景，享受下安静');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '我的法师法杖在%zone被人抢了，你敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 618, 0, 0, 0, 10, '%zone是不是很棒？松树和冰凉的空气爱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '在%zone挖矿，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '我喜欢西瘟疫之地的氛围');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '终于在%zone出了个稀有掉落！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我想念%zone过去的日子，那时候什么都新鲜，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '在%zone采药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '这地方总是空的，%zone怎么这么冷清');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '有人知道怎么快速穿过%zone吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '天啊，我讨厌%zone的瘟疫老鼠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '还有谁怀念西瘟疫之地以前那些简单的日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone越来越挤了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '大家好，今天有人刷西瘟疫之地吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone别抢装备啊，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '哪儿能找个打黑石塔上层的队？我在%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '嘿，%zone的60级副本缺个猎人，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哈哈，又在%zone卡石头里了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone全是亡灵，任务挺虐但值。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '这么多年了，%zone的亡灵还是感觉不太对劲。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '哈哈%zone，还在跟天灾军团死磕。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone声望最高的商人上哪找？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '今晚最后一杀到手，谢谢%zone这一趟。对了，我还想去黑翼之巢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '摸奥妮克希亚太难了，%zone路不好走但值。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone的团本挺好玩的，就是有时候卡得没法玩。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone的瘟疫犬真该死了，哈哈我都无语了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '等掉等累了，%zone的团本感觉没完没了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '斯坦索姆太狠了，%zone的团本可不是闹着玩的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone挣钱太容易了，就是得肝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '在%zone小心点，我差点就死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '有人知道%zone的好路线吗？我赶时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '怀念以前，%zone现在感觉空空的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '最近去%zone的队怎么样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '谁愿意帮我跑几趟%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '西瘟疫之地是阴森了点，但亡灵刷得多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '嘿，有人知道天灾陨落任务的路线吗？%zone太绕了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone的亡灵刷得跟不要命似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '总有一天我要把西瘟疫之地的亡灵杀光。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone是真折腾，但我还挺喜欢这种挑战');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '我得在这待一阵了，%zone的亡灵跟流水一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone的洞穴很黑，当心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '我就喜欢能在%zone刷一整天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '有人在%zone有任务需要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '在%zone顺手刷了点符文和草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone怎么练附魔最快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '血色十字军是真烦人，不过%zone我爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '挺好，大家还在%zone刷呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '能帮忙做个新手的%zone任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone最后一个任务求帮忙，时候不早了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone升级怎么弄最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '%zone老是那几条刷怪路线，腻了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我不喜欢%zone的兽人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '有点怀念那个%zone，感觉挺特别的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '想在%zone刷金币，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 28, 0, 0, 0, 10, '现在还有人在%zone做任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '欢迎来%zone，是有点阴森，但任务很棒。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone的亡灵留点神，它们会偷袭。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '在%zone塔边上找了个不错的刷怪点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone地形糙，别把坐骑弄丢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone路边锻造材料挺多的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '还有谁记得当年在%zone刷怪的好日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone哪里刷布最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone那个洞不错，谢天谢地没有食人魔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地挺瘆人，不过我无所谓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '我在%zone老是被悲惨的亡灵弄死，gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '亡灵真是受够了，%zone我真快扛不住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '又是%zone平凡的一天，能不能快点找到那座浮空城？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地挺瘆人，任务倒还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '在%zone抗亡灵，有点怀念以前刷副本的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '有%zone谁还要阳光啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '我讨厌天灾，但至少%zone挺有意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地一直是我最爱，这地方有股特别的劲儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '不知道大家为啥都讨厌%zone，也没那么糟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '谢谢帮忙打%zone的兽人，太惨烈了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '有人知道最好的装备在哪弄吗？我困在%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone的骷髅太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '我在东瘟疫之地刷黑铁护甲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '有人知道快速穿过东瘟疫之地的路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地清一波怪要这么久，真不敢相信。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地今天好卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone哪儿能买到更好的盾？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone这刷新速度我真受不了了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地太阴森了，我爱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '在东瘟疫之地小心那些悲惨的亡灵。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '大家嗨，我又回%zone了。又一次。好耶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地是我的心之所向，多谢啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '真不敢相信我还在%zone迷路，就想找条对的路出去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地让我想把整张图的任务都做了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '谁知道%zone怎么弄到最好的战利品？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地单刷瘟疫僵尸有啥诀窍吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '我就喜欢%zone的剧情和任务能串起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '还有谁喜欢%zone的氛围吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '穿东瘟疫之地最快的路线是哪条？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '在%zone发现个小洞穴，白拿了点经验，结果现在被僵尸追着跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '又在%zone迷路了，谁知道出口在哪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '杜隆塔尔的狼挺烦，不过嘛，谁不是从新手过来的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '我喜欢%zone的剧情，不过血色十字军有点搞笑，对吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '好极了，%zone又下雨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '60级在东瘟疫之地刷亡灵，为下一件装备攒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '%zone有几个刷金币的好地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '在东瘟疫之地刷啊刷，得为熔火之心做准备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '想搞史诗坐骑，东瘟疫之地最合适');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '有东瘟疫之地谁还需要治疗啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '东瘟疫之地的任务挺瘆人，不过经验谢谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '在东瘟疫之地刷皮革');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 139, 0, 0, 0, 10, '天，东瘟疫之地走起来就跟逛墓地一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '还有谁在%zone给部落刷声望');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '%zone这刷新真折磨人，跟个没完没了的副本似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '这地方历史底蕴很足，我喜欢%zone的氛围。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '%zone的异种虫不会放弃，我也不会');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '这个%zone怎么人人都要法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '在%zone反复摸同样的东西，腻了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '我是真爱%zone这感觉，这儿的任务怎么做都不够。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '这%zone怎么卡成这样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '谁要猎人？%zone我找不着不飞的异种虫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '这%zone的掉落差得我真不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '嘿，有人知道穿%zone最快的路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '经典就是经典，杜隆塔尔还是最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '我有多余的草药要卖，%zone产量足');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '有人能帮我找%zone的丝蜘蛛吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '还记得我们第一次在%zone刷小号装备吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '还有谁怀念%zone以前的好日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '有人有多的希利苏斯声望任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '希利苏斯的异种虫怎么老成群结队的，服了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '住在希利苏斯跟住沙漠一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '希利苏斯对猎人来说就是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '又能看到希利苏斯了，好激动');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '咱们组个队去%zone吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '刚拿到鱼竿，有人知道%zone最好的钓点吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '希利苏斯的任务给的金币还不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '有人想一起去刷希利苏斯声望吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '我去，希利苏斯这些任务要我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '哈哈，我刷%zone就是为了躲曼克里克的妻子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '刚到60级，在%zone，有人黑翼之巢缺治疗吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '有人在%zone见过暮光之锤的声望任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '希利苏斯真美，可这些树人真硬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '我就在%zone待着刷声望，得做日常了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '有人知道%zone怎么绕过那些虫子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '可惜%zone又满地都是异种虫巢领主了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '哈哈刚被一头野猪追着跑遍了艾尔文森林');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '第一次来艾尔文森林，去哪刷装备最好？简单说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '这任务真离谱，杜隆塔尔真会折腾人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '没有暮光之锤那帮人，希利苏斯都不一样了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '看见一队玩家在%zone跟李洛伊似的乱冲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '有猎人想组队打希利苏斯的其拉领主吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '%zone让我怀念希利苏斯任务的好时光。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '靠，%zone的bug太多了，任务都做不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 4, 1377, 0, 0, 0, 10, '%zone的任务还是跟以前一样烦');
