INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '有人知道杜隆塔尔刷皮的好路线吗，刚入坑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '我就喜欢暴风城卫兵那副这地方是他们家的样子');
