INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '嘿，%zone有卖水的吗，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '别吧，%zone又一具尸体，我最看不得这个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城今天真挤');
