INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '有人知道暴风城哪里钓鱼好吗，我在这转了半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '嗨，有人在杜隆塔尔做任务吗？我需要个伴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '刚来暴风城，这儿的任务从哪开始？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '刷金币最好的地方是暴风城，信我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '我喜欢暴风城的氛围，让我觉得自己像个真英雄');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城的各位好，看到这么多熟面孔真不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城今天挺热闹，新卫兵任务在哪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城的朋友们好，有人找公会吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城好啊，怎么新手法师在这儿刷得这么狠？');
