INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '刚在暴风城弄到新猎人宠物！哈哈，太自豪了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我就是喜欢%zone的氛围，可这些怪一直弄死我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城今天真热闹，喜欢这氛围');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '大家好，20级在%zone有什么好任务？');
