INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城卫兵跟我妈似的，老对我指手画脚。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '怀念以前在暴风城转一圈就能找到队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '找队伍去%zone干掉迪菲亚兄弟会');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '还有谁在暴风城被迪菲亚兄弟会任务卡住了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '杜隆塔尔摸东西感觉好少见，不过大概这也是乐趣的一部分');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城今天忙疯了，祝你躲卫兵顺利');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城有时候跟迷宫似的，集中点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1519, 0, 0, 0, 10, '暴风城，哈哈我就是得做那个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '我刚开始的时候这地方就是噩梦，%zone真是太让人怀念了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '走开一下，去山边刷点石头，没钱的时候铁炉堡真难混');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '去深谷只能穿过%zone，NPC太多了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '就差练制皮了，铁炉堡的制皮师最棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '大家怎么都抱怨%zone，也没那么差啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '我还缺铁矿练采矿，铁炉堡啥都有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡的矮人老是火气大，好像缺酒喝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '大家好！我%zone新来的，能分享点建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '还是不敢相信去%zone这么贵，我们没钱啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '各位好，从%zone去深炉怎么走最快？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡最近太挤了，跟过节似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '我得从%zone去秘法圣所，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone刷新这么慢，真不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '有人知道在%zone刷皮的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '这个收锈钥匙的任务太简单了，%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone能做的好多，可我包满了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '怀念%zone野外PVP还多的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '我喜欢%zone的氛围，让我想起从前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '欢迎来到%zone哈哈，这兔子的刷新速度太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '有人知道杜隆塔尔今天为啥这么卡吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '问一下，有人知道最近黑铁矮人在%zone哪儿扎营吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '谁能帮我找找铁皮？我在%zone转了半天了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '就喜欢%zone铁匠铺那敲打声，让我想起我第一个角色。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '我又在矿洞里迷路了，有人知道%zone的近道吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '黑铁矮人在%zone可真是让我吃了不少苦头。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '还有人觉得%zone的铁皮任务有点难吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁皮任务真是烦死人，老是在%zone冒出来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '怀念以前在%zone随便溜达，不用担心被黑铁矮人围殴的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '还有谁觉得%zone的黑铁矮人特烦？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone哪儿能找到黑铁间谍啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '谢谢%zone的治疗，就缓口气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡是漂亮，就是黑铁矮人太闹心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '黑铁矮人干嘛在铁炉堡盯着我们？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '等不及再去%zone的深矿刷一趟了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone那些黑铁矮人怎么老鬼鬼祟祟的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡的黑铁间谍最烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '黑铁矮人怎么老想抢我%zone的装备？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone到处都是黑铁矮人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '黑铁矮人干嘛在铁炉堡跟我们过不去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '黑铁间谍简直是铁炉堡的心头大患。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '今天铁炉堡人真多，黑铁矮人都上哪儿去了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哇，%zone又冒出一只狼人，它们什么时候繁殖这么多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '一会回来，%zone还有个任务要交，得杀10只岩虫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡这建筑真气派，让我想起从前的样子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '谢谢大家在铁炉堡帮我做任务，大半夜的还真不容易');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '有人想去做黑铁矮人的任务吗？铁炉堡这边这类任务一大堆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '真希望%zone能搞个斗舞什么的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '咱们在%zone组个队做黑铁任务怎么样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '组队刷装备，%zone的石虫需要人帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '真不敢相信又回铁炉堡了，石原那个破任务我都做多少遍了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '真想逛逛铁炉堡不用被那些该死的侏儒烦，不过也没啥好抱怨的，这毕竟是%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone的氛围总是那么舒服，让人怀念以前的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '%zone的部落、这些任务，我觉得我早该来这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '这卡得受不了，在%zone连点小事都干不成');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡每个任务都设计得挺好，我就喜欢%zone背后的故事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '一会回来，得去补点药，别在%zone把蓝耗光了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '真希望铁炉堡的掉落别那么看脸，心态崩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡又一天，至少没被什么东西吃掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '刚入坑，%zone有几个阵营啊？怎么加入？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '我在%zone转了好几个小时，得找到出口，我都开始把墙看出人脸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '%zone的各位好啊，今天都咋样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1537, 0, 0, 0, 10, '铁炉堡，有人能指我去飞行管理员那儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯今天熊怪真多，我看它们快成新树人了，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '呃，%zone又来一只那种巨魔，我开始烦它们了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '谢谢帮忙刷声望，达纳苏斯一直都这么热闹。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯今天好冷清，我该去升升级了，这任务太简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '要草药的来达纳苏斯附近找我，我在采，私聊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯这几天缺猎人，怎么这么多猎人老要东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '卧槽%zone这任务真变态，谁想出来在达纳苏斯放小精灵的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '想去达纳苏斯刷剥皮，还有谁要一起剥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '每次去达纳苏斯我都想起猎人为什么这么缺东西，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯真安静，离%zone也够远的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '我去达纳苏斯采了点草药，挺容易的，赚了点金币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯最近人太多太热闹了，我连跳舞的地方都没有。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哈哈，你们看见那个新手在%zone围着巨魔绕圈圈吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '大家都该去达纳苏斯，那边的任务超赞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '欢迎来%zone，大家今天都咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯的冒险者们好，最近咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '试过%zone的蜘蛛没？得有把好法杖');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '哈哈，我还在达纳苏斯绕圈找那个发任务的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '在达纳苏斯钓过鱼没？我好像上错钩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '唉，%zone又一天。好在任务不难，太谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '还有谁在达纳苏斯纯刷等级的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '刚在%zone拿到第一只坐骑，终于！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯的钓鱼试过没？真该去试试');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '我刚看着%zone另一个部落玩家想从巨魔那儿跑掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '大家好，欢迎来达纳苏斯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '哎哟，今天%zone的刷新时间太坑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '有人缺人吗？%zone快刷一波');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '好家伙，刚在达纳苏斯被人抢了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯大家都在哪儿混啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯老样子，总有东西出毛病');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '嘿，我刚到%zone，这附近有什么好刷的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '怀念以前在%zone跑一路都不带引怪的日子，现在走五步就得打一架');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯真安宁，连卫兵看着都在笑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '有人要帮忙做%zone的任务吗？我有空');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '就差把任务做完然后赶紧离开这%zone，这些任务得搞定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '你知道人家怎么说嘛，%zone的树比你妈年纪都大');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '还记得查克·诺里斯能在%zone找到的时候吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '我在找微光苔藓，有人知道%zone哪儿刷吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '有人想随便去%zone走走吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '这地方勾起太多回忆了，%zone的好时光');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '今天天气真好，正适合在达纳苏斯溜达');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '谢谢帮忙清了%zone那堆精英，我卡了快20分钟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '我发誓达纳苏斯有时候卡得没法玩，不过真漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '刚做完达纳苏斯那个史诗任务，终于完成，太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '哈哈我在%zone迷路了，结果找到几株稀有草药，太值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '想组队打死亡矿井，已经在%zone跑了几个小时了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '哎，我在达纳苏斯得找几个钓鱼点，任务要交');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '最烦在%zone刷着刷着就卡，我还挺怀念以前的网');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '%zone的树人真气派，就喜欢这儿的故事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '还有谁喜欢达纳苏斯的氛围？感觉特别宁静');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '想在%zone练采矿，可矿点分得太散了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '记得那种啥都要的猎人吗？我在达纳苏斯就是那种猎人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '要是来升级的，记得盯着%zone银行那个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '想刷稀有掉落的话，%zone有几个稀有刷新点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '达纳苏斯走起来挺远，记得把任务点都跑一遍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '有人能带我去趟%zone银行吗？找个人一起过去就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哈哈，猎人在%zone什么都要。我们该列个清单把所有需要的写下来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '%zone那些萨特比我想的硬，得换个打法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '记得从林子那边抄近道去%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '在%zone死活找不到人组队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '我在%zone刷了5个小时了，还在挣金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '终于在达纳苏斯到40级了，接下来干啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '有人能帮我打%zone的萨特吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '还得在%zone弄坐骑，还剩几个任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '真不敢相信为了%zone得杀上千只恶魔野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '能组个队去打%zone的费伍德首领吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1657, 0, 0, 0, 10, '李洛伊·詹金斯在%zone能笑死你，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我就在%zone找狗头人，有啥建议吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '真得说那个猎人，在杜隆塔尔还想跟巨魔/dance。史诗级翻车。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '卧槽今天%zone卡疯了，谢谢你，兽人直接刷我脸上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '老兄我真喜欢奥格瑞玛的氛围，兽人有味儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '我在%zone一次拉一大群怪，烦透了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '真讨厌在%zone刷在一群怪中间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '我喜欢%zone的任务线，可这卡得要我命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '在%zone装备永远不嫌多，就是刷新太成问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '%zone的怪是硬，但掉落值得');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '这是升级最好的地方，就是%zone的兽人老刷新');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛容易迷路，不过任务真不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '今天奥格瑞玛好热闹！你觉得我该从哪儿开始');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '马上回来，去把%zone那只狼人解决了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '%zone的朋友好！有人在做码头那边地精的任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛的各位好啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛永远这么有生气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '求组%zone下水道老鼠那个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '我真是太爱%zone了，多好的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '大家好，我刚入公会，有人在奥格瑞玛吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '大家好，我是新来的，在奥格瑞玛怎么升级最快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '今天奥格瑞玛太挤了，有人知道清静点的刷怪地儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '刚在%zone找到个不错的矿点，谁要矿的话说一声。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '欢迎大家来奥格瑞玛！还有谁是新人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '大家好，还有谁在刷%zone那些任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '巨魔和他们的任务在%zone永远没个头');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '少了老卫兵巡逻，奥格瑞玛显得空荡荡的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '刚来%zone，正在摸地形');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛的任务是难，不过奖励值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '%zone的卫兵还是那么脾气臭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '凌晨两点的奥格瑞玛？就我和那帮盗贼，感觉挺好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '我就爱%zone的氛围，简直是待着最舒服的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '我怎么老在%zone摸到最烂的装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛其实还行，只要你不介意兽人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '%zone的刷新时间感觉跟等一辈子似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '喜欢%zone的气氛，但那些狗头人真是没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '为什么我在%zone骑坐骑就是跑不快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛让我想起当年的魔兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '%zone卡得一批，心态炸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '我可太想%zone了，连食人魔都想');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '奥格瑞玛的任务太简单了，难怪我觉得没意思……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '刚又在%zone刷了遍下水道，那些鱼人是真看腻了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '还有谁觉得奥格瑞玛的卫兵有点太爱动手了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '小心食人魔，%zone可不是能放松警惕的地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '有人能帮我做奥格瑞玛铁匠那个任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '怀念以前在%zone每件装备都得拼命抢的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哈哈我在%zone还是完全不知道自己在干啥，不过嘛，升级嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '这里是部落的心脏，奥格瑞玛和斯通纳德感觉完全不一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '你知道%zone那些鱼人群的情况吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1637, 0, 0, 0, 10, '你觉得奥格瑞玛有时候是不是太挤了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '哪个傻子决定在%zone放这么多陆行鸟蛋，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '怀念以前在雷霆崖直接从崖上跳下去跳舞的日子，好时光。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '卧槽，%zone这些鹰身人现在真把我折腾惨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '终于找对任务要的草药了，%zone真是处处有惊喜。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '一会回来，还得再刷点声望。%zone可是挺烧钱的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '怀念以前在雷霆崖还能看清朋友的样子，现在就一片糊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '好极了，%zone又来一个风怒图腾，正合我意');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '刚在%zone拿到坐骑，感觉自己真像个兽人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有没有人替%zone的掉落想一想啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '谢谢奶，不过说真的，雷霆崖这卡得我要死了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '我不能再老被%zone这些鹰身人打死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '大家好，欢迎来雷霆崖！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有人要帮忙做雷霆崖的任务吗？喊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有猎人吗？我还缺点动物部件，%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '怀念%zone以前的日子，那时候任务简单多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '雷霆崖今天卡得厉害，还有人出问题吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '我喜欢雷霆崖的景，就是路太远了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '求个队做雷霆崖任务，没问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '惨，我都没意识到有些任务得去%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '我要去%zone待一会儿，把日常做了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '在%zone看风怒图腾跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '大家好，在%zone看到几张熟脸真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有人在雷霆崖做日常吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '嘿，你们还记得当年%zone特别火的查克·诺里斯梗吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '%zone的任务要我杀多少元素之灵啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有人知道石魂在哪儿吗？好像%zone的任务要杀它们。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '在%zone摸到两块元素石，还有人要刷这个吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '我讨厌%zone刷新这么久。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有人能说说%zone任务线的顺序吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '嘿，我挺喜欢你们在%zone都这么友善');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有人能给点%zone石魂的打法建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '%zone的宝藏到手了，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '真不敢相信%zone要杀这么多石魂。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '我爱%zone，但这卡得让我发疯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '大家好，在雷霆崖见到各位真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '看见没？我在%zone桥上卡住了，跟个傻子一样，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '哎哟今天%zone卡疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '还记得以前每件掉落都得抢吗？来得快去得也快，%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '哈哈我又被雷霆崖的卡给困住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '雷霆崖今天的任务简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 14, 0, 0, 0, 10, '哈哈，我在%zone见的绿装比地精堆的还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '雷霆崖这刷新时间也太久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '咱们能不能跳过雷霆崖的任务直接到最后？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '雷霆崖的猎人个个都得拴根绳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '我的坐骑怎么又卡在雷霆崖桥上了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '在%zone摸尸体');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '还有谁怀念%zone以前的日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '谁能给我开个门到雷霆崖，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '一会回来，得去%zone办点事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '有人有鱼人能在%zone一起跳舞吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '哈哈刚有人从雷霆崖跳下去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone怎么总是这么空');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1638, 0, 0, 0, 10, '又在%zone跟山羊跳舞了，经典。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '终于又到幽暗城了，这些蜘蛛真让我发毛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城感觉就跟墓地一样，亡灵别介意啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '恭喜25级，要刷的话去%zone试试');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '就在幽暗城这边刷点东西。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城对法师有几个不错的任务，往西走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '小心%zone的亡灵，特别猛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone哪儿有好的升级点？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '为什么%zone的刷新时间感觉这么久？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城是不错，可大家干嘛一直刷屏？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '住在%zone挺爽的，就是小心那些狼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷真是练级的好地方，安安静静的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人在%zone见过稀有刷新吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '天哪，%zone的掉率也太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城太挤了，地上掉的装备我都看不见！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '太谢谢%zone这边任务的提示了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '今天%zone卡得不像话，还有别人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '从%zone去铁炉堡最近的路在哪儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人能帮我找%zone地下墓穴的入口吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone的各位好，我刚来这地方，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城挤爆了，谁在找队？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '嗨，我就是来幽暗城做任务的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我在%zone一直掉帧，还有谁这样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人知道去幽暗城马厩怎么走最好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城好热闹，求个法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone的各位好，有人要坦克吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '哇，幽暗城这段路可真不近');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城的任务线我记不清了，接下来去哪儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城真挤，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone的各位好，有人能指我去幽暗城的训练师那儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '还有谁卡在幽暗城任务线上？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '嗨，%zone今天挺热闹。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城到处都是食尸鬼，我喜欢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '刚在%zone任务物品被人抢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '我想死这地方了，%zone跟家一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城总让我想起当年刷钥匙的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '大家今天咋样？%zone也没那么差。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城：亡灵重新活过来的地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '怀念当年在%zone到处乱跑找事做的老日子。真希望能想起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '去幽暗城马厩怎么走？我找不着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '谢谢邀请，跟大家在%zone一起刷挺爽的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '谢谢大家。%zone是有点吓人，不过习惯就好了。我还记得那会儿连地狱犬都还没有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '搞什么鬼，我们在这儿干嘛。我怎么错过了%zone的亡灵入侵。就我一个人来晚了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '我太老了，记得暗影议会都还没影的时候。那会儿%zone阴森得很。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '哈哈%zone怎么一个法师都没有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '这只蜘蛛我都见多少次了，还是让我起鸡皮疙瘩。%zone真是永远不腻。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城以前死气沉沉，现在这些新任务让它活过来了。%zone现在真棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone先干啥最好？是先跑主线任务，还是直接刷怪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone传送那10秒延迟没了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人能帮我处理下%zone的刷新问题吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '嗯，只要贴着城门走，%zone挺好认路的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人找队做%zone任务吗？我缺个坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城走起来真够远的，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '找个有坐骑的帮忙跑%zone刷装备。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '在%zone迷路了就顺着河往城里走，超简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '哈哈谁把我带到莫高雷的，我根本不需要这个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '谁能帮我做下这个%zone的任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人能帮我在%zone找找我的宠物吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人对幽暗城那个任务有建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone就是一拨接一拨的骷髅，我累死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '还有谁觉得幽暗城的任务有点太磨人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城挺好打的，可我就是找不着出口，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城到处都是影子，在%zone谁都不能信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人能帮忙做%zone的亡灵任务吗？我有点卡住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '刚又在%zone刷了一次，真是够了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '小心%zone的憎恶，吃过一次亏，不会再有第二次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我从经典服就玩到现在了，莫高雷没别人说的那么差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '我还是不明白%zone的亡灵怎么刷得这么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '在%zone摸到点不错的装备，看来得在这刷一阵了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '我发誓每次上线%zone都更卡一点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone有猎人能帮忙打这些亡灵老鼠吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '幽暗城，我也不知道为什么老回来这儿，可我就是回来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '小心%zone周围的恶魔兽人，打得挺疼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone真让人怀念，想起那些好日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '出城前别忘了在%zone的商人那儿买点东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '去%zone的路挺直，顺着大路走就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '小心%zone的僵尸，挺狡猾的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '刚打完怒焰裂谷，%zone怎么不是那样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '我太喜欢%zone的氛围了，故事特别丰富');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '有人能帮我找%zone隧道入口吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '%zone太有气氛了，就爱这种阴森感');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '我刚来%zone，任务有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 0, 1497, 0, 0, 0, 10, '小心%zone的食尸鬼，它们会偷偷摸上来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '马上回来，在%zone收材料，别等我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '在%zone，我怀念以前有个扛得住的坦克的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '影牙城堡的掉落比%zone强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone的兽人怎么这么快？它们直冲我过来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷采药特别适合');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone狼挺多，但风景很美');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有人在莫高雷村子周围的任务做完了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我卡在%zone从羊身上弄羊毛那个任务了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '哈哈我在莫高雷被一只兔子干死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '谢谢大家帮忙，我在莫高雷慢慢上手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有人在%zone找草药吗，我这儿多得用不完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我在%zone刷了一整天皮，包都满了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '小心%zone的野猪人，打人很疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我隔了好多年又回来玩，好笑的是%zone看起来一点没变');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我刚在%zone碰到一头野猪，结果被它干死了，这正常吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone有的是狼和野牛，可以杀来剥皮和弄肉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '谢谢大家的建议，我去%zone看看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '嘿，谁知道从%zone去血蹄村怎么走最快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷今天超忙，希望我能快点找到草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '哇，%zone狼真多，跑得好快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有人有多余的绷带吗？我在%zone刚用完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我超喜欢莫高雷这些新手任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone到处都是猎人，好像每个人都要人帮忙杀这些野兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '杀%zone那些鹰身人有啥诀窍吗？太狡猾了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷那些狼有啥办法吗？太烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone这儿的牛好多啊，不知道是不是个农场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '大家好，我刚来，在%zone开始的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '大家好，谁有%zone刷怪的好路线？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '小心%zone的半人马，打人很疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷很美，是个不错的起点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有人知道半人马萨满在哪吗？%zone有很多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有猎人知道%zone哪儿能抓大猫宠物吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '小心%zone的半人马，那些萨满很硬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我在%zone，刚在这儿开始做任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '谢谢大家的提示，我在%zone才2级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '小心%zone的半人马法师，他们的法术要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '一开始就把%zone的野猪全清了，这主意行吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷是新手最好的起点，挺不错的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '谢谢给的东西哈哈，%zone太简单了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '走起%zone，这儿有一群狼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '谢谢%zone的组队各位，简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone的狼现在好打多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone鹰身人真多，我多希望能有把弓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone这刷新时间太长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone多美好的一天，没什么比猎几只狼更爽的了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone的狼一直出问题，谢谢帮我的各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有人要组%zone的队吗，缺个治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我想知道从%zone去逆风小径是不是走这条路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '大家好，我%zone新来的，那些半人马是什么东西？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '哈哈我一直死在%zone这些狼手里，救命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷太美了，我好喜欢这地形');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '有人知道莫高雷剥皮的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷特别适合练级，那儿的任务都好做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我就是来采药的，有人知道%zone哪儿有好的点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '莫高雷到处都是狼，但练级又好玩又轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我就在%zone多刷点经验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我在%zone学怎么上坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '嗨，我%zone新来的，有前辈给点建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '谢谢治疗，我%zone新来的，还在学');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我要在%zone练剥皮，就喜欢那些半人马皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '哇，我在%zone都不知道自己该干啥，任务太多了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我确定%zone的刷新有问题，不过半人马倒是挺多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '没问题，需要什么就喊我，我不忙，%zone没别的地方那么热闹');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '是啊，%zone这些半人马挺难缠，不过掉落还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '回到%zone好怀旧啊，真不敢信我以前做过这些任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone今天卡得要命，不过其他方面还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '我都不确定自己还需要待在%zone，但我喜欢这风景');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '马上回来，我去跑趟死亡矿井，离%zone这么近，这等级来钱也快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 215, 0, 0, 0, 10, '%zone这儿有些怪让我想念哀嚎洞穴，不过掉落还挺不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '马上回来，得去%zone练采矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '又刷怪了，我发誓%zone要害死我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '有人想一起做%zone的任务吗，说句话就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '谁能告诉我从%zone出去最方便的路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone那些骷髅小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '兄弟们，提瑞斯法林地怎么升级快啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone这些怪多久刷新一次啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '在%zone练猎人，打狼需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '刚在%zone到10级，第一次打怒焰裂谷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone的任务快把我肝死了，得歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '刚在%zone把炼金练上去了，有点小成就');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone练级真爽，怪倒得飞快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '找人一起去%zone刷铁矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '我太喜欢%zone的背景故事了，越玩越想接任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone怎么这么卡，烦死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone晚上全是怪，瘆得慌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone的怪刷新怎么这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '嘿，冒险者，欢迎来到%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '这萌新见人就问%zone有什么任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '我还在摸%zone，目前超喜欢这儿的剧情');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone挺安静的，就是小心狼和蜘蛛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '我都不知道自己在哪，在%zone瞎转半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone任务太多了，真想多有点时间玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林晚上阴森得很，小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '有人知道%zone哪儿钓鱼好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '想买个坐骑，%zone的任务太难顶了，谢谢指点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '想念以前的日子，%zone还没改成这样的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone挺简单的，就是副本越来越难打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '刚到%zone，有人带带我吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '我超爱%zone的背景故事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '在%zone刷点金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '谢谢在%zone帮忙，感谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone我是真玩不明白');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone这地方全是吓人的怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人在%zone帮忙做法师任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '杀%zone那些吓人的怪，累死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '得在%zone打点亚麻布，裁缝要用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '提瑞斯法林地的僵尸任务需要帮忙，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '在%zone刷金币，有人要草药吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '为什么我老是要在%zone从亡灵身上打铜币？没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '我好像在%zone迷路了，该往哪走啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone这些亡灵怎么这么爱扯人胳膊腿？反正哪儿都凌晨5点了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '兄弟们，谁知道%zone哪条路能躲开食尸鬼？我好像卡住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone刷亡灵有什么技巧？我缺布做第一个坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '哈哈刚在%zone被天灾把脸啃了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '得去办点事，%zone见，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '有人要帮忙做%zone的亡灵任务吗？这地方我挺熟的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '有人知道%zone有什么近路吗？跑图跑得有点烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '刚在%zone被怪追了，说实话还挺刺激的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '从这儿去提瑞斯法林地怎么走最方便？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '我讨厌晚上跑%zone，有点怕');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '提瑞斯法林地刷布有什么技巧？第一个坐骑要用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone的亡灵是挺烦，不过这地方其实蛮不错的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '谢谢在%zone帮忙，能问你个关于亡灵背景的问题吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '哈哈%zone这任务又让我去追牛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone小心脚下，那些骷髅骑士挺难缠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone的刷新速度也太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone这地方跟恐怖片似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone这地方让我想起自己刚来艾泽拉斯的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '恭喜升级，希望%zone没把你活活吃了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '%zone哪儿刷怪好啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '提瑞斯法林地有些阴险的人形怪，小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 85, 0, 0, 0, 10, '钓鱼技能刚升上去，提瑞斯法林地哪儿钓点好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '兄弟们，谁愿意帮我在%zone刷皮革？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '我就在西部荒野练练采矿，别来烦我哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '不好意思去不了，%zone还有一堆要肝的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '刚打完怒焰裂谷，%zone有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我在%zone把采矿练到20了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野的任务真是温柔地把我熬死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '在西部荒野跟豺狼人干上了，唉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '马上回来，去%zone采点草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野有几个任务需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '哇，西部荒野这些任务简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '大家好，西部荒野的迪菲亚兄弟会任务需要帮忙？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone鹿真多，你们急什么呢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '哈哈，我当初怎么会觉得西部荒野简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '小心迪菲亚兄弟会，%zone到处都是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone附近哪儿有马厩管理员？我想买匹马');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '是我错觉还是%zone这个任务有bug？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone那些狗头人到底什么情况？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '嗨，还有谁在%zone被迪菲亚搞得很烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '刚赚了50铜！在%zone我已经富得超乎想象了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '有人知道西部荒野怎么走快吗？打怪太耗时间了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '在%zone采药，感觉跟一堆人泡在草药汤里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '有人有多余的绷带吗？在%zone对付完一群狼就用光了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '在影牙城堡找到好东西，就跟在西部荒野中了彩票一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '想念%zone以前的日子，还记得曼克里克的老婆吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '哇，%zone真是满满的回忆，太谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone有个任务需要帮忙，求个人护送我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '还在%zone刷裁缝技能');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone有人卖鱼竿吗，想钓点鱼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '这地方真安静，我喜欢%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '有人在%zone看到食尸鬼吗，要杀12只');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '就把%zone那只老鼠杀了，不对，是另一只');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '唉，西部荒野这些狗头人真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone需要多点怪来剥皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '哈哈，%zone的任务太有情怀了，赚点金币杀几头野猪的感觉真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野全是狗头人，兄弟们小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野的怪掉的皮还不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野的剧情真的绝了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '哈哈，我刚从%zone那群狗头人旁边跑过去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野任务在哪儿刷最有效率啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野挺适合练12级猎人的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '为啥这地方老是弄得这么阴沉，%zone这儿太黑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '%zone任务做完能去死亡矿井吗？我还没去过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野的任务太无聊了，我就想赶紧找下一个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '我就喜欢进%zone第一眼看到风车，有种回家的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '西部荒野晚上特别美，任务还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 40, 0, 0, 0, 10, '看到%zone的镇子被毁了、到处都是亡灵，真让人难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone任务求人帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹，永远是最好的采矿点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林是挺美的，可这任务线真是拖死人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人在%zone接到农夫本顿的任务了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹就是我心之所向');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹有几个挺酷的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '想去洛克莫丹钓钓鱼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '想找点刷%zone声望的任务，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '有人能帮我过%zone最后一波吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '好家伙，%zone又来一群巨魔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '有人知道%zone哪儿刷矿好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '刚在%zone杀了第100只狗头人，都杀腻了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '在%zone矮人附近找到个超好的剥皮点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone那个任务有人有铲子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我烦死%zone边上那些巨魔了，缠着不放');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹挺美的，就是那些地精烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '刚在%zone卖草药赚了100金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '兄弟们，从%zone出去最快怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone小心那些石腭怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '谢谢关于%zone食人魔的提示');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '哈哈我是真适应不了%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone那黑铁矮人我实在需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹烂透了，别叫我来这儿肝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '有人有多余的铁盾吗？我的丢在%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹这么绿，矿洞却黑得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '需要个法师来把艾尔文森林河边的狼冻住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone这些铜矿石我该拿去干嘛？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹今天卡成狗，怎么这么慢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹的山真是美到窒息，爱死这地方了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone还差两块铁矿石');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹的兽人有点腻了，不过打起来挺有情怀的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '马上回来，去%zone补点食物buff');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '下一个是哀嚎洞穴，谁想在%zone跟蜘蛛来一场？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '%zone这猎人居然真打算用根棍子去打鱼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '嗨，%zone有什么建议吗？我第一次来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '还有人记得洛克莫丹当年是游戏中心吗？那时候真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我想今天在艾尔文森林试试采矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹的精英鱼人小心点，跑得比磕了药的猎人宝宝还快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '有人在做洛克莫丹的采矿任务吗？我缺几块铁锭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹挺美，就是那些蜘蛛网太噩梦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '我10级，洛克莫丹挺费劲但也挺好玩，谢谢大家一直帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '谁要帮忙打%zone的石匠？那帮人挺难缠，求个人一起去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '有人有洛克莫丹地图吗？我好像迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '刚接到洛克莫丹第一个任务，来去收拾那些石腭怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '在洛克莫丹每做完一个任务我都想胜利地/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '洛克莫丹刷新挺快的，想想也合理');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '阴影、怪物、寒冷，洛克莫丹跟北极似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '哈哈怎么%zone的人都在躲蝎子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '嘿，%zone任务要几块铜锭，有人有吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '哇，刚在%zone被豺狼人弄没了buff，太经典了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '去%zone那个小屋的路也太长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '在%zone摸豺狼人的尸体，别管我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 38, 0, 0, 0, 10, '找人帮我一起在%zone捡东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '有人能告诉我去%zone的船怎么走吗？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸离死亡矿井可太远了，非常感谢帮忙！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '哈哈，%zone第一个任务就挺难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我刚来%zone，有人能帮我做杀狗头人的任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '%zone刷这些兽人上手了就轻松了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '在%zone看到猎人，就问问他们有没有肉可以做饭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸有什么好钓点吗？这任务做得我无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '谢谢大家帮我做黑海岸的第一个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我就在黑海岸到处晃悠，看能碰到什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我黑海岸卡任务了，求个老玩家帮帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '大家好，我刚来%zone，找不到任务怪，有人能帮下忙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '恭喜黑海岸到10级，我自己也想刷经验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '刚在黑海岸刷了50块铜锭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '采矿要的材料在黑海岸都能找到');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '要我说黑海岸太无聊了，但还是得熬过去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我在黑海岸怎么一条鱼都钓不上来，明明应该很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone的狼真烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '挺喜欢%zone的氛围，就是蜘蛛有点烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '刚在黑海岸开始旅程，迫不及待想探索了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '非常感谢复活，黑海岸跑尸太痛苦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸好多任务都是打打打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '为了杀黑海岸一只野兽我大概已经死了30次了，看来我就是菜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸跑图快把我跑死了，不过风景是真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '在黑海岸练制皮简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我总觉得黑海岸的豺狼人不太欢迎我们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸的熊怪任务需要帮忙，我感觉卡住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '%zone对新手太狠了，有什么建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我卡在%zone了，刷新比我奶奶还慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '有人能说说黑海岸哪些任务升级最快吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸一团糟，我得歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸的怪今晚打人特别疼，注意血量');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '%zone任务太多了，跑得我腿都酸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '有人知道黑海岸有什么值得一提的洞穴吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '马上回来，得去黑海岸刷点矿，劳碌命啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '%zone钓鱼太烂了，我还是换个地方刷吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸这些月爪豹怎么这么凶？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '哈哈我刚在黑海岸迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸做任务最好的路线是怎样的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人在%zone采药吗，缺人喊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '有人有多余的鱼竿吗，黑海岸用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸的鱼人任务需要帮忙，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '打完死亡矿井再回黑海岸简直轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '这地方值得来吗？%zone是挺黑但挺酷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '大家好，第一次来%zone，这儿的怪太狠了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '唉，黑海岸刷新太慢了，就我这运气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '大家能不能停一下，好好欣赏下%zone的美？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸很美，那些怪也只是想找点乐子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '真希望黑海岸能再找个猎人一起，这种事总是缺个伴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸就是那种会让你想/dance的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林的狼最恶心了，我的血瓶都不够用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '真不敢相信我又卡在%zone了，不过至少怪还挺可爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '嗨，我刚来%zone，怎么去找任务NPC？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '有人知道制皮训练师在哪吗？%zone太大了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '%zone的农夫需要点陪伴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '哀嚎洞穴你最好多找点人，%zone正好可以先练练手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸的各位，有人知道微光之尘在哪儿弄吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '%zone浑浊的水让这次刷皮特别有意思哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '想找人在%zone一起采药，有人有兴趣吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '从黑海岸怎么去石田农场？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '谢谢在%zone帮过我的各位，你们太棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林这些豺狼人真把我刷烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人知道为什么我们不杀%zone的狗头人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '哪儿还能弄到木头？我在黑海岸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '有人知道%zone哪儿采矿好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我在黑海岸卡在那个破任务上了，长尾鲨在哪啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '黑海岸怎么这么多树，什么都看不见');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 148, 0, 0, 0, 10, '我在黑海岸钓了好几个小时了，鱼群到底在哪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '你知道%zone有一堆野猪人吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '嘿，贫瘠之地野猪人真多哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '谢谢帮忙做%zone的法师任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '为什么科多兽骑手老往贫瘠之地跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '还记得当年在贫瘠之地能弄到科多兽坐骑吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我%zone新来的，去闪金镇最快的路怎么走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地野猪人真多啊哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone刷新太坑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地刷新也太快了吧哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地永远都是满屏的怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone掉东西也太少了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone卡得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '嘿，我刚来%zone，这地方怎么走动啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '在%zone浪费时间，不过剧情目前挺香的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地是我今天的常驻地图');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '在贫瘠之地肝了不知道多久了，还是挺怀念以前的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '我还是不知道%zone的狗头人掉什么，估计刷新太慢了吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone的怪确实适合刷皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '在%zone有段时间我是真的过得挺开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '真希望贫瘠之地能有条像样的路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '刚拿到坐骑，现在逛%zone舒服多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地能干的太多了，根本没时间无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone这任务挺烦，不过我已经上手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '有人知道%zone的半人马营地在哪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '哈哈，又是%zone的一天，努力别被偷袭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '猎人真得做%zone那些10-15级的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone的狗头人怎么这么硬，我完全搞不懂！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone的狗头人跑得肯定是最快的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '谢谢帮忙做%zone那些任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地热得要命，连太阳都在流汗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '刚升到5级，现在在%zone找科多兽打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone热得离谱，不过至少野生动物挺有意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone的风险投资公司天天都在招人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '刚在%zone放倒了十几头科多兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '我发誓%zone的太阳更毒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '刚看到%zone风险投资公司的采矿场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '喜欢%zone的氛围，让人真有种冒险者的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '哈哈，我喜欢%zone的地精，太疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '艾尔文森林的狗头人任务最烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地太棒了，满地黄沙真有沙漠的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '刚靠%zone遍地的石头把采矿练上去了，谢谢大家没顺手杀我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地对我来说有点慢，不过至少风车挺有意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '有人想一起跑一趟贫瘠之地吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '我就喜欢%zone这么有生气，从兽人到风车都挺带感');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone跑尸跑得烦死了，跟陷在泥里一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '是我的错觉还是贫瘠之地的野猪刺越来越大了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone这刷新时间快把我熬死了，你那边怎么样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone野猪人最烦的就是那些小的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地那些野猪人到底值不值得打？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '不知道%zone有没有什么好掉的，反正我要去刷一堆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '这延迟搞得我在%zone感觉像在原地打转');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '有人知道%zone做任务的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地这个任务到底怎么开始啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '我不知道还能在%zone杀多少次野猪人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地的野猪人掉东西好吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '不需要%zone野猪刺的猎人不是真猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '太谢谢你在%zone带头拉怪了，没你我们真过不去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '弄科多兽坐骑最好的路线在哪？我在%zone太慢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '离鹰身女妖远点，%zone这儿她们特容易仇恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '天啊贫瘠之地这垃圾怪也太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '大家好，在%zone玩得挺开心，很安静，狼很多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '好无聊，就在%zone采采药，老样子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '嘿，有人能帮我在贫瘠之地升到10级吗，我在这儿待了快一辈子了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '这地方太离谱了，我在%zone迷路三次了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '从%zone出去最快怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '猎人怎么总要在%zone把啥都杀光？就不能给我们留点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '有人有多余的狼皮吗？%zone任务要用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '%zone这肝度是真的，能顶住的都牛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地升级超棒，随时求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '哈哈%zone有个新手刚掉下悬崖，谢谢提供乐子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '哇我刚在%zone发现一个隐藏洞穴，风景绝了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '%zone这个任务发布者老给我们派些杂活');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '贫瘠之地晚上又吓人又美');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 17, 0, 0, 0, 10, '想多找点任务肝，有人知道%zone有什么好任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '大家好！欢迎来%zone，我就是来刷刷经验，顺便帮帮有需要的人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '哇银松森林那些蜘蛛真大，不过掉的东西值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林今天看着挺阴沉，好在掉的东西不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我真不敢相信%zone这些蜘蛛的刷新时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '想采点药吗？我们可以组队一起去%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林晚上阴森森的，不过任务不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone给的经验也太多了，简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '嗨！有人能教教怎么打蜘蛛吗？%zone越来越难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '还有谁在%zone被这些蜘蛛虐？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林到处都是狼，烹饪用的肉怎么弄啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '马上回来，得把洞里杀狗头人的任务做完，%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林好多蜘蛛网，这任务需要帮忙，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone特别冷，我带了火焰法术');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林全是这些烦人的蜘蛛，任务需要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '为什么%zone总是蜘蛛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '又是银松森林？多谢刷新时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '哈哈，又在%zone迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林下雨的时候超美，怪就没那么美了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林，至少树挺好看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '说起来，我到现在还没找到%zone的稀有怪，都第五天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '好极了，%zone又要去抓鬼了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '刚在银松森林被抢了，12金没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone有人会跳/dance吗？我快疯掉了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我还差两级就能去%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林人越来越多了，往东走能避开大部分仇恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone前期草药最好，能采就多采点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林的蜘蛛有点难缠，不过任务挺简单的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone到处都是狼和蝎子，记得带一两瓶治疗药水');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林的矿是想要，但一堆座狼在旁边，挖起来太麻烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我在银松森林打了一堆碎皮，有人要吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '还有谁喜欢在%zone刷布的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '哟，居然有人在做%zone的精英任务！佩服');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我发现银松森林里有几处隐藏宝藏，有些战利品还挺不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '大家好，欢迎来银松森林，这儿挺阴森的，不过任务还算简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '有人要陪我一起去%zone吗，狼人挺凶的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '嗨，有人在%zone做任务需要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '大家好，我刚到%zone，有啥好路线推荐吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '哈哈刚发现我在%zone转悠好半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '谁在%zone需要帮忙就跟我说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '刚在%zone迷路了，怎么出去啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我在%zone，谁能带我去找下任务NPC，谢啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我复活回来了，还是困在银松森林，这有啥新鲜的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '小心%zone的狗头人，打人挺疼的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone的蜘蛛大得吓人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone之后咱去哪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林跟咱上回来的时候一模一样，没啥新东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '行吧，那咱一会儿去刷%zone的副本？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone之后能不能去哀嚎洞穴？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '大家好，有人知道%zone这一带哪儿有银矿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '第一次来银松森林，这地方氛围怪渗人的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '谁能帮个新手做下%zone的狼人任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林的各位，谢谢给的金币小费，玩得挺爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '在%zone采了半天草药，不过话说回来，这儿的NPC还挺友好的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '刚在%zone接到个钓鱼任务，希望能钓到好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '死亡矿井太轻松了，%zone还有谁缺人啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '银松森林这天气真够呛，哪儿有暖和点的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone还有谁跟我一样怀念当年的好日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '我去，银松森林的狼人是真闹心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '%zone还有谁在练挖矿？这附近有几个点不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 130, 0, 0, 0, 10, '在银松森林刷豺狼人掉皮革？值得费这劲吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '各位冒险者好，希望你们在赤脊山玩得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '我来赤脊山就是冲稀有怪来的，祝我好运吧！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '嘿，有人要去黑暗深渊吗？%zone刷任务挺合适的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '在赤脊山刷怪呢。这地方升级不错，就是任务没完没了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '是我错觉还是%zone的任务越来越难了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '谁有多的魔血？赤脊山可真是块宝地哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '有人知道穿%zone最快的路线吗？我想找点好任务做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '大家好，有人要打血色修道院需要帮忙吗？%zone的任务挺有意思的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '这有猎人缺弹药吗？我刚在%zone从鱼人身上弄了点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '赤脊山刷怪太爽了。鱼人和任务都刷不完。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '有人要去%zone吗？搭个伴呗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '说实话我就想在%zone见啥杀啥。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '刚拿到坐骑，在%zone总算自由了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '今天看大家都在%zone探索，挺好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '你要是讨厌地精，%zone可就够你受的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '就在%zone刷刷怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '要不要去%zone刷会儿鱼人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '别忘了把赤脊山的洞都清了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '有人知道%zone的石匠在哪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '我在赤脊山跟鱼人打交道从没吃过亏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone那些任务要帮忙就喊一声！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '赤脊山今天卡得要命，多谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '我喜欢%zone的氛围，可这些豺狼人一直刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '谁能提醒我一下咱为啥又来%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '刚拿到坐骑，咱去逛%zone吧，多谢啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '我发誓%zone的掉落比我妈做的饭还难以下咽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '大家要是路过艾尔文森林看到新人，能帮就帮一把');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '真不敢相信去黑暗深渊还得一路杀过%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '我怎么老在%zone迷路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone那些豺狼人，是不是就是长得凶的狗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone的任务怎么老是跑路比打架还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone能拿的宝贝太多了，时间太少');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '真服了，在%zone得杀这么多同一种怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone的刷新时间是多久啊，我在这儿待半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone的食人魔真的开始惹毛我了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '在%zone放松一下，看看风景');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '刚拿到坐骑，在赤脊山感觉自己像个国王');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '大家好，有人需要帮忙做丹莫罗的雪人任务吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '我去，%zone今天的刷新时间也太长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone的食人魔到处都是，出门小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '趁我还没忘了目标，赶紧把赤脊山的任务做完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '谁想聊天就来找我，我在赤脊山歇着呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '赤脊山挤满了来找人杀的部落玩家。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '怎么大家都往%zone跑着刷怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '赤脊山的任务永远做不完。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '在%zone打架比弄到好装备容易多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '唉，怀念当年在%zone捡东西没这么麻烦的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '还有谁也卡在赤脊山那个任务上。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '哈哈，我还在%zone跟这些霜虫较劲，它们怎么这么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone现在狼可真多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone那些狼还有谁打不过？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '还有谁觉得赤脊山的任务有点磨人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '哈哈，在%zone找那个洞结果迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '有人知道%zone附近哪儿能刷厚皮吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone的任务真是越来越拖沓了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '在%zone把制皮练完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '%zone的狼老把我坐骑咬死。谢谢啊，各位。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '最近有人在%zone刷过东西吗？我这儿一堆事要做。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 44, 0, 0, 0, 10, '在%zone采药，缺材料的可以找我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '马上回来，得跑趟丹莫罗弄点碎皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '%zone哪儿能刷皮革？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '真希望蜘蛛别老乱跑，我怀念以前的%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '谁要刷%zone声望，我乐意陪你刷怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林有时候有点太安静了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '我都想不起来上回在%zone看到麻风侏儒是什么时候了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '记得在%zone把垃圾都捡了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '有人要%zone的草药吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '谢谢帮忙，不过不用，我不需要把%zone搞成简单模式');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '大家好，有人在%zone见到那个鬼了吗？我发誓它就是在耍我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '大家好，很高兴在暮色森林看到这么多友善的面孔。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗的巨魔搞定啦，任务终于做完了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '有人要法师一起去刷监狱吗？我在暮色森林待得无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '在暮色森林找草药，有人知道好点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '嘿，有多余的皮革吗？我得在暮色森林练剥皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林太阴郁了，跟噩梦似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '怀念以前暮色森林掉落好弄的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '谢谢帮忙，%zone习惯那些僵尸之后也没那么糟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林的狼需要帮忙，老把我撕了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '%zone的蜘蛛怎么老照我脸上扑？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '谁能帮我杀暮色森林的食人魔？我打不过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '刚在%zone开始升级，任务在哪刷啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '怎么大家都急着冲过艾尔文森林？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '还有人在%zone被霜狼群虐吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '有人知道穿暮色森林去下个任务点的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '我去，%zone刷怪也太疯了，感觉要烧起来了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '我实在打不过暮色森林的尸鬼，帮帮忙？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林挺吓人的，不过任务倒是好懂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林简直就是我梦想的坟墓，每次尸鬼一刷就又完蛋');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '%zone全是狼和豺狼人，不过这任务难得有点意思，多谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林刷怪简直是噩梦，还有谁一直被杀？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林任务挺简单的，有人想组队一起做吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '%zone那些尸鬼小心点，挺难缠的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林跟家一样，真不敢相信我以前还漏了这地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗今晚好安静，感觉就我一个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林怎么老下雨，这天气受不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '到处都是蜘蛛，多谢啊，暮色森林真是好地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林一到晚上更糟，全是尸鬼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '各位，有人知道在暮色森林做任务的最佳路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '大家好，我刚到暮色森林，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '刚拿到坐骑，终于不用在%zone走到腿断了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '哈哈，差点被暮色森林的狼咬死，老一套了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '谢谢帮忙做暮色森林那个任务！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '不客气，能帮上%zone那个任务的忙就好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林小心点，食尸鬼挺阴的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '谢谢帮我做任务，丹莫罗现在轻松多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '各位，有人在%zone见到暗影潜伏者吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '记得去暮色森林那个废弃矿洞捞点外快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林刷怪太爽了，五只狼升一级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '刚把暮色森林铁匠的任务做完，他要40块铁锭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '哇，暮色森林真是满满的回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '谁能给我发张%zone的地图？我迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林晚上挺瘆人，但任务值得做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '%zone的幽灵小心点，打得挺疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '暮色森林任务还差10张狼皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 10, 0, 0, 0, 10, '有人知道%zone的制皮图纸在哪吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '没事，能帮上%zone那个霜狼任务就好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '有人要法师帮忙拉%zone的怪吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我去，%zone的鱼人刷新也太慢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '湿地的氛围我很喜欢，就是这些鱼人太狠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '马上回来，去倒杯水，%zone的喷泉挺好用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '哈哈去%zone副本的路上被鳄鱼咬了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone的掉落太烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '在%zone找侏儒跟寻宝似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '哇好久没来%zone了，这儿的怪多少级来着？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone的鱼人小心点，拉多了它们刷得跟疯了一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我喜欢%zone的背景音乐，让人想起从前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '刚打完怒焰裂谷，丹莫罗现在跟散步一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '大家怎么都在抱怨%zone的任务？比这更烂的地图也有啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '真不敢相信我忘了%zone的潜行任务，那是最精彩的部分');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '等不及拿坐骑了，这样就不用老在%zone跑来跑去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '怎么大家都在%zone往北跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '谢谢帮忙做湿地的元素任务，我实在不擅长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '哈哈，让我想起第一次玩湿地的时候，鱼人真多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '真不敢相信我在湿地钓鱼把鱼竿弄丢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我喜欢%zone的水蜘蛛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '湿地的草药值得刷吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我在湿地打到一张超棒的皮革图纸！找人做点东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗的雪人挺吓人，但奖励值得');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone那个雏龙任务我需要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我来%zone就是冲鱼人来的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '湿地总是又潮又泥，我就喜欢这儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我就是喜欢湿地的氛围，浑浊的水还有鱼人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone那个任务我乐意帮忙，招呼我一声就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '谁帮忙打下%zone的鱼人，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '在%zone采药，还有谁觉得自己在这地图就是个纯新手？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '还有谁喜欢%zone的剧情？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone哪儿还能找到更多矿石？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我去，%zone水真多，感觉像开了个养鱼场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗总是挤满了做任务的人，我就喜欢这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '刚在%zone的泥里迷路了一个小时左右，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone野猪人太多了，我都没脾气了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '有%zone的沼泽谁还要坐骑啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone的剧情能刷一整天！谁有多余的治疗药水？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone的地精把我整成这样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '谁能带带我过%zone，拜托');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone让我想跟泥巴怪/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '大家好，湿地有啥好玩的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '哇，%zone这儿真绿，让人想起从前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '湿地的任务挺简单的，只要躲得开那些破事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '大家好，%zone新来的，目前很喜欢这气氛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '湿地一点没变，又是地精和鱼人的一天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '刚拿到坐骑，在%zone日子轻松多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone食人魔真多，不过声望给得不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '嘿，%zone刷金币最好的办法是啥哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '湿地全是泥，我也全身是泥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '从%zone怎么去监狱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '我在湿地想采点草药，可惜一无所获');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone刷金币有啥窍门吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '真服了，在%zone得杀个我几乎看不见的怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 11, 0, 0, 0, 10, '%zone有几处风景真漂亮。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '有人需要帮忙练采矿或者剥皮吗，在%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '治疗到底在哪，%zone跟战场一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '刚被一个萨特追着跑遍灰谷，谢了啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '谢谢治疗，%zone现在简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '这刷新时间快把我逼疯了，灰谷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '得有人去拉那些萨特，灰谷一个人根本不行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '有人打过剃刀高地吗，我那儿还有几个任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '卡得离谱，%zone根本刷不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '刚在血色修道院出了我第一件史诗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '大家好，%zone做任务愉快。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我去，%zone那些萨特越来越烦人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗让我想起当初为什么会爱上这游戏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '谢谢帮忙打%zone的鱼人，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '大家晚安，明天%zone见');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '还记得咱在%zone全迷路了，最后跳了好几个小时舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '%zone那个讨厌的萨特要帮忙吗？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '还有人记得当年在%zone，咱觉得自己多厉害吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '马上回来，得去%zone刷点鱼人做剥皮任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '还有谁怀念在%zone靠两条腿跑的日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '还有谁觉得%zone萨特太多了？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '刚拿到坐骑，终于！不用再跑穿%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '唉，又一天，又得在%zone杀萨特');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '哈哈我在%zone一直死在野猪嘴里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '有人在%zone快速升级有啥诀窍吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '有人想组队做%zone的任务吗？多几个人轻松点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '有人知道去诺莫瑞根做任务穿%zone最快的路吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '感觉在%zone又把同样的任务做了一遍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '灰谷的大蜘蛛小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '老样子，%zone又下萨特雨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我都能听见猎人在抱怨%zone没目标打了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '怎么感觉%zone一半的刷新都是坏的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '哈哈%zone这卡得我啥都点不着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我发誓%zone的掉落比上回还差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '嗨，有人知道在%zone从30级快速升级的法子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '别忘了去%zone的钓鱼点看看，能钓到好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '灰谷跟丛林似的，全是熊怪和萨特');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '这%zone跑起来简直是噩梦，不过掉落还不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '嗨，大家在%zone今天过得咋样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '嗨，我在%zone刷会儿东西，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '%zone之后我要去诺莫瑞根，想来的跟上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '还有谁被%zone的刷新搞烦了？越来越闹心了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '刚在%zone拿到坐骑，我发誓这地方整个都快起来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我挺怀念%zone以前的迅猛龙，现在强太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '谁有%zone杀萨特的任务还没交的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '刚在%zone拿到坐骑，等不及到处骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '这游戏我也有过更好的时候，但还是喜欢丹莫罗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我觉得灰谷是游戏里最美的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '25级，找人一起打灰谷，缺个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '有人做灰谷任务吗，能带带新手入门不');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '真希望灰谷能多点有意思的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '谢谢组队，我得跑回灰谷了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '又是灰谷？咱不是刚离开这儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '哈哈%zone怎么啥都这么绿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '咱又得把整个灰谷跑一遍？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '就差一个法师buff了，好做%zone这些鬼任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '灰谷的萨特刷得怎么这么勤');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '真不敢信我们还在玩，丹莫罗还是最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '嘿，%zone哪儿能刷木头？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我喜欢%zone有鹿，让这地方显得特别自然。鹿别介意啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '灰谷风景真美');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '刚把灰谷做完，萨特还是那么烦哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '去%zone采草药，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 331, 0, 0, 0, 10, '我喜欢%zone这些树');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '谁能帮我找下%zone的采石场');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone的枭兽把我揍惨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '穿%zone的路怎么这么长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '黑暗深渊的掉落比%zone强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗的狼真让人头疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '谁来奶一口，我不想死在%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '哈哈我在%zone迷路了，谁能指下任务NPC在哪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone那些破半人马老把我控住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我怀念%zone还没满是精英怪的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone狼太多了，找人组队去猎');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '石爪山脉那些半人马巡逻队搞得我头疼，有人见过带蓝羽毛的吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '喜欢%zone的氛围，让我想起我第一个角色');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '谢谢坐骑的提示，我三十几级在石爪山脉拿到的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '半人马真烦，石爪山脉那个精英小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '有治疗在吗？找人组队去%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '有人多一张狼皮吗？我还有好长的路要走，丹莫罗太大了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '半人马挺烦，不过石爪山脉的故事真不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '大家好，有人在石爪山脉见过那个稀有怪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '大家好，%zone有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '得找到%zone鱼人的刷新点，哪儿都找不到。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '谢谢帮忙。我刚来%zone，有时候还挺吓人的，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我烦死%zone那些地精陷阱了，马上回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我在%zone啥也找不到，估计是漏了点什么。太谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone任务需要帮忙，谁想组队一起升级？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone那些蠢鱼人，怎么都杀不完。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '大家好，刚在%zone到25级。这儿的狼我喜欢，就是刷得慢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '从丹莫罗歇会儿，有人需要帮忙打死亡矿井吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '嘿嘿大家好。刚开了个新号，找朋友一起在%zone做任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '有人知道%zone的稀有怪在哪吗？我缺那个坐骑。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '你好%zone，我刚来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone的狼老把我咬死，有啥招吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '有人知道%zone刷怪的最佳路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone好啊，有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '有人知道%zone稀有狼的刷新点吗？谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '各位，谁能告诉我升级穿%zone的最佳路线？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '石爪山脉今天把我整惨了哈哈，被野猪人放倒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '各位，有人知道%zone刷皮革的好点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '在丹莫罗刷怪别忘了顺手采药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '石爪山脉好像到处都是鞭笞者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我得在石爪山脉刷点东西囤补给，然后再去剃刀高地');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '嘿，我在%zone跑任务，还有谁在这儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone那臭狼。有人要帮忙打吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '能给我开个去铁炉堡的传送门吗？我困在%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '在找去诺莫瑞根的路，%zone挺难走的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone的狼人你根本躲不开');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone绿得不行，我感觉自己像沙拉里的巨魔。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我发誓%zone的怪在合谋对付我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '在%zone囤草药，有人也要吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '恭喜拿到那块冰石，%zone风景美但冷得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我就喜欢在%zone一边刷金币一边采药的感觉。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone怎么全是狼？全杀了就是了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '还有谁怀念魔兽当年的日子？%zone太让我想起那时候了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '大家好，谁想去%zone做任务？这儿的任务挺轻松的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '抱歉来晚了，在%zone南边豺狼人营地附近的树脂池里卡住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我喜欢%zone的氛围，能在这儿逛好几个小时');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '嘿，还有谁觉得%zone豺狼人的刷新时间有点问题？好像有点长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '%zone的各位好！希望你们都玩得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '老兄，%zone今天卡得要死，希望早点好起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '等不及拿到坐骑好好逛逛%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone的鱼人真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '有人要帮忙做%zone的任务吗？我很乐意搭把手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '保持乐观，不过说真的，%zone的掉落也太随机了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 406, 0, 0, 0, 10, '我来%zone就是看看风景，顺便看看豺狼人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '大家好，我刚到希尔斯布莱德丘陵，啥情况');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '真要命，希尔斯布莱德丘陵那刷新等了半天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵真漂亮，我喜欢这儿的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '行啊，%zone那个任务我能帮你');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '老兄，我烦死希尔斯布莱德丘陵的刷新了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '准备去%zone，缺个治疗，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵：有人知道去辛迪加营地的近路吗？我记不清了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 12, 0, 0, 0, 10, '有人知道%zone的迪菲亚在哪吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone刷暴风城声望特别合适');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人给点希尔斯布莱德丘陵任务的小建议吗？好久没做了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '靠，希尔斯布莱德丘陵的怪刷新太慢了，等半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '还记得希尔斯布莱德丘陵是练级圣地的时候吗？那时候真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵的怪怎么有时候打人这么疼？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人想一起做希尔斯布莱德丘陵的任务吗？我可以帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '得刷希尔斯布莱德丘陵的怪涨声望，太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '刚拿到第一个坐骑，希尔斯布莱德丘陵从来没这么快过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵有点腻了，不过任务奖励不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '刚在希尔斯布莱德丘陵升到30级，爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '大家好，我刚到%zone，该先做哪些任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '记得吗，去丹莫罗矿洞有条秘密通道');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哈哈，希尔斯布莱德丘陵的豺狼人还是跟记忆里一样烦人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, 'gg希尔斯布莱德丘陵。谢谢队友，这刷怪真爽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵刷怪愉快，队伍保持紧凑点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '怎么希尔斯布莱德丘陵人人都要猎人？笑死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人知道希尔斯布莱德丘陵的任务在哪儿交吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵太苦了，不过掉落值得。有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '我在希尔斯布莱德丘陵，缺坦克的喊我。马上回来，去补点货');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '在希尔斯布莱德丘陵抢我掉落的那家伙真混蛋。气死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哈哈刚在希尔斯布莱德丘陵被巨魔偷袭了，经典！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵搞起来，谢谢大家帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '这些家伙我以前见过，%zone真是满满的回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵刷着是累，不过风景真不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哈哈刚在%zone有人朝我扔了块石头。为啥啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵的辛迪加营地怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵这延迟我真服了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '谢谢大家帮忙做希尔斯布莱德丘陵那个任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '在希尔斯布莱德丘陵能一直跑，谁还要坐骑啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵的怪怎么刷这么慢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '剃刀高地老虐我，不过早晚能拿下。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '我发誓，希尔斯布莱德丘陵的掉落随机是被诅咒了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '谁要在%zone组队？这些任务我还没做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我在%zone练剥皮，还有谁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵全是辛迪加，简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哇我在%zone跑了一整天，脚都疼了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '是只有我觉得还是%zone今天雾特别大？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人在%zone能帮帮我吗？我迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵热死了，我快化了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人知道%zone的野猪人还是见人就打吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '刚拿到坐骑，多谢，希尔斯布莱德丘陵看着不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哈哈还在刷那件精英披风，希尔斯布莱德丘陵真漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '小心希尔斯布莱德丘陵的辛迪加强盗，他们很阴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵刷怪不错，我也看到你们了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone有几个任务挺坑的，但总体不算差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哇希尔斯布莱德丘陵有很棒的背景故事，想听的来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人给点希尔斯布莱德丘陵任务的建议吗，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '有人知道%zone做任务的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '我太喜欢%zone的故事了，是我的最爱之一');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '%zone今天刷新太慢了，刷得心累');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '终于到%zone了，一直想来逛逛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '还有谁怀念%zone任务那么带劲的旧时光');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '刚拿到坐骑，在%zone总算自由了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '大家好，我刚来%zone，这儿哪些任务最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '小心，希尔斯布莱德丘陵的怪很凶。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '丹莫罗是个练级的好地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '哈哈，我希尔斯布莱德丘陵又迷路了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '希尔斯布莱德丘陵练级很棒，任务多。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '谢谢建议，我去希尔斯布莱德丘陵看看。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 267, 0, 0, 0, 10, '当心希尔斯布莱德丘陵的高级精英。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我发誓，千针石林的乌鸦比玩家还多，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的科多兽挺难缠，走大路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '还有谁烦千针石林这些半人马');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '真没想到我又回%zone了，我讨厌这地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '马上回来，去千针石林刷点东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '笑死，我猎人打%zone那只蝎子试了4次才打中');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone是有点绕，跟着大路走就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '攒钱买坐骑，在%zone刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '这就是为啥我得有坐骑才能穿过千针石林');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的各位好，刷怪顺利！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林要帮忙吗？我这儿有几个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '有人在千针石林有铁矿石吗？想换');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '哇，%zone这些蜥蜴真够烦的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '马上回来，去%zone的半人马营地看看，说不定有任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '还有谁在千针石林刷爬行动物皮？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的任务要帮忙吗？我可以搭把手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '哈哈，刚刚在%zone迷路了15分钟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '%zone这儿风景不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone有猎人想组队吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '谢谢在%zone帮忙，挺险的但我们过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone缺个治疗，去诺莫瑞根副本。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '谁知道%zone哪儿刷怪最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone的任务有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我讨厌%zone那个跟半人马有关的任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '呃，千针石林这些多头蛇太难风筝了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '想在%zone采点草药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '还有谁觉得%zone的任务很无聊？但我得拿经验。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我觉得%zone这些半人马比平时难打。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '我迫不及待想离开%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我在%zone采药和剥皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我讨厌%zone这一带，精英多头蛇太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '在%zone刷到能买坐骑为止');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我在%zone需要剥皮和采矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '哇千针石林太热了，等不及离开。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '谢谢给我补满血的治疗，%zone真能磨。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '有人想听千针石林刷皮的小窍门吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '我喜欢千针石林的感觉，让我想起以前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '等我一下，在千针石林打几个野猪人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '哇%zone这些任务真是又臭又长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 1, 1, 0, 0, 0, 10, '有人需要法师去%zone拉小怪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林任务超简单，现在干啥呢哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone又看到野猪人了，那玩意儿真是野兽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '喜欢千针石林的历史，做任务都有意思。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '终于有坐骑了，穿千针石林轻松多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林任务发布者真多，我都不气了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '%zone任务卡住了，缺人帮我打这个食人魔。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林好有怀旧感。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '今晚有人在%zone做任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '千针石林跟我记忆里的总是不一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_zone', 4, 0, 0, 2, 400, 0, 0, 0, 10, '还是烦千针石林那些食人魔老把我击倒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '暴风城这地方，绕来绕去真是烦死人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '来个剧情党，谁能给我讲讲当年那些人类王国的事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '马上回来，得去弄点谷物，农民可没觉睡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '奥达曼你们要坦克吗？我是T，没问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '恭喜拿到坐骑，你应得的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '监狱对35级来说是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '血精灵和我们的神级头发，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根太带劲了，侏儒都疯了，可他们需要我们帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '剃刀高地刷本，谢谢邀请！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊升级很合适，好打的怪多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽对我来说还是难受，打多少次都一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '嘿大伙儿怎么样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '我爱这游戏的剧情，太深了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '刚拿到坐骑，爽翻');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '我爱当人类，我爱联盟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '马上要在血色修道院冲到30级了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '血精灵就是最棒的，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '得刷金买那匹史诗坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '太谢谢这口奶了，正需要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '哈哈，血精灵和我们的神级头发');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '谁想组队打监狱？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '我真想把采矿练上去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '我去，诺莫瑞根真是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '大家好，我刚玩到这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '得多弄点金买最好的皮肤');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '真不敢信他们放兽人进黑石深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '哈哈我怎么这么爱血精灵的音乐，我们品味都挺糟的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '有人能来前面吗，我得回沉没的神庙，还有东西要摸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '血精灵的魔法你就这水平？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '奥达曼我需要个法师，有种不祥的预感');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克总是好玩，找奶和坦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '还需要啥尽管说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '血精灵就爱那个高音，谁来开嗓？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '我就想歇会儿，清黑石塔清烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '马上回，去看看邮箱里的史诗装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '厄运之槌有人要盗贼吗，我准备好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '人类万岁，我们的城市最棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克哪个职业好升级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '怎么总感觉下黑石塔卡得厉害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '听说玛拉顿的箱子不错，我该找队伍了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '别忘了奥达曼的怪，你一动它们就上来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '怎么就是找不到人陪我打黑石深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '你要是还在厄运之槌就别惦记掉落了，刷新太烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克的掉落为啥这么烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '嘿各位，45级能单刷厄运之槌吗，还是再等等');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '黑石深渊刷新怎么这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克有人帮忙挺好的，能轻松不少');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '这延迟太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '我在研究奥达曼的地形，实在乱得离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '嘿各位，我来自银月城，很高兴见到你们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '还记得我们以前打下黑石塔是图开心吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克能换坦吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '嘿，玛拉顿有要带的吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '血精灵在沉没的神庙里是真会玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '刚从黑石深渊拿到我第一件史诗，太美了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '我怎么早没想到，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '没事，钥匙我沉没的神庙拿了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '改天再打次玛拉顿吧，挺好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆刚开，缺治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 3, 0, 0, 0, 0, 10, '嘿各位，玛拉顿要帮忙就说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '血精灵到场，路过而已');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '听说黑翼之巢开了，走起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '我怀念大家都在通灵学院的时候，为啥总要跑到这鬼地方另一头？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '有人想打熔火之心吗？缺坦，打快点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '我看这儿有个新猎人得喂宠物');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '有人想刷上黑石塔吗？还差几个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '血精灵在此，奥爆已经练熟，我的法师准备好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '在斯坦索姆做日常，真是浪费时间！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '哪里能接任务？不想打扰大家，我刚玩这游戏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '通灵学院又是这样刷怪，一点都不好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '真希望现在就能打团本，可惜不行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '血精灵最牛，我们奥术最强，城最酷，银月城第一');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '刚通了熔火之心，满满的回忆杀');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '血精灵有格调，听说是这样，我们头发确实好看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚找队，有人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '谢谢通灵学院的建议，一次就过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '上黑石塔跟我记忆里一样难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布卡住了，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '哈哈我的战士连我猎人都追不上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '希利苏斯真美');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '顺手捡了两把银剑，64铜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, 'pvp竞技场装备求帮忙，有技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆总是难受，但我们搞定了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '马上回，传个银月城');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '嘿各位这儿怎么样，谢谢邀请');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '血精灵头发最好看，对吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '今天通灵学院掉得不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '哇上黑石塔简直噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '该死，各位我得复活，被那怪弄死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '大家好，希望你们今天过得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '哈哈熔火之心还差个法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '人类牛，我们吃的最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '不过我真喜欢血精灵的头发');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 4, 0, 0, 0, 0, 10, '哈哈我得歇会儿，猎人永远在要东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '嘿嘿，德莱尼在埃索达的欢迎队伍最热情');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '就算卡成那样，我也爱德莱尼那股精神');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '死亡矿井刷新怎么这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '怀念掉落真的多的那些日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '影牙城堡真狠，好在德莱尼够硬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '大家好，有人见过新坐骑了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '德莱尼和他们永不停歇的光明追寻');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '今天这卡得我烦，不过德莱尼可不会认输');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '队伍对了，熔火之心轻轻松松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '在死亡矿井耗时间，但我们能过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '怒焰找队，缺坦，10金酬劳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '我爱德莱尼文化');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '我们的种族天赋前期真管用，不觉得很爽吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '死亡矿井搞什么，开玩笑吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '太感谢帮忙打影牙那只蜘蛛了，欠你一次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '大家怎么看埃索达和纳鲁的背景故事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '马上回，得跑趟铁匠铺');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '死亡矿井里大家怎么总这么忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '这地方跟埃索达和我们族人一样让人安心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '嘿，有人知道从这儿去暴风城最快的路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '60级了没人喜欢等刷新');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '我们很强，可怒焰裂谷开头那几级……真够呛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '德莱尼以力量和坚韧著称，别忘了这点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '嘿，谁能告诉我最近飞行管理员在哪？我得赶紧去暴风城。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴有几个朋友就挺好打，就是别抢装备行吗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '哈哈，我能感觉到纳鲁的光在指引我，这个信标怎么开？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '有人能帮我练锻造吗？我有些废铁，但不知道怎么用。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '有时候有条尾巴确实不错，我能当个真正的跟屁虫哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '有人能教我在影牙怎么任务吗？打那个狼人需要什么？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷适合搞装备，不过当心那个元素怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '谢谢死亡矿井的攻略！那副本其实挺好玩的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢太好玩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '影牙太爽了，就是别让你家坦克吃太多苹果');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '有人能告诉我哪找厨师吗？我想学烹饪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '哪儿采药最好？我得练草药学。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '哈哈，我爱德莱尼，还有谁能说自己是未来来的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 1, 0, 0, 0, 0, 10, '谢谢帮忙。暴风城挺带劲，就算守卫多得要命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '大家好，黑暗深渊狩猎愉快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '德莱尼必胜，埃索达骄傲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '剃刀高地是个地狱坑，但经验值值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '监狱缺奶，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '该死，诺莫瑞根全是陷阱，我恨侏儒哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '又斯坦索姆？真不敢信我又回来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '血色僧侣可不是闹着玩的，里面机灵点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '你好，我是德莱尼，我很骄傲，我们的城超棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽要帮忙吗，找输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根是场冒险，小心那些活板门');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '埃索达有艾泽拉斯最好的自助餐，别错过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '剃刀高地最烂，但那是必经之路，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '我对血色僧侣是又爱又恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '副本是折腾人，但掉落很香');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '哈哈说真的，暴风城怎么一股旧袜子味？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '哇我们连首都都吵不出个结果，我干嘛在乎泰达希尔那个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '人类的城市最好，暴风城万岁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊最烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '有人能帮忙搞诺莫瑞根的钥匙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '暴风城的铁匠最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '德莱尼特别为自己的文化骄傲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '我们就是风暴，宝贝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '联盟该停止争吵了，看着挺蠢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '刚在剃刀岭杀了几个落单兽人，笑死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '德莱尼和他们的亮闪闪锤子，别老 /dance 了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '监狱比剃刀高地简单多了，我去哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '经典服刚开那会儿诺莫瑞根简单多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '这游戏里联盟该多点爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '血色修道院得找队伍，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '怀念在黑暗深渊刷100金都没人管的日子，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊的队伍就差个输出还行的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '该死，我的布又被抢了……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '这游戏变化不大，我还是爱德莱尼和他们闪亮的城');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊队伍求个会奉献的圣骑士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 2, 0, 0, 0, 0, 10, '德莱尼没有女王，但他们懂得让族人过得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '哈哈我居然从黑石深渊一路跑回这破地方，别学我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '我在找队，今晚谁刷下黑石塔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '德莱尼的骄傲很坚挺，可我们的脚真不行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '哈哈人类啥都擅长，连抱怨都擅长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '我是新手，谁能简单说说奥达曼会遇上啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '说真的祖尔法拉克那迷宫谁设计的，我又迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '刚在下黑石塔采了一堆草药，可包满了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '猎人明明样样最强，怎么老需要所有人帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '我爱剧情，但这些任务现在越来越难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '厄运之槌没我想的那么糟，就是食人魔越来越烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '我就是想念曼克里克的老婆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '德莱尼为啥总是做最好吃的点心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '待在这地方离埃索达这么远，我感觉自己像叛徒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '奥达曼找队，缺坦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层，坦克在哪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克真是要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '太谢谢那口奶了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '我在玛拉顿待的时间怕是比在自己家还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '黑石深渊简直就是地狱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '马上回，得去睡了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '有这帮啥都要的猎人，下黑石塔真是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '有人能给我跳个 /dance 吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克，我怀念不用到处跑的日子，我半辈子都在跑路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '奥达曼队伍缺奶，拜托');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '有人知道下黑石塔那条龙的好路线吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '我们真得快点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '怎么总是德莱尼得去祖尔法拉克受罪，多谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '玛拉顿采药有没有更省事的办法。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '这游戏到处是抢装备的，跟老鼠一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的小龙太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '玛拉顿的任务怎么这么无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 3, 0, 0, 0, 0, 10, '嘿，奥达曼队伍缺1个坦。哈哈不是我，我是奶，不是坦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '哈哈德莱尼主城真安静，要不是有敌人就更好了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '有德鲁伊要草药点吗？谢谢关心哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '冬天真难熬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚缺个坦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '熔火之心，纯粹是回忆杀');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '昨晚斯坦索姆真够呛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '我能加入吗？斯坦索姆找输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '德莱尼是个了不起的种族，就是别把他们弄湿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '通灵学院是艾泽拉斯最惨的地方，唯一更惨的是身上没buff');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布缺奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '我们要带至少60级宠物的猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '今天上黑石塔刷新时间又离谱了，搞什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '嘿，你们要刷祖尔格拉布跟我说一声，我能来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '通灵学院只要你会打，几乎很简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '今天熔火之心太热了，我得歇会儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '联盟万岁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '我们有史上最好的种族，别忘了，没错就是德莱尼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '抱歉来不了，又困在斯坦索姆了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆真是噩梦，我发誓那地方闹鬼，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '你要是有黑翼之巢的buff告诉我，pvp要用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '德鲁伊老说自己需要装备，真正需要的是我们。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '龙永远是pvp模式，看来它们太爱我们了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '有人能帮我打熔火之心吗？我搞不清该先打哪边');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆挂在组队频道，想来的话');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '这频道死了吗？我看我得换一个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '谢谢大家帮忙，这是我这个角色第一次打团本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴空得很，连回声都透着孤单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '我们还得再来点治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '无缘无故跳个舞？行。/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '怀念小时候带个宠物就能刷黑翼之巢的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚的巢穴怎么没人？总是空的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布出坐骑的几率多大？听说挺稀有的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '我发誓猎人总在要东西，不如干脆组个猎人啥都要俱乐部吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 11, 0, 4, 0, 0, 0, 0, 10, '说好的速刷上黑石塔，boss打得真艰难。gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布简直是噩梦，哪都不出东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '人类真是靠得住，哈哈别告诉我爹我刚说他无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '谢了治疗。不客气，坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '我想念以前，那会儿团本里还没一堆抢装备的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '上一波拉得漂亮，干得好兄弟们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '马上回来，去看看我的坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 4, 0, 0, 0, 0, 10, '谁能奶一下？轻松搞定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '真不敢信我又回到这等级了，感觉跟做梦重复一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '这么多年了，奥格瑞玛还是像家一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '锻造总算入门了，多谢教我那个兽人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '哇，怒焰裂谷跟记忆里一样简单，看来我就是玩得好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '我又回到一级了，大概这就是所谓的"从头开始"吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '我就喜欢兽人上来就掐喉咙，我们可不磨叽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '兽人一直是个硬骨头民族，我们还硬着呢，我有信心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '哈哈我老忘了我们一开始没蓝，挺难受的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '我想念以前，那会儿副本是真有意思，死亡矿井到现在还是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '死亡矿井还是那么刁，今天有得玩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '我就喜欢冲锋时那声兽人咆哮，不过确实有点过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '马上回来，去弄点新皮甲，别走开');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '狂暴的食人魔需要来杯啤酒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '照这速度死亡矿井快成我第二个家了，得赶紧多弄点金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '人类怎么老在说联盟这个部落那个的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '今晚又去哀嚎洞穴，祝我好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '兽人就是倔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '马上回来，得去熔点铁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '影牙里怎么这么多蜘蛛？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '真不敢信这任务要我杀100个巨魔，又是这样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '兽人就是艾泽拉斯的查克·诺里斯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '死亡矿井真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '我实在没空扯这些');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '要碰个头吗？我在奥格瑞玛的熔炉那儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '人类的骄傲无人能比，这东西难学也难精');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 1, 0, 0, 0, 0, 10, '有人知道哪儿采药好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '是我错觉还是黑暗深渊变难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '卡了抱歉，我这网跟过山车似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '还有谁在弄坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '血色修道院哪儿还有任务接');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根挺难，我要是有个术士就好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '剃刀高地真让人头疼，我得组个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '兽人不用坐骑，兽人自己开路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '等不及拿坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '大家好我是新手，有人知道剃刀沼泽有啥好任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '影牙城堡挺难啃，不过联盟团结得很');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '兽人向来以强壮坚韧出名，我就靠监狱里不放弃任务来证明这点！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '有人黑暗深渊要法师吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '刚30级，真不敢信马上能骑坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '农民在监狱求帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '侏儒怎么这么吵，该叫铁炉堡的大嗓门才对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '没事，就为我的新配方刷点金币，谁知道草药这么贵？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '有人有多余的开锁工具吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '为黑暗深渊备点治疗药水，我是新手，谢谢建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '真希望猎人别啥都要，刷起来太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '兽人是最烂的骑手，我想我的坐骑了，还有谁也卡成狗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷里全是穴居人，我可不想再被穴居人弄死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '我有种要死的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊总是很欢乐');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '矮人，个头最小嗓门最大');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根太太太太好玩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '我这游戏玩得太太太烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '哈哈前提是有人能找到这地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 2, 0, 0, 0, 0, 10, '这本纯属浪费时间，我该去剃刀沼泽的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '谢谢邀请我去祖尔法拉克，我这就过去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '大家好，奥格瑞玛的兽人战士们今天怎么样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '马上回来，去看看玛拉顿有没有人要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '求带刷本，影牙城堡太硬了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层卡得离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '嗨，兽人兄弟们准备好了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '厄运之槌又空了，是只有我这样吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '玛拉顿怎么老塞满那些巨魔？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '走，兽人上前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '奥达曼跑哪去了？不在这儿啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '想念以前，那会儿到处都能看到兽人战士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '嘿兄弟们，奥达曼要个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '谢谢祖尔法拉克的奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层今天真难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '这镇子就像个人类大派对，全是人类');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '想念玛拉顿还没满地持续治疗那会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '干掉那个BOSS之后别忘了跳个舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '猎人永远嫌自己DPS不够');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '大家好，你们要点啥吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '哇，玛拉顿还是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '德鲁伊真别再跟BOSS跳舞了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '兽人干得更漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '谢谢所有帮奥达曼这一趟的人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '又在黑石深渊刷铁了，真刺激');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '还有谁也卡在玛拉顿这延迟里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '谁能帮我刷点雷矛卫队的声望啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '还有谁喜欢暴风城夜里那股味道');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '队伍好，祖尔法拉克很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '神庙这怪一点不含糊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '哈哈兽人天生方向感不好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '谁来治治我在黑石深渊的捡装备瘾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '厄运之槌单刷是噩梦，但最后值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '哇原来真能凑出个好队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '玛拉顿要治疗，求奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 3, 0, 0, 0, 0, 10, '这无限刷新到底有啥意义');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '哟，部落又一个光辉的日子，去宰几个联盟渣滓，攒点荣誉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '抱歉兄弟们，得走了，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '人类有时候骄傲得让人没法合作，不过我们还是最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '哈哈我错过坐骑了，还跑反了方向');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '哈哈我看见新会长想/dance，结果卡椅子上了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '该死的刷新时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '刚拿到60级坐骑，跟做梦一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '兽人干得更漂亮，尤其是在自己首都');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '通灵学院求组，别来抢装备的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '部落打不过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '见啥捡啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '我烦透挖矿镐断了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷其实挺好玩的，就是别卡住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '但愿我能在黑石塔上层找到那破装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '刚在拍卖行刷了不少金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '这延迟我是真受够了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '奥格瑞玛的兽人派对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '我去又一个刷新计时，我怎么就不能快点杀怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '哈哈奥格瑞玛的兽人，就为装备跑到斯坦索姆来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '有怒气还要什么蓝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '刷刷刷，我盯上那个60%的采矿加成了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '小意思，再刷点金币就够这坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '我想念黑石深渊以前的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '死亡矿井缺人，求个治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '谢谢这装备，我这回真盼着出点好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '笑死，我刚在BOSS面前/dance了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层随便刷，来个DPS');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '这趟通灵学院太久了，我等的刷新都快赶上杀BOSS数了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '奥格瑞玛的兽人！我们可不只有肉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 2, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚要个T，我们DPS多到能把山融了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '谁知道矮人从这儿去暴风城最快怎么走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '有人知道这附近哪儿弄铁锭吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '矮人也得赚金币啊，别嫌我们贪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我就在艾尔文森林把矿采完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '大伙儿，今天刷新怎么这么慢，那头熊我杀了老半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '这儿还有人没坐骑吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '哈哈真不敢信我们得从一级开始');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷求帮忙，有好坦克吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '还在琢磨怎么弄铁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '还有谁嫌挖矿太慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '死亡矿井求组，也不知道会遇上啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '有人知道哪儿弄银矿吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我能问问你咋连把矿镐都没有吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '大家好，矮人给这儿的铁炉堡兄弟问个好！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '马上回来，得去看看有没有黑铁矮人又来偷我午饭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '人类最棒，只有暴风城才叫地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '还有人记得怒焰裂谷以前那好日子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我要当猎人，这样我才能让别人去倒垃圾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我们矮人可不会让人忘了我们铁与石的传统');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '今天我得进影牙城堡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '真不敢信他们又让我们采铜，谢谢铁炉堡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我们是矮人，总能把你弄出去，死亡矿井求治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴那些破迅猛龙，没事我等');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷是个噩梦，但至少我们有啤酒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '哈哈你该看看那些新手怎么在影牙拉怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我们扛得住，也绝不会被人拒绝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '谁能帮我做那个从湖里捡鱼鳞的任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我们干嘛又得打这些东西，轻松打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '我爱铁炉堡，不过天啊任务日志越来越长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '一生联盟，谢谢死亡矿井的帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '矮人随时准备砸开一桶酒，我们都需要这个，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 1, 0, 0, 0, 0, 10, '这些天还有谁烦透了挖矿，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '矮人从不改变，除了胡子，一直长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根可好玩了……对侏儒来说，反正不是对我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '终于拿到坐骑了，舒服');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '监狱就是个巨大的牢笼……里面全是带着笼子的卫兵');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '我想念那会儿大家都在忙着升级的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '谢了这装备，我比你更需要它');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '谁能对着延迟/dance一下让它停？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '我发誓再看见一条浑浊的鱼我就变成鱼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '铁炉堡，每天都像在家，但比家更好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '哈哈，监狱出的东西跟没胡子的矮人一样稀罕');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '大家好，刚玩了个矮人，要怀念铁炉堡所有的酒了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '有人黑暗深渊要帮忙吗，我和我兄弟都快长鳃了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '血色修道院求组，求坦克和治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '矮人分两种：又矮又壮，或者又高又傻。我：又高又傻');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '剃刀高地这地方，你不是战士就太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '各位好，我以前是猎人，后来膝盖中了一箭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '有人知道死亡矿井怎么走吗？我卡半道了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根没个术士感觉空荡荡的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '早啊，有人知道铁炉堡附近采药采矿的好地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '恭喜拿到坐骑，感觉我升级升了一辈子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '卡在监狱的一个任务上了，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '还有谁记得Leeroy Jenkins冲进副本那会儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '乐意帮大家血色修道院，我才35级，要不了多少东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '各位好，有谁有单刷剃刀沼泽的诀窍？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '我们先把监狱打完，再去剃刀');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊有时候真烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '我爱我们的矮人胡子，我们是个强悍的民族，不过铁炉堡的麦酒才是我的最爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '暴风城万岁，全游戏最好的吃的和酒都在这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '等我一下，包满了，去清一清');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '这就是在血色修道院找到最好装备的办法……前提是你跑得过卫兵');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '剃刀高地的亡灵挺烦，不过装备不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '别忘了攒点金币买史诗坐骑，以后你想骑个好点的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '这地方谁设计的？到处都是石头！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 2, 0, 0, 0, 0, 10, '靠，我是矮人，可不该迷路的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '真不敢信我终于到奥达曼了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '有人祖尔法拉克要帮忙吗？我是个经验丰富的矮人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我找不到玛拉顿的入口，哈哈，谢谢帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我想升级，可我朋友都甩我老远了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '我就喜欢人类，永远给我们撑腰');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '嘿我刚进游戏，谢谢大家帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '有人知道沉没的神庙的事儿吗，跟我说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '铁炉堡怎么走啊？我迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '矮人最牛，铁炉堡永远第一');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我被黑石塔下层的任务卡住了，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '想问问黑石深渊那个任务值不值得做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的任务我每次都搞不定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '想不通沉没的神庙为啥这么神秘');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我在厄运之槌，求指点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的入口在哪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '矮人最厉害，不过我们也总需要帮手，哪怕是矮人来帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '那头熊还在追我，这任务简直没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '还有谁怀念铁炉堡没这么挤的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '为啥在祖尔法拉克死了以后复活这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '矮人的啤酒最好喝，有人知道哪儿还有烈性黑啤吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '刚在黑石塔下层挖了一堆铁矿脉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '厄运之槌的延迟是越来越离谱了，我发誓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '玛拉顿刷起来太爽了，好东西一堆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '哈哈我要是什么都不干就能拿这些装备就好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '还有谁记得奥达曼当年是真的难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '刚刷了一趟沉没的神庙，这地方永远不腻');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我可爱看新人在黑石深渊一头撞上坦克了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '怎么每个猎人没宠物就活不了，连在熊洞里都这样，哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '找公会，缺输出打团本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '大家好呀，暴风城这边晚上好哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '哈哈有人要矮人坦祖尔法拉克吗？我闲着呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '大家怎么样，我在这练锻造呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '奥达曼有啥窍门吗？我在里面完全迷路了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我爱咱们矮人，喝得多是多了点，但活儿干得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '谁要一起刷黑石深渊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '在玛拉顿刷了点金币和草药，要的尽管问');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '好像在哪儿见过你，终于说上话了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '谁想通宵打副本？我就想找个伴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '那洞里出的东西太爽了，感觉真好哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '厄运之槌有人要搭把手的吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '我是矮人，见过不少世面哈哈，副本算我一个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 3, 0, 0, 0, 0, 10, '刚升59，想去坦几趟沉没的神庙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '谢谢大家通灵学院那趟的帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '矮人就爱铁炉堡和自家的麦酒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '拉下一波了，跟紧点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚缺个坦，在这儿回我，顺便带几个肉盾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '铁炉堡最好的酒坊，全靠咱们矮人撑着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '哈哈我们懒得建新公会了，能进你们公会吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层挺刁的，别多拉怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '谁能带我过一遍怒焰裂谷？我第一次来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '终于拿到史诗坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布缺个治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '矮人就图个痛痛快快跳舞喝酒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '上次熔火之心那趟打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '马上回来，在斯坦索姆奶坦呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢还差俩人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '多谢组我，新人一个，求点经验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '铁炉堡的啤酒天下第一，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '矮人跟麦酒从不放假');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '哇熔火之心太刺激了，有人有窍门吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '谢谢你陪我跳舞，太好玩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '还差几块金矿石，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆闹鬼，可这不就是好玩的地方吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '矮人配啤酒，天下无敌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '有人知道黑石塔上层的稀有怪在哪儿刷吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '怀念老团本，那时候的东西才叫史诗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '我在琢磨配什么武器合适，好去干掉奥妮克希亚的boss');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '嘿兄弟们，矮人在此。记得多带点吃的，你知道的，我们爱吃');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '还有谁觉得侏儒工程师就是自尊心更大的迷你矮人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '多谢在黑石塔上层奶我，我在里面迷了一小会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '哈哈真不敢相信我忘了买药水，在斯坦索姆挂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '那装备怎么不直接蹦我包里啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '奥妮缺副坦吗。哈哈我还欠着dkp呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '钓鱼这玩意儿我还是玩不明白');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '刚拿到黑翼之巢的史诗装，感觉真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '还有别的矮人主号跟我一样爱铁炉堡吗？吃的真是一绝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布打得漂亮。我也不知道这名字啥意思，反正就是爽，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '还有谁怀念当年的pvp？哈哈，那些年啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '矮人酿酒师的神圣职责就是能喝多少喝多少。/干杯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 3, 0, 4, 0, 0, 0, 0, 10, '当年是苦，可那些团本才叫史诗。熔火之心是我的最爱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '暗夜精灵最棒，就是树老往我头上掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '多谢给矿，挖矿就差升到6级了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '人类从不放弃，只是越放弃越熟练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '这堆破烂得找个商人卖掉，有啥建议吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '哈哈咱们那些树确实该修修枝了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '我大概该学学钓鱼了，多谢提醒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '刚在灰谷刷了好几个小时');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '谁能帮我找找死亡矿井，我第一次下副本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '啊，又是哀嚎洞穴那个噩梦，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '论种族还是暗夜精灵最强，我们天生就跟林子亲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷习惯了也就那样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '玩得正爽的时候复活时间老长了，一死起来又老短');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '嘿谁能告诉我练猎人最省事的办法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '37级人类，黑暗深渊求带');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '上次我挂了多谢帮忙，这么学可不怎么愉快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '我喜欢影牙城堡，剧情太有意思了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '我不采药的时候就在达纳苏斯的酒馆里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '我爱达纳苏斯，就跟第二个家一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '这延迟真烦，沉浸感全没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '真希望能在影牙城堡里来段/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '咱们的掉落怎么有时这么差？希望能搞把好武器');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '达纳苏斯像家一样，就是那些蜘蛛还是毛毛的哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '暗夜精灵最强，谁不服我就跟谁打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '求艾尔文森林刷金币的窍门');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '刚升到30级，终于有坐骑了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '刚拿到第一套皮甲，谢啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '怎么谁都缺猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '还记得怒焰裂谷当年是真难吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '我就爱看新人在逆风小径问"怪在哪儿"');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '带个治疗的话，影牙城堡其实挺好玩的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '马上回来，去练工程学');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '当炼金师最爽的就是白拿药水');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '暗夜精灵文化博大精深，可这城有时候跟迷宫似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴真是满满的回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '哇终于30级了，我的暗影呢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '刚入坑魔兽，不过到现在还挺喜欢暴风城的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '监狱清怪清得不错，再要个治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '我爱这些古树，老兄，跟家一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '谁要坐骑？我是暗夜精灵，我跑得比它还快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根。不是第一次来了，可我还是讨厌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '你们知道暴风城监狱有攻略没？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '暗夜精灵为啥这么爱树，因为咱们爬树比人类强？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '马上回来，得补点箭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '侏儒，开个传送门，100金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '在监狱里一死就得跑回墓地，烦死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '有人要速刷剃刀高地吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '出售秘银矿石，详情私聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根真是拖得要命，我要是有好装备就好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '刷完血色修道院还有谁想歇会儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '有德鲁伊多出皮革要卖吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '暗夜精灵太能潜行了，偷着来段/dance都没人发现');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '攒钱买坐骑最快的路子是啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '这游戏的复活时间简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '刚在黑暗深渊摸到件好货，爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '大家好呀，都咋样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '想去剃刀高地刷皮革，有人一起吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '德鲁伊不就是会变身的抱树党。他们抱怨就甭理');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '马上回来，得回阿斯特兰纳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '人类：随时备着玩笑，也备着剑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '我觉得我的猎人需要抱抱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '没事，那任务祝你好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根现在挺容易的。我倒怀念它难的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '冲挖矿最好的方法是啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '我终于能骑坐骑了，太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '我爱暗夜精灵，可阿斯特兰纳有点无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 2, 0, 0, 0, 0, 10, '我在打黑暗深渊，就是太慢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '哈哈，精灵到底为啥爱树来着？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '快到祖尔法拉克了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '不好意思，刚才挂机了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剃刀高地刷起来累，但装备值得，多谢治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '怎么大家都从我旁边跑过去了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '我以为厄运之槌挺容易的，结果我挂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层是挺难的，不过打得快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '我完全不知道该干啥，求帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '黑石深渊你得亲自下去趟一趟水');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '谢谢大家到目前为止的建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '玛拉顿求个队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙打对了就特别爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '战斗中跳舞肯定不是什么好主意，不过我还是照跳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '这儿练级咋样哈哈，别忘了去尘泥沼泽拿那个坐骑任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '血色修道院挺难，缺个T，求坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '记住，别把仇恨引到治疗身上哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '我喜欢玛拉顿，换换节奏挺好，不过小心多头蛇，那玩意儿真烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '没准备的话厄运之槌可不好过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙是个噩梦，可那掉落值了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '对暗夜精灵来说，达纳苏斯就是第二个家。太美了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 3, 0, 0, 0, 0, 10, '摸清门道的话祖尔法拉克一路顺风。小心那些巨魔');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '真不敢相信副本里还有延迟，我还以为早修好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆的复活时间太狠了，跟原地打转似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '在熔火之心摸到稀有装备太爽了，可这副本打一趟老久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '达纳苏斯今天怎么下雨了，我真受不了了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽有几波怪拉得挺刁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '马上回来，得给今晚的祖尔格拉布团本补点药水');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚巢穴那件掉落我到现在还乐。这东西真沉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '还有谁喜欢暗夜精灵的主城？那地方又美又有生气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '嘿大家好，咋样？在灰谷享受美丽的夜晚吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '猎人得去看看陷阱，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '暗夜精灵的潜行是出了名的。谢了兄弟们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '打得漂亮，团灭了，再来一把');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚缺个坦，谁来？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '通灵学院这季节阴森得很');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布太难了……连巨魔都在死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '人类是扛得住，不过老兄，我真想念以前那家酒馆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '大家好，去黑石塔上层吧，有人来吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '真不敢相信我们终于把熔火之心那趟打完了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '我得刷刷暴风城的声望，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '大家好，我要去斯坦索姆了，一起来吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '暗夜精灵的耳朵最漂亮，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '这延迟真受不了。也许我该去林子里散散步');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '旅行者们好啊。来随着夜晚的摇篮曲跳一支吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '今天熔火之心就是个噩梦。我干嘛要听心里那个猎人的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢的队满了，就差个猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '谢谢那个顺手帮我的治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '有人要查DPS吗？我给团队打伤害很轻松的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '抱歉，马上回来。得睡个暗夜精灵的老式午觉清清脑子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '队里缺第二个坦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 4, 0, 4, 0, 0, 0, 0, 10, '真希望联盟的潜行手段有你们暗夜精灵盗贼这么多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '猎人该换个新宠物了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '哈哈影牙城堡小菜一碟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '寒冰箭！谢谢buff');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '谢谢给的金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '马上回来，得救人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '谢谢帮忙拉仇恨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, 'NPC真让人搞不懂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '监狱组队吗？求坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '大家好，新来的亡灵哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '幽暗城阴森森的，可我就是喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '还记得咱们进不了人类主城那会儿吗？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '还有谁怀念团本真叫团本的时候？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '哈哈我试着当亡灵跳舞，好像抽筋了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '影牙城堡到底难不难？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '嘿鱼人吃起来啥味儿啊哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '谢谢欢迎，我已经死了4次了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '部落经历了不少事，不过我们照样玩得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '正琢磨着进怒焰裂谷，多谢支招！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '人类永远知道最好的酒馆在哪，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '这才是魔兽最棒的地方。我感觉自己像个全新的亡灵');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '影牙城堡把我整得压力山大哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴看着也挺好玩！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '亡灵是最强种族，不过幽暗城可不是什么阳光加州');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '死亡矿井缺个法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '我从来没见过桥那头，在怒焰裂谷里一直死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '哇，今天真能感受到部落的精神');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '大家好，刚开始采药和剥皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '早说了影牙城堡该走左边那条道');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '我想念我在哀嚎洞穴那会儿的老战士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '还有谁想练法师，就因为法师太帅了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根，满满都是回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '死亡矿井还要个猎人，输出不够');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '哎哟又卡了一下，我直接穿墙过去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '我就来刷刷金币，顺便练剥皮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '亡灵的头发比哪个种族都好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 1, 0, 0, 0, 0, 10, '给我的亡灵朋友们来个/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊把我们揍惨了，有啥窍门吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '水下打架真难受哈哈。我得换身好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '去剃刀高地最快的路咋走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽是我的克星');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '多谢大家帮忙！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '卡在血色修士那个任务上了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '怀念当年在剃刀高地的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '还记得黑暗深渊当年有多难吗？我觉得自己老了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '碰上这些新坦，血色修道院就是个噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '监狱比我记得的容易多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '剧情党们，幽暗城到底出了啥事？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '当亡灵有当亡灵的好处。再说幽暗城的景色绝了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '有人知道这附近哪儿刷魔纹布吗？马上回来，我去看看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '部落的派对最带劲。我压根想不出还能去哪儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '这些新任务我太喜欢了，太棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '又在黑暗深渊水里复活了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽简直像个迷宫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '有人要组诺莫瑞根吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '剧情党集合，亡灵的故事真让人心酸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '又在黑暗深渊水里复活了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽清了，监狱缺人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '延迟要命，不过好歹我是亡灵部落的一员');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊的水比水上乐园还多哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '猎人又要买箭了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '剃刀高地干嘛非得叫"高地"呢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '血色修道院，我打盹的最爱地点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '曼克里克的妻子又在幽暗城了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '谢谢推荐坐骑，帮我省了不少时间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '有人能帮帮这儿的亡灵吗？我在剃刀岭彻底迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '少了其他亡灵，幽暗城总感觉空荡荡的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '上面那次治疗太感谢了，帮大忙了！差点就错过机会');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '还有谁爱这种狩猎的快感？队里还缺猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '大家好呀，在这儿见到各位可爱的人类真高兴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '还记得咱们到处乱跑、在黑暗深渊里送命的日子吗？好时光');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根有啥窍门吗？我觉得我哪儿弄错了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '我知道该多用用暗影技能，就是改不了这么爱社交');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '刚拿到坐骑！终于能到处骑了，太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '血色修道院总让我心里发毛。就爱这感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '监狱没个好治疗就是遭罪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '我是剧情党，可老兄，我在诺莫瑞根天天挨揍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 2, 0, 0, 0, 0, 10, '你们剃刀高地的小怪都怎么处理的？有啥窍门吗？我得回点血');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '亡灵在此，味儿大不好意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '谢谢组我，赶紧打完吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '哇又是奥达曼哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '咱们该聊聊那些术士了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '咱们能快点吗，我得走了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '这地方让我直起鸡皮疙瘩，我看今天就到这儿吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '我觉得得赶紧出黑石塔下层，别被困住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '咱们怎么老卡在打那些该死的雏龙上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '人类的巧思是吧？我们侏儒正需要这个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '走吧！我得回亡灵城了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克真难受，好在咱们亡灵不用吸那些灰');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '马上回来，正跑回幽暗城。这地方怎么好东西全在这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '玛拉顿求帮忙，那路太难走了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '亡灵的想法：干嘛不直接穿墙过去，跟他们打不值当');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '有人组沉没的神庙吗？我可以试几次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '黑石深渊那件稀有掉落怎么出？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '真不敢相信复活时间就这么没了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '奥达曼需要啥就说，我能带。这儿我来了上千回了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '有人知道厄运之槌那些稀有怪怎么弄吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '沼泽那边祝你好运，希望你能活着走出陷阱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '亡灵从不抱怨冷。反正咱们早死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层最烂了。我干嘛要这么折腾自己？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '管他什么复活，这点掉落不值当');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '求法师开幽暗城的门。我去凑点材料就出发');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '在刷藏宝湾的声望。得像当年在荆棘谷那样多留个心眼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '我老看见那些盗贼玩家。你说他们要不要学点偷袭的窍门？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '练级的时候锻造有啥窍门吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '草药学求指点，有人知道祖尔法拉克哪儿好采吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '刚把一堆秘银卖了200金。亡灵的日子真不赖');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '在攒我的第一匹史诗坐骑。别问我为啥对一匹骷髅马这么兴奋');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剃刀高地对我来说有点太大了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '幽暗城是最好的城。没有光晃眼睛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 3, 0, 0, 0, 0, 10, '刚从玛拉顿回来。乱成一锅粥，我真喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '今晚去清斯坦索姆吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '哈哈真不敢相信咱们还在刷斯坦索姆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '我是亡灵我骄傲，幽暗城又平常一天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '有人要组通灵学院吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '今天咱们还要去几趟黑石？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '谢谢组我打祖尔格拉布');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '咱们到底为啥还要打黑翼之巢来着？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '可惜奥妮还得再清几趟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽嘛，全是情怀');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '哇咱们也不至于来得这么勤吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '哇真不敢相信咱们又来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '出售整套板甲，便宜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '大家好，今天在这儿见到各位真高兴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆之后去打黑石深渊？10分钟后出发');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '哈哈还在点坦克天赋呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '卖斯坦索姆带刷，一趟40银，有人要来吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '多谢治疗，你那下救了我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '没事兄弟们，打得漂亮，下一把去祖尔格拉布');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '求帮忙打通灵学院，先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '马上回来，刚接到血色那串任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '咱们又要全死在熔火之心最后那个boss手里了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '我就想把奥妮克希亚干掉算了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '马上回来，得去修装备，又没钱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '刚攒够买新坐骑的金币，感觉真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '今晚熔火之心，谁跟我？我水带得足');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '亡灵没什么朋友，但盟友最棒。说的就是你们，术士');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '草药够了，今晚就到这儿。该睡了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '谁要热水澡啊，在墓地里泡着多舒服？就着提瑞斯法林地的月光');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 5, 0, 4, 0, 0, 0, 0, 10, '又一个亡灵，四处找金币和草药。刷子生涯没个头');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '怀念当年部落和联盟还能说上话的日子。现在可不行喽！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '想念以前那会儿，我们只管揍兽人就完事了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '嗨，黑暗深渊求组，顺便交点朋友');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '萨尔打架打到一半怎么还这么淡定？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '还有谁想练个牛头法师？升级是慢，但法师毕竟是法师啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '嚯，牛头人是真爱他们的野牛。不过话说回来，是真好吃！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '在艾尔文森林刷矿，没问题。就看着我那一百块矿石越堆越高。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '有人要组队去死亡矿井吗？我倒是能抗，就是想要点帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '我们台词都特牛，比如"为了部落！"——可这到底啥意思啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '目前我们只去得起哀嚎洞穴。不过凑合也够用了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '萨尔这战士是最佛的一个。我也想把我的"佛系"练上去。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '狂暴牛头战士，哈哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '我在沙漠采了一整天草药，爽翻了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '欢迎来暴风城，我在这儿就为了金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '这附近哪儿草药最好啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '莫高雷今天真漂亮。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '哈哈，我迷路了，不过我不在乎。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '牛头人是最强的种族。就这么定了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '雷霆崖的风景，全艾泽拉斯第一。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '谢谢钓鱼竿的建议。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '我角色这新坐骑，爱了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '记住，杀完一定要跳个舞。/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '我该从哪儿开始做任务啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '剧情党越看越想出去逛逛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剧情和氛围爱好者');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '需要更多牛头人增益。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '新练个牛头人升级有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '有人发现新副本装备掉率改了吗？死亡矿井里啥好东西都刷不出来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '终于拿到坐骑了，激动死我了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '知道牛头人为啥跑这么快吗？因为我们爱莫高雷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '谁要组队？哀嚎洞穴招坦克、治疗，10级以上。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '哈哈，我这猎人怎么见啥啃啥啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '血少的时候进怒焰裂谷就是噩梦，GG。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '制皮得去部落主城学吗，还是莫高雷就能练？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '谁知道怎么快速刷金？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '马上回来，得去找监狱的攻略');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '别人怎么单刷影牙城堡那么轻松？我被打得满地找牙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '这制皮太磨人了，马上要升10级了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 1, 0, 0, 0, 0, 10, '莫高雷哪儿草药点最好？分享下呗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '黑深渊通了吗？招个坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '谢了各位，这把打得不错，监牢清了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '又去诺莫瑞根？认真的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '牛头人的骄傲，没问题。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽太无聊了，可我缺声望啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '怀念以前没那么多坐骑可挑的日子。不过血色修道院还是随便打。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '那些啥都要的猎人，笑死。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '今晚黑暗深渊？求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '今早剃刀高地有点难顶。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '谢谢加血，我差点就去跟暗影跳舞了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '哪儿还能找到更多狼？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '弟兄们，今天黑深渊刷起来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '嚯，部落真是相亲相爱一家人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根真是个坑爹地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '有没有人给点血色修道院的通关建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '求个剃刀沼泽的队伍，谢谢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '我想念以前的部落了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '谢谢加好友，马上回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '总有一天我们都得去面对血色修道院');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '牛头人比平时多的时候，就知道是满月了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '血色僧侣是真烦人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '嚯，这就是新坐骑？一堆铁啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '你说查克·诺里斯到贫瘠之地会干啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '谢谢加血，救我一命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '我能加你们任务队吗？开传送门还差3个人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '大家好，有谁血色修道院要帮忙的，招1个坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '我发誓，街上再看见一个巨魔，我眼皮就得跳。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '黑深渊有啥技巧吗？我一直打不过去。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '剃刀高地太磨人了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '你们有空都该去找曼克里克聊聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '我为啥又roll了牛头人？躲草丛都躲不进去。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '谁知道快速升级的办法？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 2, 0, 0, 0, 0, 10, '牛头人得跑多少趟邮箱，邮差才肯直接送上门啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '这怪我没见过，不过我喜欢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '谢谢帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '高等级玩家都挺爱帮忙的，人真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '嚯你40了？我还有一大堆要肝的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '谁会想去贫瘠之地啊？我以为部落不止这点地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '哇，谁要开屠？我是盗贼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '我爱我的盗贼，现在你能看见我吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '哈哈我没联盟那么强，不过也快赶上了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '当牛头人就是开心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '有好多新地方可逛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '我只要去趟奥达曼就齐活了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '真没人去祖尔法拉克吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '奥达曼的各位好啊，走起！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '有人组队刷祖尔法拉克吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '谢谢加血！又救了我这牛屁股一命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '怀念从前，那时候奥格瑞玛还只是个梦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '牛头人也是要吃饭的。我还是个猎人呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '嚯，玛拉顿这魔法真够阴的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '你绝对找不到一个不入公会还不为此自豪的人类');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '有人在黑石深渊给我加个buff吗，我太脆了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '厄运之槌是我最爱的副本，弯弯绕绕特别多。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '怀念还没这么多新职业的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '又黑石深渊？我这牛腿都跑累了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '有法师在沉没的神庙给我加buff吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '希望这身牛头人力气别坑我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '坦克怎么老在左上角啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '萨尔会骄傲的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '大家好，我是新来的，能告诉我该去哪儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '找人一起去黑海岸刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '剃刀高地今晚还是明天，算了，我现在就有空，求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '谁想打祖尔法拉克？我这有队伍。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '又在玛拉顿肝。我到底为啥要玩这游戏来着？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层就是死亡陷阱，但至少好玩。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '厄运之槌怎么这么多食人魔？到处都是。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '大家好！能告诉我怎么去沉没的神庙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 3, 0, 0, 0, 0, 10, '黑石深渊就从来没变简单过吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '刚跟野队打完斯坦索姆，他们都超赞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '在核心区刷最后那点魔纹布。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '还记得我们以前在曼克里克的老婆身上跳舞吗？那会儿真快乐。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '我爱清晨奥格瑞玛的味道。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '我完全不知道该干啥，来人救救我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '今晚大家是去诺莫瑞根还是监狱？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '谁想找个简单任务，跟我说，我有心得。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '我靠。我复活时间比牛头人打个盹还长。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '又在核心区摸尸，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '熔火之心招个治疗，能扛那个boss还显得毫不费力的那种。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '靠，刷皮被断了，这延迟气死我了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '我发誓，今天掉宝之神肯定恨我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '谁能跟我拿这些魔纹布换金币啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '哈哈，我得摸尸啊。抢装备的真的想让我吼出来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '谁想组队打奥妮克希亚？我这儿有靠谱坦克和治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '通灵学院还是一样阴森，不过掉落值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '大家好，联盟又平常一天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '在我眼里曼克里克的老婆是个神任务，该回归。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '怀念那时候我们还在研究怎么骑公羊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '刚拿到史诗坐骑，又找回当牛头人的感觉了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆是难，但掉落值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '黑翼需要帮忙，有人吗？招坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '牛头人是为迎风而生的，不是为游泳的 :p');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '当年熔火之心就是噩梦，谢谢帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '还有谁在肝坐骑那点最后的声望？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '有人能帮我们抗斯坦索姆吗，谢谢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '部落是真爱，可曼克里克老婆的梗还没完呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '谢谢治疗。小事，顺手的事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '我在去通灵学院的路上，还有谁要一起？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '哈哈，我刚发现我在祖尔格拉布转了15分钟圈，得练练认路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '我在去黑石塔上层的路上，有治疗跟我们吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 6, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布自己抗是真难。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '侏儒是不太好找，不过我们玩陷阱是一把好手。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '谢谢帮忙。第一次来怒焰，有啥技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '对，就是死亡矿井。队伍好的话挺轻松的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '我就喜欢我们个子最矮，却能拿个罐头盒造出死亡射线。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '真不敢信我第一次打死亡矿井，我都13级了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '影牙城堡轻松得很，就看有没有耐心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '我最爱看猎人啥都要的样子了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '没问题，慢慢来，注意陷阱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '又是哀嚎洞穴，哈哈。我们永远刷不腻。就喜欢我们啥都能干。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '我啥没见过，可这洞穴还真让我有点怕。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '我陷阱多得是，我要当陷阱之王。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '侏儒是最好的工程师，谁要搞陷阱帮忙，知道上哪儿找我们。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '有侏儒在，谁都不安全。除了我的陷阱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '谁想来一把死亡矿井？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '侏儒不就是矮个精灵嘛，对吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '谢谢大家帮我刷矿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '影牙城堡有点吓人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 2, 0, 0, 0, 0, 10, '在暴风城，人人都得有个坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '刚到5级，侏儒牛逼。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷太狂野了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴为啥在哀嚎啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '你知道去铁炉堡还是得走一段的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '看来我要永远困在新手区了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '有谁给点法师职业的建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '我们是过了，但有点无聊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴就这样？真没了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '一直不喜欢亡灵，太瘆人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '大家好，我是新来的。你们不常碰见侏儒吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '还有谁喜欢铁炉堡这股联盟味儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '这附近哪儿有铁矿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '哈哈，真不敢相信我成了侏儒，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '死亡矿井那些破小怪老拉仇恨。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴挺不错的，就是那些蜘蛛……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '这儿有侏儒吗？来聊聊天！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '我的偷窃技能第一次升了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '侏儒工程师集合！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '怒焰需要组队，还有谁？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 1, 0, 0, 0, 0, 10, '还有谁喜欢铁炉堡的声音？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '玩陷阱侏儒最在行，别忘了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '奥达曼还是一如既往地无聊，哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '我去剃刀高地，有人要排队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '哇，都十年了，心里难受，不过至少这次升级快多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '我爱诺莫瑞根，那味道跟家一样，不过你知道真正让我抓狂的是啥吗……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '黑深渊我们真的不能再打了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '监牢和诺莫瑞根在我心里永远有个特别的位置。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '还记得以前大家庆祝时都 /dance 吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '血色修道院永远是个挑战。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '我不是抱怨啊，可血色修道院咋还是没多点箱子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '有人知道黑深渊的快速路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '侏儒爱诺莫瑞根，但不是人人都受得了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '我发誓这已经是第十次在祖尔法拉克被这些巨魔弄死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '坦克天赋已就绪，血色走起。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '嚯，这地方又全是鱼人了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '看来得找几个猎人跟着。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '哈哈，有人把我的战利品抢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '就差几块银币买坐骑了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '我当初真该去当猎人的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '求个人来跟我跳舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '这地方信息量有点大。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '侏儒万岁，谁知道我们下次又发明啥。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '小贴士：在赤脊山刷怪记得把坐骑停附近。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '这儿沉得比神庙还快，笑死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '老兄，这儿的复活时间怎么老感觉这么长。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽太狠了，得有人来帮忙才过得去。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '哈哈，又在诺莫瑞根迷路了，有人知道最快出口吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '黑深渊是挺难，但掉落值。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '我发誓今天掉率有点抠门。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '剃刀高地没大家说的那么糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '今晚这延迟，血色修道院真难受。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '侏儒是当法师最好的种族，太好玩了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '现在正在赤脊山刷经验。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 2, 0, 0, 0, 0, 10, '赤脊山的任务又烦又带劲。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '这黑石深渊跟那些该死的食人魔到底什么关系');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '马上就好，就等我那些侏儒朋友把工程活儿忙完。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '有谁多一张敏捷卷轴吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '侏儒的科技和机械最牛。就这么一说，别被打个措手不及。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '我也说不准黑石深渊里更危险的是敌人还是我们自己的火力。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '奥达曼求组队，求组！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '厄运之槌太磨人，尤其是一堆陷阱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '侏儒为啥过马路？当然是去祖尔法拉克那头，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '侏儒友情提醒：看好你的血瓶。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '唯一比侏儒更好的，是侏儒工程师。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '侏儒是最聪明的种族，这谁都知道。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '死亡矿井真好玩，我都想不起来上回打是啥时候了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '黑石塔里这些怪真要命，谢谢治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '奥达曼是个迷宫，但至少没巨魔。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '嘿，这附近哪儿有个清净地方来着……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '厄运之槌东边跟侏儒的头发一样乱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '谢谢加血。对侏儒来说不错了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '侏儒为啥过马路？为了去沉没的神庙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层是练躲火的好地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克我们都刷够多遍了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '在诺莫瑞根那会儿，我们可从没这么轻松过。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '黑石深渊里跟烤炉一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '嚯，认识一个猎人之前我都不知道玛拉顿能单刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '厄运之槌啊老兄，你最好把最好的装备穿上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '哈哈，我要是在厄运之槌迷路一次能得一块金币，早发了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '还有谁怀念这些新副本之前的日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '侏儒是最好的工程师，还有谁能把缩头做得这么完美？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '铁炉堡怎么这么吵，侏儒在这儿都歇不了会儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '在铁炉堡深处刷锻造材料，谢谢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '不知道祖尔法拉克会不会有变简单的一天。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '厄运之槌，我恨这地方，但掉落还行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '铁炉堡深处的材料我怎么刷都不腻，谢谢大家帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '50级了，黑石深渊真难受。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 3, 0, 0, 0, 0, 10, '我只是个有梦想的侏儒。还有谁能把自己脸缩成小号？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '还是不敢信这些鱼人不会游泳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆是个刷东西的好地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '哈哈，侏儒的笑话是啥来着？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '嘿各位，我去本区转转，马上回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '刷，刷，刷金币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '大家好！在这儿见到各位真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '谢谢给位置，没死我就回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '在去通灵学院的路上，得升升采药。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '呼噜噜噜噜……我到底图个啥……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '嗨各位，怎么样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '大家好，今天这延迟咋回事？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '真没想到我还在这些老地图里练级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '侏儒个子小，但聚会这事儿我们真懂，侏儒们。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '就没人替复活时间想想吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层掉率太烂了，真不敢信我啥都没出。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '嘿，还真有人玩法师不靠传送到处跑的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '又熔火之心，谁想去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '嚯，组个奥妮克希亚队真难。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '嘿各位，我第一次来祖尔格拉布，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层真好玩。才怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '这一天，真不敢信这回我又被抢了装备。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '通灵学院今天挤爆了，乱成一团。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙还是最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '大家好，怎么样，去黑翼之巢打猎吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '侏儒个子小，但诺莫瑞根是我们说了算！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '熔火之心求组，缺坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆永远是侏儒潜行的好去处。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '今晚黑石塔上层刷起来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '正在跑祖尔格拉布，求帮忙！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '谢谢各位带我，GG。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 7, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢永远是个挑战。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '嚯，今天网卡得要命，走路都费劲。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '奥格瑞玛永远这么热闹，就爱这乱糟糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '奥达曼求组，求个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '真不敢信我错过了摸那堆布。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '有人能治疗吗？开打前得有人给我们把血补满。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '巨魔是真爱我们的鼓和舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '这些怪的复活时间慢得离谱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '巨魔永远护着自己人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '谢谢拉我进公会，大家都好热情。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '哟，各位好啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '巨魔这玩意儿，受不了，又离不开。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '嗨！我5级，想学怎么弄金币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '各位冒险者，你们好！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '暴风城万岁，真的，我们的首都是最好的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '嘿，有人知道进死亡矿井有新路子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '你好啊，回到游戏里真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '我技能有点生疏了，刷到20级有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '真不好意思，我好久没玩了，谢谢你帮我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '你发现没，巨魔基本上就是最早的文艺青年？永远穿着最新款。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '死亡矿井招治疗，另外还招2个坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '我钓鱼有点生疏了，有人在藏宝海湾给我点建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '哈哈，在雨里跳了会儿舞，现在全身湿透。经典。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '有人多一瓶治疗药水吗？我这法师是新手。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '是我错觉吗，怎么每次回来奥格瑞玛都更疯了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '跟你说，人类是真的能扛，好在他们联盟也够硬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '我们巨魔做炖菜是真有一手，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '马上回来，得去影牙城堡把这个任务做完。幽灵们肯定会欢迎我的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '有猎人缺箭吗？我不想当那种猎人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '我爱死亡矿井这套新装备，几乎跟巨魔在丛林里用的一样好！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '有人能解释下奥格瑞玛的卫兵为啥这么不给力吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 1, 0, 0, 0, 0, 10, '还有谁受够了那些抢装备的？我发誓总有一天我要像个傻子一样 /dance。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '大家好，在这片见到这么多友善的面孔真好！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '我发誓这些怪的复活时间实在太长了，不过我们会熬过去的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '谢谢诺莫瑞根的建议，这趟顺多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '刚拿到坐骑，终于能跑快了，感觉真好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '谁能帮我打玛拉顿最后那个BOSS？公主简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '我们升级是慢，可我们是巨魔。清算终会到来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '从剃刀沼泽出了点好货，需要帮忙就尽管问。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '复活时间这么长，我们不如歇会儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '刚通了血色修道院，是挺难受，但很值。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '嚯，凄凉之地任务这么多。还能更荒凉点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '卡在监牢了，延迟要命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '怀念以前啊，那时候还能弄到鱼人宝宝。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根的掉落就是不对劲，也许只是我运气差？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '刚打赌输了30金。公会，谢谢你们啥也没干。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '咱能聊聊剃刀沼泽为啥永远打不完吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '猎人就是需求大户，老嚷嚷着要更强的装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '血色修道院就跟教堂似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '你缺监牢的装备。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '怀念以前的监牢，那时候还不至于一晃而过。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '剃刀高地任务一大堆，掉落一丁点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '我们是丛林之民，你们是……树之民？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '监牢有人要巨魔吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '哎哟，复活时间要了我的命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '这延迟把我丛林本能都弄丢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '这是我最爱的升级地图。我是巨魔，我天生就该在这儿！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '现在人开心了还会跳舞吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 1, 0, 0, 0, 0, 10, '你敢信联盟这套整个都是人类搞出来的，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '还有谁记得以前那会儿，跑完本就跟公会的人一起/dance，多好的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '我好想要我的坐骑啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '摸尸体可是门正经手艺，不是随便按个键');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽让我好怀念当年');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '我是巨魔战士，我就乐意待这儿，别的地方哪也不想去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 2, 0, 0, 0, 0, 10, '我一直在死，但值了，我喜欢这地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '有人知道玛拉顿该干啥吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '哈哈，我都忘了自己多恨黑石深渊的刷新');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '巨魔最牛！奥格瑞玛就算了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '奥达曼要帮忙吗？找队伍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的掉落就是垃圾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克简直是噩梦，小怪多得要死，忙得要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '奥达曼那些守卫到底干啥的，谁知道啊！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克其实挺好玩，只要你别死太多次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙永远一个样，无聊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '我就喜欢巨魔有自己的城，有个家真不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '谢谢邀请，没事，你们打得不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '奥达曼有人要组吗？我这儿还差几个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '嘿，对巨魔来说奥格瑞玛才是家哈哈，不过我想兽人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '今晚祖尔法拉克真难顶，还有谁在苦战？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '我一直挺想当个萨满的，大概吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '玛拉顿有啥技巧吗？我没打过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '人类骑士是最好的坦克，哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '怀念以前不用天天刷这些玩意的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '黑石深渊最近简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '还有谁碰上那种猎人啥都要的毛病？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '刚打完沉没的神庙，那儿的巨魔疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '厄运之槌有人组队吗？我在找队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '真希望巨魔能用上所有酷炫的巨魔装备，可惜不行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '有些人就是不懂 /dance 的精髓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '巨魔为啥过马路？因为要去奥格瑞玛哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '厄运之槌的刷新时间，就是我人生里回不来的五分钟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '刚在奥达曼升了级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '暴风城美是美，可进城的队怎么永远那么长？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '试过用法师坦玛拉顿，不推荐');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '有人把我的披风摸走了，不是被抢，就是运气差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '看见一个战士在黑石深渊杀完怪跳 /dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克又卡了，感觉我在用烤面包机玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '熔火之心对法师就是噩梦，我只想干掉拉格纳罗斯回家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '看见一个猎人在沉没的神庙想驯鳄鱼，祝他好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '巨魔为啥老要更多法力药水？因为咱法术有问题啊老兄');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克刷金不错，前提是你不介意等刷新');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 3, 0, 0, 0, 0, 10, '摸到人生第一把风暴贤者法杖，感觉真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '巨魔最酷，我才不在乎奥格瑞玛不是最美的城');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '你们玛拉顿要帮忙吗？也没那么难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布为啥不多掉点皮革，任务要用啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '还有谁在怀念那些老团本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '我在通灵学院老死，因为太黑了。多谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '天哪，我得搞清楚上黑石塔那个boss怎么过，有啥建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '奥格瑞玛万岁，就是别跟巨魔拼酒量');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '想再去趟斯坦索姆，还有几个任务没做完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '哈哈，酒吧里那侏儒还在要小费，真不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '今天熔火之心太狠了，全在岩浆里死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '上黑石塔，有一帮朋友就轻轻松松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, 'pvp有啥窍门吗，我得刷点好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '人类最会带联盟，谢了，把我们从兽人手里救出来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布找装备中，得找人帮忙杀哈卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, 'pvp队伍要法师吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '好，奥妮克希亚的队伍组好了，开搞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '奥格瑞玛的巨魔最牛，咱想干啥干啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '反过来说，祖尔格拉布我一次都没打完过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '熔火之心为啥要做这么热');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '巨魔是游戏里最好的种族，就算你不玩我们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '希望以后能多点巨魔的剧情');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '这奥妮克希亚团本就是场大型捉迷藏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 8, 0, 4, 0, 0, 0, 0, 10, '上黑石塔永远是个挑战');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '黑石深渊值不值得去？我就想弄点护甲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '嘿部落，我第一次在这片做任务，去下一个镇子怎么走最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '哈哈我又从鱼人那儿接任务了，看来得去水里扑腾');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '血精灵是真爱我们的传送门，谢谢捎我一程！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '还有谁怀念死亡矿井是新手首选副本那会儿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '太怀旧了，我差点忘了自己多喜欢哀嚎洞穴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷是个学做血精灵的好地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '这地方就是金矿，我发誓，东西就躺着等人捡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '这片区的各位好啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '嘿兄弟们怎么样，死亡矿井的小怪要不要帮忙清？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '我第一次接到在哀嚎洞穴干掉boss的任务，好激动');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '猎人为什么带个桶进团本？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '影牙城堡的摸尸体永远是个谜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '银月城是我们的城，我们为血精灵骄傲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '哈哈，猎人为了升级啥都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '大家小心兽人，他们的猎人从不脱靶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '我们不光有战士，还有世上最好的法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '血精灵就是：我得下线睡一觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '这个等级去哪刷皮最好，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷真是噩梦，不过谢谢邀请');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '死亡矿井挺简单的，只要专心打boss');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '我怀念当年就那样在银月城闲晃的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '马上回来，去厄运之槌刷点皮革');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '等哀嚎洞穴的队伍，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '我想打影牙城堡，有奶吗，马上回');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '怎么一个法师都没有，找点输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '我觉得血精灵的头发真好看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '希利苏斯升级我有点不知道干啥，有啥建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴能采药吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '出黑暗深渊带刷，3金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '监狱满队，马上回');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊求带走，拜托');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '记住，没人喜欢侏儒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 1, 0, 3, 0, 0, 0, 0, 10, '我发誓祖尔法拉克那些怪打人跟火车撞一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '来自幽暗城的问候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊快满，缺坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '出剃刀带刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '血色还差两个人');
