INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_race', 4, 10, 0, 2, 0, 0, 0, 0, 10, '哈哈，还记得我们以为血精灵很弱的时候吗');
