INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心这些刷怪真烦死了，太难受了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道哪儿弄厚皮不？我任务要用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想找人刷黑翼之巢的坐骑，有人不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '各位冒险者好啊，还有谁也超爱这游戏的剧情？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人能帮我找找上黑石塔的入口不？我转了好几小时了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '还在想办法弄到那龙喉兽皮，有人有窍门不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道奥妮克希亚巢穴的掉落值不值当不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '没人找我干活，正好有时间去肝法师的东西了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '1-20级怎么升最快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这儿还有谁也特别喜欢祖尔格拉布的背景音乐？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁有坦克去斯坦索姆？我得把这任务做完！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院这些任务咋能快点做完，有啥想法不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道除了在%zone杀鹰身人还有没有更好的刷皮法子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真不敢信我还在熔火之心刷那几件套装，太离谱了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道%zone哪儿能弄到厚皮不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想找人加我的团，缺坦克和治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这刷怪计时真要把我逼疯了，咋这么慢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道这附近采药的好地方不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '每组总有个抢装备的，是不是挺怪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '救命，任务卡住了不知道咋办');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人能给我做面秘银盾不？钱好说。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真怀念公会没那么硬核的时候，以前玩着更开心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁想打黑翼？我出输出，缺坦克和治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真不敢信这副本里一个猎人都没有，全是法师。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我需要个术士放恐惧，谁会这法术？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚七点奥妮克希亚巢穴招刷子，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这延迟把我整得跟勒罗伊·詹金斯一样乱蹦，咋老是卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道刷塞纳里奥议会声望的好地方不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人要法师过斯坦索姆不？没问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '卡的时候摸尸体一点都不爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '1-19级，有人知道制皮去哪儿练好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布那把噬魂者小刀给猎人太强了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我主玩术士，不过啥副本我都随时能上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '又有个菜鸟陷阱手抢我的怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢战场这波声望，轻松搞定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '%zone哪儿能刷黑铁矿石啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在凄凉之地打怪呢，有啥窍门不？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人愿意组队打黑翼之巢不，缺坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布给我来个灵魂绑定，太不爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '猎人是啥？就是啥都要的那种人');
