INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这等级刷钱跟上班一样哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院挺好玩的，第一次来？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哈哈真不敢信我还在玩，太谢谢帮忙的各位了');
