INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '上黑石塔太带劲了，好时光啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我得刷暗矛巨魔的声望');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 4, 0, 0, 0, 0, 10, '你好，咋样？想找个PvP搭子');
