INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴有人吗');
