INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人知道采矿怎么升快点吗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_question', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人知道猎人哪儿弄把好点的匕首吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今天刷新也太慢了吧，还有人卡这问题吗？');
