INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢大家的建议，我好像有点懂了');
