INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚拿到第一个坐骑，太爽了');
