INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，你们发现 %zone 刷新有多慢了吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在剃刀沼泽杀了一堆野猪人，啥都没有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '等等，得等这延迟缓一缓');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '各位冒险者好，今天谁来监狱走一趟？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '又一天，又要刷500只怪，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院的怪咋感觉5秒就刷一次？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '逆风小径的刷新时间咋这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '说真的，我宁愿刷副本也不想跑曼克里克老婆那破差事……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '各位冒险者好，我在黑暗深渊，谁来一起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '各位冒险者好，缺人一起去剃刀沼泽速刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '说真的，希望剃刀高地的任务别这么重复，都玩无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊刷新太久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢大家的治疗！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人能开个去剃刀高地的传送门吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '又一个猎人要抓宝宝了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱刷起来真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根就是个迷宫，谁设计的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人组个队打哀嚎洞穴吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '感觉自己3级跑去5级的地图了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院的怪打人跟卡车撞似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这儿有点卡，就我这样吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我发誓我一天得跑十趟剃刀沼泽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我觉得我键盘都比 %zone 的掉落新一点！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那些怪刷新咋这么慢？还得多刷点掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这地方阴森森的，我喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '去黑暗深渊最好走哪条路？我找不着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能解释下今天诺莫瑞根咋这么卡？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于30级了，该去刷剃刀沼泽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '为啥我要跑的时候怪打得更狠？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁怀念猎人得带俩宝宝的年代');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院的卫兵我是真受不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地咋不多掉点？我总觉得空手而归');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊刷新有啥窍门吗？感觉老打同一批怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽的怪咋老巡逻？太烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刷新要命，求点好打的怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '猎人永远缺陷阱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '跳个舞就能把延迟甩掉，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '想不死着打通血色修道院简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '尸体上啥都没有？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈怒焰裂谷队里4个战士就我一个法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那些巨兽我咋打都打不死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根就是噩梦，我连掉落都摸不着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根需要帮忙吗？谢谢所有攻略');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊一团糟，还没掉落，本来就难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '今天黑暗深渊刷新太离谱了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，在 %zone 见到你们真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有人在血色修道院卡吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根掉落干得离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢大家剃刀沼泽速刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真不敢信最近剃刀高地巡逻的怪这么多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '逆风小径那些任务有多阴间，咱能聊聊吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在 %zone 采了点材料，先下线一会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱里我还没掉过一件像样的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '没事，大家好运玩得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能帮我找到 %zone 的任务怪，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院轻松一趟，大家要buff吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家在 %zone 今晚玩得开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%zone 的刷新真要命，还有人这么觉得吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '怀念掉落不是秒到手的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢建议，我确实得快点升级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，我花30分钟找监狱入口');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这儿的猎人这么少，不奇怪吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地的野兽太狠了兄弟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '40级刚拿到坐骑，感觉真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '咋就不能有个好点的刷新机制？我在这儿待半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁卡在侏儒任务上？我挺喜欢的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '求组血色修道院，还缺2个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '最近还有人觉得黑暗深渊卡吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '猎人得吃饱才开心，我还得多请教');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇，有人像Leeroy那样直接冲了高地，结果还赢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '好难过现在全变简单了，我怀念那挑战');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '能跑 %zone 还要坐骑干嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴那刷新我是真受不了了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那怪的刷新怕是去抽烟了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '为啥我总摸到最烂的掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '求组血色修道院，非常感谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '就喜欢看这儿的鱼人互相啃');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那boss刷新等一辈子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊还是那么卡，GG');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱是我的快乐老家，就差2个任务了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这儿的鱼人真把我惹毛了，我得收拾收拾它们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '要杀的鱼人也太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '喜欢这地方，就是希望怪别刷这么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷谢谢大家帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚从剃刀沼泽回来，真不轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在掉落面前 /dance，有人抢了我的史诗锤');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那群狼的刷新时间太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道穿 %zone 的近路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '为啥我总觉得血色修道院得有更好的掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '怀念诺莫瑞根那种老派副本的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，剃刀高地那些蜘蛛的刷新时间就是个笑话');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能帮我做剃刀沼泽的任务？我卡住了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我发誓最近监狱里更卡了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '是我错觉吗，黑暗深渊的纳迦现在更凶了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今早哥布林咋这么卡，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我喜欢老副本的氛围，满满回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真不敢信打完那怪刷得那么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这任务的刷新时间咋非得这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这些野兽的刷新时间有点过分了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢诺莫瑞根那任务的提示，真帮上忙了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈这延迟比剃刀沼泽还糟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，希望大家都过得不错！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊的刷新时间长到离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望监狱的怪别刷这么快，那刷起来轻松点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刷新时间感觉比以前长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '正要去诺莫瑞根，还有人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '轻松，我终于拿到坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在剃刀高地摸尸体跟过圣诞似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在血色修道院升级有啥技巧？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，%zone 那边咋样了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大伙儿能不能一起感受下我们有多烦这延迟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '猎人就是猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '从这儿咋去诺莫瑞根？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '现在还有谁卡得厉害吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚死在监狱门口，又是。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我在影牙城堡咋老迷路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊的掉落不咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '等等，去血色修道院前得先做午饭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽刷起来难受，可那掉落得要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有人在 %zone 打怪费劲吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁要快速组队去黑暗深渊？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱是我最爱的练级地，就是怪太硬');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '为啥死了还得跑回副本门口？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这任务的刷新也太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嘿，25到39级哪儿练级好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根有人要治疗吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '做任务要帮忙就喊一声，没事儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴满满回忆，谢谢魔兽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院这掉落简直离谱，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地这掉落是挺简单的，但也没啥意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有人记得剃刀沼泽当年多恶心吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我还在刷血色修道院那掉落呢，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我去，剃刀高地这些野猪人真够烦的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望黑暗深渊别这么卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这地方的剧情我是真喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁在血色修道院被刷怪搞得头大？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那个任务谢了啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望掉落别这么磨叽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怪咋离任务点这么近？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '外面这儿气氛一直挺好的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '抱歉发牢骚了，实在是被监狱的刷怪烦到了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有人在剃刀沼泽为掉落发愁吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我可太喜欢逛这些老废墟了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '靠，我还得再去剃刀高地刷一会儿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '早啊各位，血色修道院组人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%zone的怪刷新计时也太蠢了，搞什么');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '多谢大家帮忙。没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁有黑暗深渊的地图？我去看看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '好家伙，血色修道院又来一遍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '就摸了几件灰装，我这运气，GG');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨！有人在诺莫瑞根吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我发誓这延迟一天比一天烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱刷怪也太慢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁做任务做累了想歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我小号的掉落永远比大号好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根那些侏儒怎么跑得这么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁去把曼克里克的媳妇叫来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁有多余的食物？我在刷金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '马上回来，这些怪的刷新计时快把我熬死了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，做任务才给100铜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井现在好空，求组队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我在%zone采药，你要的话拿点没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能帮忙捡下那卷轴？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '就差5块秘银锭了。哪儿矿点最好啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊没人，走起。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢邀请');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望能飞过来，哈哈。至少能上坐骑吧。任务太长了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，我觉得这儿的猎人得来个专属加强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我觉得这儿给的东西比所有团本加起来都好，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能解释下这儿为啥这么卡？什么都慢得要死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这怪很简单，放你的群攻就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怀念法师还很稀有的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哎，%zone刷怪怎么要这么久？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '马上回来，得去挖点矿练锻造');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，出门好运！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁有监狱的地图？我迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于拿到坐骑了，不用再跑了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院的掉落怎么这么烂？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，我老被剃刀沼泽那些野猪弄死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨，第一次来诺莫瑞根，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '没事，能帮上就好！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢建议，黑暗深渊进展不错！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人咋从来没任务找我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哎，有人要帮忙做任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '猎人永远什么都想要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能带我刷剃刀高地升级，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这儿有人怀念以前的刷新时间吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱今天卡成狗，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道咱们啥时候能拿坐骑吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根挺好玩的，就是那些虫子……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院不难，就是刷新时间太坑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道血色修道院的掉落怎么搞吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我掉率从来没出过问题，我就是需要它');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁知道去 %zone 的近路？这刷新时间要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '今天卡得不行，不知道为啥。%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道监狱怎么快速过吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '搞什么，怎么刷这么快，我都等半天了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还卡吗？我连怪都选不中');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这任务很简单，谁需要提示');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人要帮忙打血色修道院吗，所有近路我都记得');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我觉得升级升得该歇歇了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '你们哪儿来的时间升级啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我好像被人抢了装备，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能告诉我%zone那些大食人魔怎么过');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怀念以前跑图那么容易，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '看人家猎人跳舞，我也想跳');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇，%zone这些怪刷得比我妈做饭还快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这任务我爱了，剧情太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '拉一堆怪真是够了。得换个新宠物');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我就为金币和材料来的，没问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望能在打怪中途/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这任务简单到爆，我喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '掉落怎么还不来啊，简直在嘲讽我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '暴雪啊，刷新为啥要这么久？做任务做着做着就得等半天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '恭喜到20级。还能说啥呢。你很快就要坐骑了。最好的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡小心点，ADD一串太难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱感觉该好好打扫一下了。我都好久没来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽卡得厉害。这还不是难的部分');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '得有人把黑暗深渊的掉落加强一下。这没啥意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%zone的剧情我太喜欢了，真能把你带回去。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院我都刷第一百遍了。为啥还这么爽？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '想快点过诺莫瑞根？别打怪了，一直往前走就行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '能不能把剃刀高地怪的血量加强点，别这么简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我不确定剃刀高地野猪人的剧情是不是全真的。不过故事不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我觉得自己像复读机。不过这儿的掉落是真烂。别误会，游戏是好游戏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '太喜欢剃刀高地的野猪人了。它们被误解得太深，坏得又那么到位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井有时跟迷宫似的，记好自己走哪了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%zone的怪怎么刷这么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁在卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '是我错觉还是%zone猎人一堆，个个都要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能带我去血色修道院，我老迷路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我得刷金币，但完全不知道从哪下手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我是真不喜欢监狱，布局太烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在剃刀高地采药采几个小时都没人打扰');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我怀念以前剃刀沼泽没这么简单的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 2, 0, 0, 0, 0, 10, '俗话说装备是给输家的。哈哈。不过说真的，怎么才能搞到？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '建议：去黑石深渊带个朋友。我差点死了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢帮忙，我钓鱼终于升上去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有人就是喜欢哀嚎洞穴那氛围吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙那个新任务算声望吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊缺坦克的私我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿这个等级不是刷装备最好的地方之一吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我50级，想弄点装备去祖尔法拉克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '就单刷奥达曼玩玩。挺想那地方的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊刚去的时候特别容易迷路。跟紧点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能给我指下黑石塔下层怎么走？谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层卡得不行，为啥啊？？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁还要猎人啊，那种又要300个宠物的，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '行，沉没的神庙我帮你拉怪。没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢治疗，刚才真救了我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈。我怀念以前简单的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真希望怪多掉点金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，我刚跟鱼人跳了支舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '等复活呢。又来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁想一起去刷装备？缺几件史诗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone的刷新计时太离谱了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道这附近哪儿刷厚皮好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层刷装备太折磨了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克的怪对这个等级来说太硬了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓我见查克·诺里斯的脸比见我朋友还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '又卡爆了？这任务我都做不下去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '他们干嘛非得把飞行管理员挪走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙凭气氛还是我最喜欢的副本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁觉得往黑石深渊塞那么多稀有怪是好主意');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又是个复活刷怪的bug。哇哦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，厄运之槌怎么这么卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哇，这掉率。费这劲干嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哎，有人知道穿过%zone的近路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '是我错觉还是祖尔法拉克的怪现在特别慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我喜欢奥达曼，但哇，复活刷怪太烦了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙boss有啥技巧？他真够难的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有第一次来的吗？有点懵吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '50到59级去哪儿刷点好东西？玛拉顿？奥达曼？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真希望厄运之槌的掉落别这么看脸');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道%zone的复活时间现在怎么这么长吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层很棒，但我不喜欢它的寻路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '缺吃的猎人真是最烦的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone今天刷新太离谱了。怎么每次我赶时间就这样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我怀念以前卡顿还不算日常的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '掉落得加强了。感觉有点运气吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁还用找路啊？顺着尸体走就能找到怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '现在怎么又卡了？我只要我的金币！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真希望他们修修这刷新，玩着跟上班似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼让我既怀旧又打得难受。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我觉得厄运之槌才是真正的友谊考验，现实里倒算不上');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '不知道是我运气差，还是黑石深渊今天就是针对我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿刷金币挺好，但我怀念以前的玛拉顿。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙很有老派的感觉，就是难打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '在%zone小心点，刷怪太离谱了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克试着拉怪打。少犯点错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊注意卡顿，我得跳舞才不会死。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层，猎人什么都想要，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼刷新怎么要这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这游戏剧情太棒了，一切都值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，奥达曼的刷新计时比我耐心还长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙的怪慢多了。该给它们加点速度');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我觉得祖尔法拉克的掉落系统坏了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌的卡顿让我错过了跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '马上回来，打下一个boss前得去拿点吃的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哇，%zone的掉落根本不值得跑一趟，多谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，还有谁在%zone被刷新计时坑？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人玛拉顿缺人吗，不介意带个新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '马上回来，得去喂宠物，我猎人没子弹了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼现在卡成狗，能帮忙的话先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '马上回来，我得歇会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哎，我在祖尔法拉克挂机的时候被人抢了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '说真的，我怀念曼克里克的媳妇还算个难关的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '总之，想去%zone快点，就趁没人注意的时候/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哎，谁能帮我解玛拉顿的谜题？我一直死。gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真不敢信刷新怎么要这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '怎么感觉40级的不该这么硬啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，玛拉顿组队，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '天呐，黑石深渊卡爆了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '马上回，得传出去祖尔法拉克，怪太猛了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '各位冒险者好，早上好，享受卡顿吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我咋就死那了？？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '唉，沉没的神庙刷新慢死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，厄运之槌缺输出，打一会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊是挺狠的，但还行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哇，黑石深渊这儿的怪好简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '那个Leeroy Jenkins的梗真是绝了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '朋友们好，谢谢邀请去沉没的神庙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我该带个猎人的，缺输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '说真的，刷新时间怎么这么长？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '终于进玛拉顿了，走起走起走起');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '就在抢装备的人到掉落之前先干掉他们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刷新等一辈子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁受够奥达曼的卡了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '喜欢这地方的剧情。像走进历史一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这任务我得杀多少遍同一只怪啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚在黑石塔下层被抢装备了。太好了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，刚玩这游戏，目前很喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克的掉落很棒，但太危险了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '今晚在沉没的神庙跟几个幽灵跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone这些刷新怎么要这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '试着单刷黑石深渊，被打爆了但挺好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你说玛拉顿掉落烂，我有点懵');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%zone 的各位好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '猎人真的需要更多输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，玛拉顿感觉像个迷宫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢治疗，我新手，老忘记拾取规则');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我在祖尔法拉克怎么这么卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我最不需要的就是再来个盗贼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，祖尔法拉克缺坦克，今晚谁有空');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙今天那些陷阱把我坑惨了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真希望厄运之槌的掉落别这么随机');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能告诉我奥达曼怎么去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层的怪打得太疼了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡真麻烦，不过也值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴全是垃圾怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿真是满满的回忆，谢谢带跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人需要帮忙做配方吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刷金币没以前那么容易了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, 'Leeroy Jenkins今天运气都比我好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '糟了，又卡了。我连走路都不行，更别说跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿太挤了，这儿没掉落，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '在祖尔法拉克刷金币，有人要什么吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '马上回，这刷新计时比任务还长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嘿伙计们，有猎人需要帮忙弄宠物吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌东太疯狂了，掉落不够分的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '去死亡矿井肯定有近路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我就在沉没的神庙刷材料');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人想打黑石深渊吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我觉得我要哭了，我的装备被人抢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '很高兴又见到奥达曼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁在找玛拉顿的队？我需要帮忙打公主');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone的刷新感觉太～～慢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能告诉我上哪儿找那种什么都想要的猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的怪怎么这么快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家怎么都往黑石塔下层跑？那儿一个人都没有');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我得练采矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我觉得沉没的神庙刷新计时坏了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这游戏真该修修那些刷新时间了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone的刷新计时太离谱了，难受啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，卡得我都分不清自己在跳舞还是快死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '最近有人在厄运之槌刷到好东西吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为什么刷新的怪老是在你面前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊现在太疯狂了。到处是怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真不敢信我还在打，还没到60。哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼总能勾起回忆。不全是好的那种');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙现在掉落怎么样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '摸尸体手感真差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone的延迟怎么总是更糟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我怀念怪还难打的时候，被挑战的感觉真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '是我错觉还是玛拉顿最近掉落惨不忍睹');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克任务我需要帮忙。有人能来吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刷黑石塔下层好无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊怎么这么难刷到好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢邀请，%zone，希望能出好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哎，你们准备好了都该去厄运之槌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓玛拉顿今天卡得越来越离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '一路跳着舞去黑石塔下层');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙的掉落很烂，不过也凑合');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又在黑石深渊看见有人抢装备了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人要猎人去清沉没的神庙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '老玩家们，祖尔法拉克怎么快点过，有啥经验');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我记得当初打这个，啥都不懂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这游戏的任务设计还有改进空间');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，希望你们都过得不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我怀念以前在黑石深渊拉着怪自己加血的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真不敢信%zone的刷新时间还这么长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '说真的，当年我不需要团队buff就觉得自己很强，现在估计不一样了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌是挺折腾的，但掉落太值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴猎人单刷很简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼找个治疗，求靠谱点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又是黑石塔下层？谁来救命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '怎么人人都要猎人？咱们不需要更多宠物了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我怀念任务简简单单的日子，而不是这种剧情绕来绕去的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊一直更像死亡陷阱而不是副本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层一卡就更难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓，这刷新比野队拉怪还慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁怀念玛拉顿以前的简单？那时候没那么噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你以为什么都见过了，玛拉顿又给你来一下');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这刷新比%zone的坦克还慢，像泡在糖浆里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '不明白哀嚎洞穴咋还有bug');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢帮忙，哈哈，不知道我咋觉得这会是轻轻松松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊没完没了。我还能见到出口吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又在摸鱼人尸体。我怀念奥达曼掉落还看着有意思的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '抱歉，我这就来，就等这20%的触发');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我又看见个猎人什么都想要。又来了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克人一多就特别卡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌谁都没掉落，没事。我懂。我不意外');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔真是一趟长征');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又是黑石塔下层。把这个和沉没的神庙打完就去玛拉顿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，谢谢组队，%zone挺难的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还好掉了几件');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的刷新感觉好长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚打完玛拉顿最后一个boss，这掉落什么鬼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能带带新手打奥达曼？不知道我打得对不对');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道从祖尔法拉克到沉没的神庙的近路吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哎哟，厄运之槌太狠了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克这个蠢boss到底怎么打？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '是我错觉还是黑石塔下层卡得厉害？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '剧情党们：奥达曼的人怎么都这么暴躁，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嗨嗨，有人能给我点玛拉顿的速成建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙这任务链太折磨了，有人给点建议吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这延迟要我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家都说危险，但祖尔法拉克其实挺好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这游戏太怀旧了，我喜欢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼的刷新计时太扯了，感觉在原地打转。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁刚在%zone突然卡了一下？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '当你需要包多过需要血瓶，你就知道到后期了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊感觉就是个无尽黑暗的迷宫。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为什么我老是打完副本只拿到最少的掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙太棒了，我喜欢进本时的音乐');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓祖尔法拉克的怪越来越聪明了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你有没有发现这游戏在深夜更有生气？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '得赶紧去影牙城堡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层，我干嘛要这么折磨自己');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌是个好副本，但这地方真该立个路牌，说真的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '说真的，我喜欢剧情，但有时候我就想放空。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁在琢磨玛拉顿的最佳路线');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone的刷新怎么这么慢？？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道厄运之槌更好的刷怪路线吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓奥达曼的掉落随机有时候是被操控的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊今天卡得厉害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙的鱼人老是拉到仇恨，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿凭剧情还是最好的副本之一');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%zone 的攻略太谢谢了，我这水平啥帮助都缺');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%zone 的刷新时间咋这么长');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克卡成这样，我连自己角色都看不见了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还记得咱们第一次刷黑石塔下层吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '没人关心你奥达曼那套刷法');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁有多余的金币借我？拍卖行得补点货');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '鱼人怎么刷得这么慢啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊掉落出得那么晚，真烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我就喜欢黑石塔下层那种又黑又阴森的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆现在刷怪快得离谱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我跟你说，这儿的怪比查克·诺里斯还烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道怎么最快去%zone吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈我老被同一只怪打死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院刷新时间疯了吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '得走了，采矿还得练练。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '还有谁烦团本里卡？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哈哈，摸完装备别忘了跳个舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家好啊，今天团本祝你们好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '又是斯坦索姆？就不能刷快点吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚刷黑石塔上层吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚熔火之心有点卡啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布全靠腿跑，真遭罪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '好怀念那会儿随便打的团本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井人太多了，谁去把门口清一下？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院啥都不掉，太难受了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚的吐息还是那么要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人打黑翼之巢吗？希望今晚装备好点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢大家，这趟打得真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '那个本你们带得真好，最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '过%zone有点吃力，求帮帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '%zone的掉落刷新有啥窍门吗？等半天了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今天这卡顿要命，我啥招都试了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有猎人吗？别光/dance了，先把那玩意儿打死啊哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁能告诉我回通灵学院门口最快怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '得再搞点背包，包早就满得不行了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想把木喉声望刷上去，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '记住啊，别站火里。除非你就想在那儿/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层捡东西值不值啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢大家教我奥妮克希亚怎么拿装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家注意，背包留点地方装装备啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在纠结要不要排黑翼之巢，你们觉得呢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆今天刷新快得离谱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '怀念以前光刷皮就能轻松赚钱的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院越刷越无聊，真希望能出个新60本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层现在卡得跟屎一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '等等，血先加满，我蓝跟不上了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '横穿%zone怎么要走这么久？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '曼克里克的妻子估计比咱们谁都幸福');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刷这么多次以后，熔火之心都没难度了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚还是最帅的战斗吧？不管打多少遍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刷一遍黑翼之巢能赚不少金币吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布就是个大型刷子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '老是捡那几样东西，腻了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆怎么走来着？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '%zone里那些僵尸怎么刷这么快？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑上卡疯了，还有别人这样吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '现在掉落真轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '还是怀念以前在黑石塔的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '还有谁喜欢奥妮克希亚背后的故事？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心得把刷新时间加长点。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布就是一窝虫子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道去黑翼之巢的好路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真希望掉落能多点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石刷得太快了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我就喜欢熔火之心那氛围');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布还得靠法师冰东西啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院那路我还是没搞清楚');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '为啥卡，为啥偏偏是这 %zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '太谢谢那一口没必要的奶了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢可不会自己打完。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '又是熔火之心？真的？行吧谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '麻烦谁按时把大家的buff补上啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '卡得厉害，希望我没拉到仇恨。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '开怪前别忘了上buff');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这些小怪的刷新时间让我想直接/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在奥妮克希亚那儿拉太多怪了，哎。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '抱歉谢谢你，拉错怪的是我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院今天刷新快得离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今天哀嚎洞穴真难受');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '是卡还是我幻觉啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人有刷布快点的心得吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哈哈刚在熔火之心被抢了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道去黑翼之巢的近路吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在挖铜矿呢，谁要点啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚奥妮克希亚的掉落怎么这么差');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布这刷新真顶不住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刚凑齐一套锻造护甲，爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有猎人想找斯坦索姆的队伍吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '%zone刷新太久了，求修一下');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怀念影牙城堡还有难度的时候');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今天这卡到底是啥毛病');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '恭喜拿装备，谢谢组我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '还有谁又被门卡住了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哎有人知道去祖尔格拉布最近的路吗？谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哎，装备已经进包了，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哈哈打奥妮克希亚我感觉自己完全没用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '看来想过黑翼之巢我得再堆点伤害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '%zone刷新等死人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哎，拿到新坐骑之后该干嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人来帮打下通灵学院boss吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这刷新比晚上的迅猛龙还难缠');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今天怎么卡顿这么厉害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这地方真美，氛围我太喜欢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆其实没那么难，就是得队伍合适');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刚拿到第一只史诗坐骑，有点自豪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这就是那个啥都要的猎人吧哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布是难熬，不过掉落值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢帮忙，熔火之心总算过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心不算最糟，开怪注意点就行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '现在这些任务怎么刷声望啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层是狠，不过习惯就好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刷新一等老半天，怒焰裂谷就没意思了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '感觉自己像个得喂全团的猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '天啊斯坦索姆刷新怎么这么久');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想在黑上门口/dance，结果惨败哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚那儿的怪怎么这么烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁能帮我干掉那个李洛伊·詹金斯啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '%zone里刷声望最好怎么做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刚打完熔火之心，一件都没掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道斯坦索姆好走的路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '猎人又是啥都要，老样子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '去黑上这一路太费劲了，求帮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道这些团本掉好东西吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙真好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家好，去%zone最好怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今天黑石塔上层卡得我不行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢大家组我打团，咱们干起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '通灵学院刷新还是坏的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '卧槽，又是黑翼之巢？真的假的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在去黑石塔的路上，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆没了那点剧情，感觉空荡荡的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布求帮忙，找个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, 'gg，这团挺难的，不过打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心这刷新时间要了我的命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '兄弟，这刷怪非把我熬死不可');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚把靴子捡到了，gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真希望怪能掉点像样的东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢祖尔格拉布那会儿的奶，咱们打得不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑上缺坦克，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑上三号boss注意脚下，多谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人打奥妮克希亚吗？想弄那只史诗坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢里打龙之前别忘了救圣骑士哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '得刷瑟银兄弟会声望，怎么刷最快啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想办法快点到黑翼之巢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心太简单了，大家得多打奥妮克希亚练练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁告诉我 %zone 练级最佳路线，1到5级磨太久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '副本再难也没今天这卡难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚这团缺猎人，没你们太难了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢分装备，我在%zone摸到个好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道怎么在山里刷金币吗？我附魔还得练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刷了一个小时，就见着五只怪，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层今天刷新太糟了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢建议，我正想把钓鱼练满');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真的，今天卡得离谱，我连/dance都跳不利索');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆潜行进去其实还行，你信我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '一个任务干嘛要横穿大半个%zone啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这里刷新等太久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这周黑翼之巢太狠了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '能帮我看看制皮吗？图纸怎么都不掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我跟你说，这世界的猎人啥都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆这刷新快把我逼疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚熔火之心怎么这么卡？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在黑石塔刷黑铁矿呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真的，今天这掉落系统跟我有仇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '对低级职业来说，黑上真是长征');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '还记得奥妮克希亚刚出那会儿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁能帮我去黑翼看看？');
