INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '嗨%zone，我刚回来，有人想干点啥吗？');
