INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '嗨，有人想打打pvp吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家好，%zone的各位今天过得开心啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '破卡顿，捡个东西都延迟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这周第五次刷斯坦索姆了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刷了一整天材料，真是爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '怪怎么刷得这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家好，狩猎顺利啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '又是哀嚎洞穴？谢了免了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '得刷点赞达拉部族声望');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '卧槽，这么多猎人都要奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚通灵学院太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家都好佛系，我太喜欢%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心怎么每次都像最漫长的团');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '大家好，欢迎来到%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦索姆的剧情还是最棒的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有输出想打奥妮克希亚的吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道去通灵学院最好的路线吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有奶妈给点熔火之心的心得吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还记得以前任务有点难度的时候吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层真是路太远了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人找黑翼之巢的队伍吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢哥几个复活我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想找个队伍刷斯坦索姆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁能给新人讲讲捡装备的规矩啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '真的，这团本肯定不是查克·诺里斯做的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '斯坦还是bug一堆，这本都打不完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁能教教我通灵学院怎么拉怪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '想刷%zone，可刷新太慢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石卡得厉害，没法打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '为啥非得一遍遍打同样的怪？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '奥妮克希亚的入口怎么走？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '找黑翼的队伍，缺个好奶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道通灵学院入口在哪吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心是磨人，可为了装备值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '这些怪干嘛要这么多条命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢是紧张，不过我们一次就过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑翼之巢的入口怎么到啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '有人知道%zone采药最好的路线吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谁要帮忙打通灵学院，跟我说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '刚打完熔火之心团本，装备到手了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人缺治疗药水，谁有多余的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '挖矿太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '在这儿刷剥皮呢，位置不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '我觉得这趟奥妮克希亚该放弃了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今天通灵学院真烦，刷新还慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '剧情时间，聊聊提里奥吧，还有围攻之后他干了啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '熔火之心总是乱七八糟，我都不知道卡从哪来的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '哈哈黑翼之巢就是一场硬仗，捡完装备就跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔太无聊了，有时候我就去斯坦玩玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '谢谢欢迎，新来的，我特别喜欢剧情');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '黑石塔上层的怪怎么刷得这么慢？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '嗯，有人没等奶妈就直接李洛伊式冲进洞里了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '差10点才到19，真不敢相信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '祖尔格拉布捡东西就是噩梦，我就想拿完走人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '今晚有人有空打奥妮克希亚吗？先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 4, 0, 0, 0, 0, 10, '就希望这卡顿能停，游戏其实特好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡的掉落太不稳定了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我得练锻造');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚被抢了掉落，真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人要100%的掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这掉落系统比不会瞄准的猎人还烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人永远缺弹药');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有这刷新，升级太慢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '抱歉，我挂机一会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井不算难，可这延迟太要命了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人在 %zone 刷怪有啥技巧吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '卡得我只想像法师一样 /dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '去 %zone 真得打这么多怪吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井入口我到底咋找');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '没掉落？看来是我走运了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '看来那任务还得再做一遍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嗯，这剧情真让这地方活了起来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '卡了抱歉，我还在摸这地图');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，新人一个，死亡矿井有啥技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_gripe', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%zone 的刷新时间要命啊……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怎么没人帮忙做任务啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这儿是学剥皮的地方吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '从这儿怎么去奥格瑞玛？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真不敢相信我在死亡矿井还会迷路。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我说真的，新玩家一天比一天厉害。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这次练级感觉比哪次都慢，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁要治疗？我有/dance绝活。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人这数量也太离谱了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '边刷边笑，还有谁？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡我还是玩不够');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这游戏我好久没这么放松过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这游戏太难了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人知道%zone哪儿刷吗？缺布');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有猎人和盗贼，谁还稀罕潜行啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我喜欢挖矿，但不喜欢跑回去存矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我怎么老被蜘蛛打？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，又是影牙城堡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '太谢谢组我了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井跟噩梦一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这就是我一直不喜欢法师的原因');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴太简单了，随便打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我真得把剥皮练上去了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这怪早该死了，昨天就该死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '都没发现艾尔文森林野猪这么多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '小白问题：在贫瘠之地刷%level是不是更轻松？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井最烂，刷怪简直要命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡缺个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '又卡了？大哥别啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '捡到把双手剑，轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚挖矿赚了50铜，感觉暴富了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '曼克里克的老婆为啥走了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，现在死亡矿井掉落咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢13级刷皮的建议');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '打得好各位，这趟哀嚎洞穴真刺激');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在影牙城堡集合，感觉等了半天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嘿，有人知道采矿怎么练最快吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁有多余的制皮图纸吗，啥都行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还记得第一次到%level吗，感觉自己贼牛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '马上回来，去捡个尸体');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在%zone刷金，怎么地上没见着金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '要人帮忙就喊我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于10级了，总算能穿件像样的衣服。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人记得任务说明以前好读过吗？不记得。我也不记得。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '又是怒焰裂谷？我一点都不意外。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '术士太强了，没宝宝我感觉跟没穿衣服一样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我9级卡在一只蜘蛛上了，救命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '为啥死亡矿井里卡得最厉害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡简直是艾泽拉斯最吓人的地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真怀念光刷怪就能玩得开心的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井有那些大块头就一直很折腾。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我服了，9级卡在一只猫头鹰上，猫头鹰都该去死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怎么大家都讨厌猎人？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴是练潜行最好的地方，别告诉我输出队友。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '想找个副本队等得花都谢了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嘿各位，有猎人缺宝宝吗？我这多得是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刷怪模式已开启，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%level的我被一只蜘蛛打死了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡有个法师任务，求帮忙，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '恭喜抓到那宝宝，跟驯服了个小龙卷风似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁有鱼竿？我想练钓鱼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我还记得%level那会儿多难，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '抢我怪的那个猎人真让人火大，菜鸟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今天得搞到100金，谁来一起刷？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢加血，我以为我要没了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '找哀嚎洞穴队伍，%zone，%level');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这刷新时间真让人受不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今天怎么卡成这样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井总是挤满猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真怀念副本还不秒锁的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '能不能给法师一点爱啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人看到怒焰裂谷的任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有时候我觉得我宝宝比我还需要练');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '最后那个箱子里的东西我拿到了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我哭得停不下来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，我刚到%zone，新手有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴对%level来说是个不错的刷怪点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡的刷新时间怪得很，我在那儿卡住多少次都数不清了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，很高兴认识你们！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '求帮忙，影牙城堡简直是噩梦！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有法师能给我开个去暴风城的门吗，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人去%zone吗？求组哀嚎洞穴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '现在卡得我想骂人，我这猎人也得歇歇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，曼克里克的老婆！每次都骗到我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刷新时间还是有bug');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '再杀一只怪就能交任务了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡真够磨的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这些怪怎么要打三下才死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这就是我讨厌怒焰的原因');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈你还是个猎人，永远都需要那件装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真怀念一小时打完哀嚎洞穴的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '你能行的，就一直死呗，挺好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '找死亡矿井队伍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '最烦死之前画面卡住');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这游戏烂就烂在这儿，真是谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怪不得我得升级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢昨晚在死亡矿井帮我的各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '升到2级这路也太长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴缺人，有想来的吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '又卡了，动都动不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真怀念刚玩时坐骑那么好弄');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁想在%zone放这么多%level的怪啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我发誓，再让我杀一头野猪我就……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '知道我怀念啥吗？能一路直冲哀嚎洞穴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '采矿刚升二级，现在得要把镐才能挖');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '找影牙城堡入口又迷路了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊就是一堆泡泡和鱼人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢邀请我打监狱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁把猎人放进厨房的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院晚上太吓人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根的彩蛋还是最棒的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '侏儒工程学见鬼去吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁怀念诺莫瑞根的好日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嗯……我估计找不到回城的路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哪儿刷铜矿最好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚被一个法师抢了装备。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽就是个大地迷宫。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '曼克里克的老婆问你好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '侏儒科技真让人难以置信。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我来就为坐骑和怀旧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚拿到坐骑！终于能快点逛%zone了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%level在哪儿刷皮？我装备得升级了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽是折腾，但掉落值得');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在血色修道院看见一个猎人，宝宝全带齐了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我就爱看侏儒在诺莫瑞根里跟嗑了药似的乱窜');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我血怎么掉这么快');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嘿各位，我卡在监狱里不知道往哪走了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚接了个新任务，%zone总算有点意思了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '祝你们副本顺利，希望出点好掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈刚看到那个坦克，拉怪拉得那么兴奋，李罗伊附体');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢各位帮忙，真的很感谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人在血色修道院治疗方面给点建议吗？啥都听');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱里的迪菲亚也太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈咱们干嘛还费劲做那任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道我猎人宝宝为啥出bug吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我得喘口气，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还记得咱们没这些花里胡哨坐骑的时候吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '为了块布还得跑回去，烦死了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁来帮我做这个剃刀高地的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢刚才那波加血，你救了我一命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '找监狱队伍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽现在有bug，注意仇恨问题');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁怀念%zone以前那些老派任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根求帮忙，有人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '猎人总得带宝宝，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '现在血色修道院真烦人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '马上回来，得刷点布做裁缝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡有啥技巧吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊小心有人抢装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '赢了别忘了跳个舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '想刷金，结果一直卡在战斗里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '能采药就赶紧采点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '李罗伊来干都比我强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于有60%坐骑速度了，天高任鸟飞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道%zone附近哪儿还有铜矿吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁被刷新时间卡着');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '新剥皮手套真香');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人组黑暗深渊吗，缺坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴看着也太吓人了吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这么卡，监狱简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁锻造任务要帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色刚出了个不错的掉落，没得说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '求组诺莫瑞根，有人知道哪个入口最好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '铜矿脉也太多了，胳膊都挖废了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地太黑了，谁带个火把');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, 'NPC怎么老刷在我看不见的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽有猎人加几个陷阱很好打，可带个战士？根本不可能');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊跟地狱来的副本一样，全是水，真是谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '又是诺莫瑞根？我得歇会儿了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我一点铜矿都找不到');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '现在又去打监狱？我拉杆拉得手都酸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院？不如叫血色受罪，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我怎么老在剃刀高地死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我快要去杀个豺狼人抢它裤子了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能提醒我咱们为啥来这儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我爱这游戏，但讨厌打蜘蛛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚单刷了血色，感觉自己无敌了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望能在战斗外跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这游戏全是回忆……还有豺狼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '做任务就该派猎人去');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '不过挖矿真的很解压');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '天，监狱也太长了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地熟悉路线就很轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望我多20银');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我还在琢磨诺莫瑞根，挺磨人的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我想去跟科多兽/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '找几个人打剃刀沼泽，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚拿到坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真想去搞点黑暗深渊的装备，太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '怎么我每次看到猎人都在要吃的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人想组队去死亡矿井吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我卡在%zone36级了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈我刚看见一个猎人想喂地精');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱就是烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根感觉是最长的一次刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚打完一趟黑暗深渊，我还是39级，真不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嘿各位，%zone有啥新鲜事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚升到%level，不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还在等那件史诗掉落');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈我又被狼群追了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊拉怪缺个法师');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这么多铜矿我该拿它干嘛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我就喜欢这儿的法师啥都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈刚看见一个猎人掉下悬崖');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我就在监狱刷点金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀那边还有点活没干完');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '去血色修道院的各位好运');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '天啊，又是个蹲刷新点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这就是我怀念从前的理由');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色又平常的一天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有人记得咱们一口气打通剃刀高地的日子吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '掉落总是那么稀');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人能帮我做任务吗，要杀10只鱼人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我就爱这地方的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '啥都要的猎人最讨厌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这练级没完没了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '感觉这些任务我做了几辈子了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道怎么最快从黑暗深渊出来吗？这猎人太需要照顾了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这些怪的刷新时间比以前更糟了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱现在算我第二个家了，就是那么……监狱味儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在诺莫瑞根待了一小时，就捡了点破烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我说真的，这儿的掉落比找我最爱的宝宝还难');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '又在剃刀沼泽受气，真恨不得马上拿到坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '老被这些狼仇恨，烦死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁觉得怒焰太简单了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人能帮忙打下监狱吗，里面跟迷宫似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真怀念以前啊，那会儿我也能像这游戏里其他人一样跳个舞把烦心事都甩掉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院也太简单了吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '卧槽，剃刀高地的卡顿跟猎人啥都想要一样猛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这地方我真待够了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我觉得血色修道院该多来点跳舞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嘿兄弟们，知道吗，监狱是小号升级最爽的本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '打剃刀沼泽真让我想赶紧有坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '20到30级升级的话，一定要去黑暗深渊，怪正好合适');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '天啊，又是血色修道院。我感觉我一直在跟复活计时器打架');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在%zone刷布，谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '知道我比卡顿更烦啥吗？跑黑暗深渊。太太太远了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '想要轻松拿装备就去诺莫瑞根，那本根本没人打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱本来挺轻松，直到要打那个典狱官');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真希望我能不死一次打完血色修道院的掉落，就一次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这复活时间到底什么毛病啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '记住啊，利若伊·詹金斯可看不上你们这么抱怨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我还得多刷点金币，多谢啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁在%zone刷怪啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嘿哈哈，有人知道制皮图纸去哪弄吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '格罗玛什去他的吧，我今天死得也太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在暴风城有猎人想找人一起做任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院求带，太难了哈哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我马上就能拿坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '今晚监狱简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家能不能统一一下，诺莫瑞根就是个坑？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '第100次打剃刀高地了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我真不懂别人怎么把这些怪杀那么快的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我开始觉得这游戏有黑幕了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁记得以前一只怪就能秒你的日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人有空一起打本吗，我升级挺快，就是缺个伴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我在黑暗深渊死的次数我自己都不信。谢谢复活计时器啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真怀念啥也不管到处乱逛的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚发现我一直没机会读完诺莫瑞根那本古书');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这不就是%zone嘛。我的任务怎么跑到沙漠中间去了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '说真的，血色里捡个东西咋要五分钟。你们为啥要这么对我们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '一复活再捡东西就难了。笑死，你家猎人的宝宝直接溜达着把掉落拿走了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真怀念以前捡装备全靠猜的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真不敢信我又错过捡装备了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱挺简单的，可是哇，看到那么多掉落真没法拒绝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能教教我在监狱怎么不卡。这任务到底有啥意义');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我喜欢这儿的剧情。可惜一切都过得太快。这地方值得停下来慢慢品');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，看到这么多人真开心！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这个制皮图纸还得再攒点金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地%level单刷感觉有点太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊真是个让人怀念的本');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道血色修道院有啥好的组队任务吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽打得我想退游，还好它够简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，我刚在黑暗深渊连死三次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁跟我一样爱艾泽拉斯的剧情？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我根本停不下探索，能做的事太多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢大家在诺莫瑞根帮我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有了新坐骑，这地方好玩太多了，我爱死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有队伍缺人打监狱吗？没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '看来只能跳舞跳到20级了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱刚开始是挺难的，你慢慢就懂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能给黑暗深渊找个坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色里的陷阱小心点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我今天在监狱死了好多回哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色尽量找个好队，快得多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我得赶紧弄个坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我还在往%level冲呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢上次在血色帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '希望新任务快点出来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '等我一下哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '活在当下，这就是我的座右铭');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱缺个治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在诺莫瑞根当坦克简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '试试%zone的新任务，特别棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院缺人啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽现在好无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '别忘了拿血色钥匙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道好的升级路线吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这些本的掉落真是烂');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇，今天黑暗深渊人爆满');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚学会骑术');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '得缓口气才能打完影牙城堡');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地好空啊，终于清静了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真怀念诺莫瑞根还是终极内容的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱太让人怀念了，老派的极致');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '今天黑暗深渊bug好多，还有别人也出问题吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我要去血色修道院，有人要治疗吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '30级啦！离坐骑又近一步');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '打完架就来个/dance，那你就是真魔兽玩家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院求带，求组队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人知道%zone附近哪儿还有铁矿脉吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真怀念曼克里克的老婆那种老世界任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在%zone刷金币，累是累，但值了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能接下监狱这个组队任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还在等我的坐骑呢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '多谢你们的草药啊兄弟们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我这战士咋这么吃耐力');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我在剃刀高地花的金币多到不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人有炼金配方吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '打得漂亮，我们血色修道院刷得挺爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真想一整天都刷黑暗深渊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱清本中，缺治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有猎人了还要啥潜行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '周日还去死亡矿井？看来这就是我的人生了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊求组');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我都不知道这是怀旧还是纯惨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁想打剃刀沼泽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '又是一天，又一趟%zone');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁跟我一起去血色修道院');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁觉得%zone的复活速度有点离谱？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱凑人简直是噩梦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这卡顿让我连攻击都打空哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地也太好玩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '再升一级就能拿坐骑了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我刚拿到第一只坐骑，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还记得这地方以前空荡荡的吗？现在我连捡个尸体都难。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根让我想起我为啥爱这游戏');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院的氛围永远那么燃');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我发誓掉落随机数恨我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '打剃刀沼泽让我怀念从前');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁想要更快的坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '不敢信我又被一只小怪打死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 2, 0, 0, 0, 0, 10, '侏儒的剧情最棒了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有人记得任务真有难度的那段好日子吗？哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，我就在这儿升会儿级，一会儿得走');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊永远那么折磨，但最后值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷总是空的，哈哈，我也没啥好抱怨的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '僵尸巨魔还是最烦的哈哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人能帮我打祖尔法拉克吗？第一次来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '附近有猎人吗？有几个精英怪想请帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这世界是挺残酷，但这才是经典味');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌就是一团乱，别误会我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人多带瓶药吗，今天全靠刷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这游戏的剧情真是绝了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真怀念以前本不能秒进的日子');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁爱沉没的神庙？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼总是很有意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '进了影牙城堡才知道，我居然还能怀念这地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这地方太棒了，玛拉顿，别忘了我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '兄弟，这游戏的音乐太完美了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '钓鱼竿又卡石头里了，又一次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道%zone的复活计时修好了没');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥我一进黑石深渊坐骑就消失');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克求组，来个坦克谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '在荆棘谷刷皮，救命');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈刚在祖尔法拉克一只舞跳完三只雏龙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁也在攒坐骑速度');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这趟玛拉顿打完我感觉我少了一半脑细胞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在银松森林采药，跟从前一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '要个会潜行会陷阱的猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌还是最容易迷路的地方，永远都是');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '呼……今天刚打完我第500趟祖尔法拉克，得睡了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿也太疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌该改名叫厄运无聊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '太感谢了，奥达曼拿到我+10敏捷');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '困……黑石深渊能不能快点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真希望我赶上游戏刚开那几天，现在都这么有魔力');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我还得赚更多金币来升采矿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你知道的，服务器一挂我准在');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真怀念自己能单刷副本还很有用的日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层现在太危险了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我来就为刷金币和装备，主要还是金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我本来想在厄运之槌弄件好传说装备，可太难了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼缺输出吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这个等级打玛拉顿简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哪儿能找到靠谱坦克打沉没的神庙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊清小怪，随时来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '德鲁伊永远是最好的治疗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁在找队去奥达曼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '想第一次去试试黑石塔下层');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '不知道我当年那个CD key还在不在。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥大家都讨厌黑石塔下层的蜘蛛');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢在黑石深渊的帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克咱们这输出配置怎么样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，有人找玛拉顿的队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢拉我进黑石深渊，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人想打祖尔法拉克吗？哈哈，一个人可搞不定');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人多带治疗药水吗？%zone要用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '不敢信我在厄运之槌把蓝打空了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真希望他们把这地方的卡顿修了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嘿大家好，还有谁记得魔兽的老日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁来夸我一句干得不错，我好接着干。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这任务%level就掉了，真不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这游戏真该多给猎人点加强，他们啥都缺');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '旅者们好，还有谁有多余的坐骑吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿谁缺好治疗？先谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真怀念升级就是在%zone刷怪的日子哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚到%level。有人要帮忙打奥达曼吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈这坦克在祖尔法拉克里一直绕圈跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我老忘厄运之槌里陷阱有多少');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人找沉没的神庙队吗？跟我说一声');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '拉怪还得带着一身buff，真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我现在是属性最好的猎人，偏偏基本用不上。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嘿，有人要黑石深渊的跑法技巧吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚在玛拉顿团灭了，五分钟后回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿缺坦克，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '太喜欢了，%zone里啥都恨我们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '卡在奥达曼boss这二十分钟了，没事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁怀念老魔兽那种简单');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊清本中');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '在黑石塔下层，又迷路了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊的boss太简单了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁记得利若伊·詹金斯');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，看到这么多人真高兴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌就是噩梦，马上回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙刷得真累');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '睡了仨小时还要啥buff');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '想打黑石深渊但得凑五个人，缺输出');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥总觉得复活时间长得没边哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又卡住了，我感觉自己在泥里跑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '早啊冒险者们！大家今天咋样？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁觉得自己老是错过掉落？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁觉得自己猎人啥都想要？没错，我啥都想要！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚在背包里翻到些旧剧情笔记，怀旧感一下子上来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚升到%level，感觉太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚在祖尔法拉克被人抢了装备，真行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从黑石深渊摸到张20金的卷轴');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁爱在%level的祖尔法拉克拉五十只怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿缺坦克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人能帮我刷黑石塔刷皮吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我感觉自己就是个啥都要的猎人，连没人要的都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我咋老在奥达曼死。连墙都恨我似的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙里治疗最好的装备是啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我爱在祖尔法拉克刷，怪都不打我');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我最爱猎人从来不用问问题，永远不用');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '不知道怒焰裂谷那个任务值不值得做');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人能陪我在怒焰裂谷练剥皮吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你有玛拉顿地图的链接吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼的任务还行，可为啥让人跑那么多路');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '升到%level感觉咋样');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢大家这趟玛拉顿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙又是这些破怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层去死吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼比黑石深渊强');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁还差人打祖尔法拉克');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，还得找吃的的猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁有多余的钥匙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '呃，死亡矿井里怎么什么都这么慢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道黑石塔怎么单刷吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚连刷了十趟黑石深渊哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '困死了，太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哇，这些法师还是一口气全拉，真行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层真是纯刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真怀念玛拉顿还没这么挤的日子，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人想来趟奥达曼快速刷吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这些怪真是恨死我这张脸了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '今天厄运之槌看着挺空的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '队伍对了，祖尔法拉克永远好玩，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢在哀嚎洞穴帮我的各位，玩得挺开心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '兄弟，这些战士一杀完就爱/dance，轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '来一趟玛拉顿这种老本，永远不会错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥黑石深渊这么难凑队？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嗨，我被拉去祖尔法拉克了，有人知道该期待啥吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层清本，缺输出，谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿是挺烂，但掉落值得');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼求组，人已经凑齐了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有猎人找沉没的神庙队吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能帮我搞定奥达曼的任务发放人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '咋回事啊，我这坦克就是死个不停');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚在影牙城堡被人抢了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这个月我还能刷几次玛拉顿？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，欢迎来%zone，需要帮忙就说。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能解释下我咋在祖尔法拉克被一只萨特秒了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石要治疗的话，还缺一个');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '早啊各位！还有谁想去趟奥达曼？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈刚在沉没的神庙被个盗贼抢了装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁在黑石塔下层被那些侏儒坑了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '慢的话抱歉，厄运之槌卡得厉害');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊里咋全在吼？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '就想打通玛拉顿，有啥建议吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嗨，我是新来的，这附近哪儿能弄到坐骑？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '周末快乐各位，今天在%zone好好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，谁能告诉我怎么找最好的刷怪点？我是新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '兄弟这复活时间也太久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥我在黑石深渊总拿最烂的装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又在玛拉顿死了，我太恨这boss了……不过还挺好笑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人找队打祖尔法拉克吗？我升完级就回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，沉没的神庙boss求帮忙，来个人谢谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥卡顿总在奥达曼出现？对大家都不公平');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人组队去玛拉顿吗？我吃口东西就回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，我这猎人要吃的比侏儒要金币还多');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哇，%zone的怪比我想的硬多了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你知道人家怎么说，拿不准就潜行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊配不上它这名字');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '全程跑玛拉顿一点都不好玩');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人看见曼克里克的老婆了吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌最烂了，我们咋还老去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '困……');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '为啥任务老让我去祖尔法拉克？？我知道了啦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '学跳舞三秒钟，忘了它得三小时');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼就像迷宫里的迷宫');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙也没那么沉了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '啊不，又是曼克里克的老婆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '施法得要50%的蓝');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嘿大家，有人找玛拉顿的队吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这地方精英怪扎堆，多谢了啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔下层到底怎么去啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嗨各位，黑石深渊最好的打法是什么？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你知道人家怎么说，打不过就加入呗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '40级了还在琢磨我到底在干啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这些老地方怀旧感满满，还有谁有同感？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人想来趟祖尔法拉克吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '老伙计厄运之槌，永远不腻，对吧？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家都回这儿来了，真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克求组，有人吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这些任务勾起来太多回忆了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '待会儿想组个队打玛拉顿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙对我来说太危险了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我居然真在黑石塔下层迷路了，不敢信');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '去奥达曼之前我得先刷点金币');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '现在厄运之槌的队太难找了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我去黑石深渊跑趟快速任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我喜欢这儿的剧情活起来的感觉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁也卡？连/dance都跳不好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，还记得大家都说想当战士那阵吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '小怪刷新太快了。我是猎人，真得停下来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚把蓝打空了，我去拿杯酒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙很漂亮，可出来真是受罪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '再刷点金币就能买新坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚被人抢了装备，那我说句恭喜吧');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%zone的掉落咋这么烂呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '是只有我觉得还是玛拉顿的怪打人太疼');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人有黑石深渊的技巧吗。我卡在某处了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚升到%level');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我为啥要选在这儿玩法师升级啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有人在%zone被蜘蛛坑吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓，祖尔法拉克每个任务都折腾人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还记得我们没这些花哨装备的时候吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌太疯了，能不能给个安安静静的本啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '跑全程玛拉顿，值不值啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能给我开个去黑石深渊的门？谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嘿，今天奥达曼咋这么空');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '又是祖尔法拉克，唉');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '坦克会没事的，你等着看');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '说实话玛拉顿就是特别好耍');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 3, 0, 0, 0, 0, 10, '坦克、猎人，我爱你们');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁能说说开锁工具怎么弄啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '现在我明白死亡矿井为啥要组队了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哇，我都%level了，感觉任务做了八百年');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷有啥建议吗？我头一回来');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井刷怪慢得要命，真是谢谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，队伍对了影牙城堡也太简单了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴就是个又黑又吵的地方');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我是剧情党，这氛围一直很棒');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢建议，这个我正学着上手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今天这延迟气得我想原地/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '掉落怎么这么久，我快疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我卡在哀嚎洞穴了，估计装备还得再搞搞');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我喜欢剧情，可这些任务太磨人了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这游戏全是回忆，真不敢相信它回来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '背包怎么才16格啊天');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈我在死亡矿井拉了5只怪，别担心');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这任务难住我了，求帮忙？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷真烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在影牙想一只一只拉怪');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还记得咱们第一次打死亡矿井吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '能给我加个血吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '马上回来，去看下邮箱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真没想到我会说这话，我居然有点想哀嚎洞穴了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '靠，我找不到死亡矿井的入口');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，我都忘了自己有多讨厌这些任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我的怪跑出区域的时候最烦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，我12级就有2000金了，史上最富新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁能带带影牙城堡？我迷路了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '采矿啥时候开始练合适？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%zone这些任务轻松模式');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢大家帮忙，我19级终于通了怒焰裂谷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好哈哈，第一次来哀嚎洞穴。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井轻松过，还缺1个，来的说');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人老是要加血，是不是挺逗的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我怎么还挖不了铁矿？采矿总是不够高');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢邀请我打死亡矿井，打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴到底怎么单刷啊？？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '目前19级的任务感觉挺轻松');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，还记得我以为骷髅钥匙真能开门吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '%zone怎么找人啊？有人知道吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人能带我去哀嚎洞穴吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '影牙城堡求带');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '现在的怒焰跟散步一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_general', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁怀念当年练级的好日子？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '搞到新坐骑啦！我那小马驹就挺好使。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁知道哪儿能刷蛤蜊做烹饪配方？我%level，刚入坑。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次通影牙城堡，捡到把不错的小刀，新手能这样不赖了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚凑齐%level锻造要的矿石，谢谢帮忙的各位。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁知道%level去哪儿刷皮好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我第一件绿装到手了，原来怒焰真的会掉。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我怎么就总找不到好地方呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次打完怒焰，轻松模式。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈给了谁10铜，这趟狩猎真棒。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚练剥皮，找皮料。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚搞到一块200铜的锭。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刷金币还是刷材料，纠结啊纠结。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我就刷了10铜，咋地，我可有钱了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从铁炉堡厨师那儿弄到个面包新配方，还有比这更爽的？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '找到个挖矿的好地方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '找到刷布的最佳地点了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从那只野猪身上弄到5铜，多谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怎么总是猎人要喂宝宝。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '卖亚麻布能赚点钱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '队伍给力，死亡矿井一路轻松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚拿到初级治疗药水的配方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁想来打影牙城堡？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我从没意识到自己在哀嚎洞穴花了这么多时间。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁在冲20级？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '多谢邀请，死亡矿井有点乱但挺好玩的！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈在8级侏儒那儿刷了50铜。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '你好，刚做出我第一件制皮装备！找点好熟皮再做几件。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, 'gg，人生第一次打完死亡矿井，总算不是新手了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，我刚在怒焰做完第一个任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '新手报到，6级刚拿到第一把弓！找几个靠谱猎人一起刷。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于在奥格瑞玛找到制皮师给我做新装备了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '各位冒险者好，刚到15级，制皮刷材料有啥好建议？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚拿到第一把矿锄！新手区附近哪儿有好矿挖？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，我刚做出第一件制皮装备。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我刚拿到个锻造配方，我要成最有钱的人了，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '天呐，我们挖到第一块铜矿石了！终于能开始熔炼了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '发现个从没见过的新任务点，绝对新鲜。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真不敢信第一次竟然错过了，终于10级。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井掉了个稀有，gg各位，让我试试。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '你知道吗，哀嚎洞穴最棒的就是那尖叫声。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我刚拿到职业坐骑，哇太棒了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚拿到第一只坐骑，感觉太爽了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴运气好掉了个稀有，还是蓝装。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚升到%level，这刷级简直没完没了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，怒焰裂谷真有怀旧感。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚打完死亡矿井，感觉自己很猛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '今天找到株稀有草药，都记不清上回是啥时候了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '制皮终于练到50了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我刚干掉怒焰的一号boss，松口气。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴这么简单，我之前干嘛一直拖着。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚找到把还行的武器，感觉不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井是难搞，但值得。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '队里得换个更好的坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '得弄点好装备，这练级太难受了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚拿到第一只坐骑，终于能骑着在达纳苏斯转悠躲开那些新手了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于在死亡矿井升到%level，最后那个boss真折磨人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我跟你说，卡得越来越厉害了，感觉游戏在针对我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '各位，我刚拿到铁皮药水的第一个配方。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从死亡矿井boss那儿搞到把新斧子，刷怪该轻松点了，单刷毫无压力。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我一直想在艾尔文森林采点草药，可总有人先到。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哎，真没想到，刚在怒焰裂谷碰上个稀有刷新。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于把垃圾全卖换了些银币，打算买几瓶药水。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚在死亡矿井做完第一个任务，好久没来了，回忆全回来了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '找队伍，我刚起步，但准备好打点难点的副本了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '钓鱼刚练上去！接下来练啥好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于到%level拿到那只好坐骑了，谢谢会里的兄弟！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井挺轻松，不过我觉得得换把好剑，下一站影牙吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷求帮忙，有人知道那些陷阱吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次通哀嚎洞穴那会儿，简直是噩梦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈，死亡矿井的怪真凶，不过我把缺的金币搞到手了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴轻松搞定，现在得去采点草药做任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我在练猎人，接下来该干啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于做完提升制皮技能任务的第一部分，现在得找把更好的武器。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我任务需要帮忙，但不知道下条线索去哪儿找，咋办？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '运气好，在石爪山脉一个洞里找到铁矿脉，我矿包都满了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴还差人，这都我第五趟了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，刚接了个提到上层精灵灭亡的任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我们刚干掉范克里夫，掉落分配也不错，gg各位。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这些地图的背景故事太棒了，我就爱这剧情。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚弄到副新皮手套，看着贼新。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我们会里的猎人总是一副耸肩样，得多堆点输出。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '各位，我刚拿到第一只暴风城坐骑，终于啊！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井刷本，我要的靴子到手了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '等我给你看看我攒了多少铜币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我在影牙城堡死了多少次都数不清了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚补上我缺的那个法师法术，哇这配装手感好多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我都为影牙城堡里被我们杀的怪感到难过了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚做出我第一面铁盾，总算是个真坦克了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于有坐骑了，我再也不用走路了，简直是奇迹。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '挖矿赚了150铜，谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '天呐我们拿到第一块金锭了，等好久了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '恭喜发财，希望你玩得开心。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢在死亡矿井的帮忙！gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我赚到1枚金币，今天是个好日子。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚通完怒焰裂谷，轻松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰还缺猎人和治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴是我最爱的刷怪地。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚挖矿赚了25银，哇。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚拿到坐骑，终于能离开丹莫罗了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢帮我打黑暗深渊，你们太棒了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚在血色修道院掉了第一件史诗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '换新法杖就轻松了，这根我还没用过呢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于拿到诺莫瑞根的钥匙了，赶紧打完收工吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有了坐骑，监狱现在轻轻松松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚拿到坐骑，还接了个相关的任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于打完剃刀高地，真是场噩梦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢在血色修道院给我加血，我欠你一次。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚到%level，感觉自己无敌了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有这队伍，监狱就是小菜一碟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院怎么打最好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '那个任务给的坐骑我拿到了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从影牙城堡搞到把新斧子，我第一件蓝装！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于在简单模式干掉范克里夫了，我们都快撑不住了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨呀。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我们从那任务拿到钥匙了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇，真不敢信我搞到新坐骑了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱超简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根真难受。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢帮我弄到坐骑。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈上次我们打诺莫瑞根被困住了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我终于攒到200金了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色30分钟就通了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '到了剃刀高地我们该干啥？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哇，第一次进影牙城堡，还挺简单。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊记得一次拉3只怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能讲讲诺莫瑞根的战术？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%level就拿到第一只坐骑，哇。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这得花我好久。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱里的迪菲亚真烦人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于在监狱把那任务做完了，先谢谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚拿到诺莫瑞根的钥匙，开门的时候我要跳个舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽太带劲了，掉落也不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我终于拿到血色修道院的钥匙了！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚干掉剃刀高地的boss，史诗级战斗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次在这儿挖矿，我连路都找不着。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院简直是噩梦，不过掉落还不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '你们知道怎么去剃刀高地吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚用圣骑士在监狱把任务做完了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我终于拿到诺莫瑞根的钥匙了！！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我终于在剃刀沼泽刷到那件掉落了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于搞到那坐骑，跑得飞快哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%level就搞到件绿披风！总算有点用的东西了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '多谢在黑暗深渊给我加血。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院通了，有人要去剃刀沼泽吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根随便刷，缺1个坦克，谁想轻松赚金？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '制皮任务第一部分刚做完，就快成了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刷新的时间简直是反人类。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '看见个法师在监狱杀完卫兵跳了个舞，我乐了一整天。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地打完了，掉落一般，不过我不抱怨。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '马上回来，得走了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱，有点卡但还是挺好玩的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁有多余的坐骑卷轴？谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽就是场乱斗，打得挺爽，我喜欢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院刷本队，不闹事，轻松搞定。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我终于拿到坐骑了，感觉太好了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚打完黑暗深渊，搞到几件不错的蓝装。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我们终于搞到那坐骑了，天呐感觉跟赢了一样。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇我刚接到个诺莫瑞根的任务，多谢大家帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哎哟我把血色那任务做完了哈哈，我做到了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚从剃刀高地弄到个新饰品。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于通了监狱，掉了几块好布。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚打完血色修道院，掉了件挺稀有的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚从剃刀沼泽弄到把帅剑。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '好，坐骑到手了，下一站剃刀高地。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚从黑暗深渊弄到些好装备，感觉真不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，刚从黑暗深渊弄到个不错的饰品。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '好了各位，刚从诺莫瑞根赚了点金币。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家好，我回来啦哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '笑死，我正好赶上%level！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '多亏刚才那个副本我拿到坐骑了，缺坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于把黑暗深渊那个烦人的%level任务做完了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚在监狱掉了第一件史诗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人看见剃刀沼泽最后那波拉怪吗，太神了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院今天挺轻松。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能共享下剃刀高地的任务，谢谢哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '求诺莫瑞根的队伍。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于攒够买那坐骑的金币了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱缺个治疗，找治疗。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '不错，我刚接了个20%经验加成的任务。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚在剃刀高地掉了第一件史诗，不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚拿到坐骑，现在得找条顺路的路线。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈剃刀高地有时候真无聊，不过至少掉落还行。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '在诺莫瑞根抠金币，还有谁想搭个伙？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇，我还记得咱们没坐骑的时候。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '真不敢信血色修道院这趟这么快。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '各位好啊，咱们赶紧办完吧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我就是来摸装备的，我知道这挺肤浅。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚在剃刀沼泽掉了史上最好的东西。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这可不是我第一次来，套路我都懂。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁烦透在哀嚎洞穴来回跑？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谢谢组我。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '看来血色修道院那场打得也没那么糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈十年了监狱还是把我虐。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '侏儒和他们那些陷阱还是把我遛得跟傻子似的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于拿到血色钥匙了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我任务栏里有黑暗深渊，谁想一起去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽全是大老鼠。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '祝你们其他还得刷诺莫瑞根的人好运。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地队伍出发，缺个能抗的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '多谢在血色的帮忙，你们最棒了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚做完乌鸦任务，弄到根不错的新法杖。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这么多年了高地还是把我虐。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '找黑暗深渊的队伍。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '制皮刚刷了100金，感觉真不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我学会骑术了，以后应该不用再走路了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽太带劲了，从盗贼身上掉了件好东西。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨，我需要的坐骑刚到手，我想骑着转转，看现在能不能追上别人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊通了，一路轻松，还有谁也打完了？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根乱成一团，不过拿到了装绑饰品，gg。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地轻松搞定，从盗贼那儿掉了好东西，谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院打完，任务全清了，谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '你好呀，很高兴认识你。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚到这地图的等级上限，该去更大的地方了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '%level打血色修道院还不算太糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '今天在黑暗深渊里感觉特别怀旧。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我刚在剃刀沼泽刷了一阵。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根刷得累，不过捡到把好武器。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地，哈哈真没想到。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我刚到血色修道院的等级上限。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于拿到那坐骑了，一路真不容易。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '想找人帮忙，找监狱的推队。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根搞定，轻松模式。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴挺有意思，金币没捡着，但经验赚够了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '老鼠能刷，可它们刷得也太快了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚在%level拿到我的坐骑，等这一天等太久了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，监狱的仇恨我拉了多少次了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于在黑暗深渊弄到把像样的剑，感觉真爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根太折磨了，刷新等得要死');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '抱歉啊各位，我卡了，网太烂了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '卧槽，我在剃刀高地出了那个稀有掉落，太激动了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨各位，谁在找血色修道院的队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于把监狱那几波小怪清了，烦死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院一遍过，轻松，谢谢大家帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨各位，我血色修道院的队要猎人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我在死亡矿井赚到第一枚金币了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '想喘口气的时候去剃刀高地真挺爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我刚把骑术升上去了，太开心了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于拿到那个坐骑提速buff了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地我们清得超快，谢谢各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊的任务我需要人帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '有人有诺莫瑞根的钥匙吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽这刷法要把我刷死了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地还差两个人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院那个稀有掉落轻松到手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '30级骑术终于学到了，谢谢大家');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这么多兽人，清怒焰裂谷真是要命。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '就差最后3个坐骑和5000金了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我刚到%level');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚打完剃刀高地，掉落不错！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨各位，血色修道院刚打完，终于拿到那个坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '干得好各位，黑暗深渊真带劲，输出漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨大家，就是来打个招呼。这地方我真喜欢，想起Leeroy Jenkins就想笑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '唉，诺莫瑞根太绕了，下次能弄张地图吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚从剃刀沼泽拿到新技能，舒服了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，就是来做日常的，坐骑到手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '兄弟，剃刀沼泽真挺好玩，升级拿装备都行');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '大家都得看看这猎人跟着节奏跳舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我有第一只坐骑了！你们也是吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我从血色那些修士身上弄到强效治疗药水的配方了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，摸监狱boss的时候卡了一下');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊可算过了，试了15次');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，剃刀高地还缺人吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨各位，终于到%level了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，500个腐烂之尘你们说拿来干嘛好？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于有坐骑了！为了她做的那些史诗任务真不值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '嗨，黑暗深渊的掉落去哪卖啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于在血色修道院那些修士身上摸到把像样的剑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还好我没碰上那种一直跟着我的烦人怪。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '大家好，我就剩2%血把任务做完了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽挺难的，不过还是打完了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '对，监狱刚打完，出了个好货');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊那个任务终于从列表里划掉了，跑过去真费劲');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院轻松过，掉落不错，求个诺莫瑞根的队');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱我们打过了，一人分了50金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽简直是噩梦，但值了！现在%level了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱打得挺激烈，拿了点好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈，我们活着出来了，谢了各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '从深渊里捞了点金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚打完怒焰，拿了点还行的装备，不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '我们到诺莫瑞根了，出了件好货');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '天呐我终于有坐骑了！！！谢谢大家帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽刚才是真轻松，哇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '卧槽，刚从黑暗深渊弄到一身好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '唉，这怪现在的刷新速度简直离谱');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈20到39级这段是真难熬，不过掉落值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚打完监狱，还是烦这卡顿，不过好歹过了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根是真需要人搭把手，太难搞了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哇，35级打血色修道院真是噩梦，你不觉得吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '这些草药我该拿去干嘛？我是新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谁能帮我练练制皮啊？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '哈哈我这猎人宠物现在啥都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚从血色修道院摸到件好东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽到底怎么去啊，太费劲了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于拿到那坐骑了，太感谢各位了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '第一件紫装到手，%level终于有点感觉了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊刚清完，一次没死，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根真是满满的回忆');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱挺折磨的，但值');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽差点让我退坑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '血色修道院刷得累，但掉落轻松到手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '在哀嚎洞穴等人组队，马上回来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚拿到%level的坐骑！这苦真不是白吃的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '从剃刀高地弄到那件超赞的紫装');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '还有谁喜欢这种怀旧的感觉？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽这仗打得太不公平了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地就是那种老派的硬磨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '今天血色修道院轻松得很，有人要帮忙吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀高地挺有挑战，现在%level了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '第一件紫装到手，可算来了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '黑暗深渊挺难的，不过值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '不错，我正想找几个朋友一起玩呢 :D');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈我们在影牙打得太烂了，我都替我们难受。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '监狱刚打完，掉落真香');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁知道黑暗深渊的好路线？想搞点装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚在监狱刷了点金，终于买到坐骑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根我还差几个人，谁去？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '剃刀沼泽谁帮我找个治疗啊');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚拿到血色钥匙，现在总算能进副本了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚在剃刀高地挖了点矿，赚了50金');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '谁能教教我采矿，我还在摸索');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '抱歉，我得挂机一会儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '终于弄到猎人宠物了，费老劲了，啥都得要，但总算到手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于学会制皮了，太爽了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '诺莫瑞根想找人一起，我是新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 2, 0, 0, 0, 0, 10, '刚在血色修道院出了件传说，哈哈我觉得纯靠运气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢大家帮打黑石深渊，拿到不少好东西！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克真带劲，不过黑石塔下层我还得再找人');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从奥达曼弄到个亮闪闪的新饰品！太爽了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '别忘了看厄运之槌里的背景故事，太精彩了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道沉没的神庙有什么好打法吗，我是新手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '今天祖尔法拉克出了件好东西，我喜欢里面的任务');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '想知道在玛拉顿刷声望最好的办法是啥');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈黑石深渊的怪太好玩了，我们被打爆了但没事！');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我在刷皮革做制皮任务，有人能给点建议不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人总得带个宝宝嘛 : )');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '跟好人一起玩才是享受剧情的最好方式，我在沉没的神庙找着几件好装备');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我太喜欢厄运之槌的氛围了，不过是真的凶');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从厄运之槌弄到个稀有掉落！爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石钥匙我们终于拿到了！谢了各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌的胸甲轻松到手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克清完了，大家干得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼的稀有掉落到手了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我们终于在玛拉顿干掉瑟莱德丝公主了，gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '从沉没的神庙弄了个新玩具，小意思');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我们凑齐暗影议会套装了，哇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚学会钓鱼，谢啦。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔我们搞定了，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克出了个超棒的，+13敏捷的腰带，谢谢rng哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从祖尔法拉克拿到不屈之力之槌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '天呐黑石深渊的刷新时间太坑了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '笑哭，黑石塔下层有个萌新跑去跟火元素/dance');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '弄到明亮铁锤了，能帮忙打武器，谢谢各位');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿的掉落离谱，但55级打起来太惨烈了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '终于在沉没的神庙赶在刷新前搞定了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人要矿工吗，我包满满的铁');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊卡得离谱，可能得重启了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '4级，找哀嚎洞穴的队伍。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '想找个附魔师多的公会，求带');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人知道厄运之槌附近哪采药好吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我们刚从奥达曼拿到件上古遗物，不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哇，厄运之槌那次真是险');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刷新太慢了，太感谢了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚在黑石深渊出了紫装，gg');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我们赶在重置前把沉没的神庙打了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢大家在黑石塔下层帮忙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克终于清完了，松口气');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿只用了平时一半时间，55级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰挺顺利，大家都很给力。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '今天怎么卡成这样，动都动不了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚看见一个学Leeroy Jenkins的直接倒在小怪手里');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '猎人都哪去了，他们总是啥都要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚在祖尔法拉克弄到符文银刃，爽');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我那双黑铁靴子该咋办，求指点');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼我们清了，第二次就过，不过哇哦');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁在玛拉顿采药，太无聊了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你知道黑石塔下层能刷铁吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '加兹瑞拉那差点团灭，不过活着出来了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚弄到把亮闪闪的新绿武器，符文不是事儿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我采矿刚练到%level。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，在黑石深渊又迷路了，这路太难认');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊，50多个怪，金子赚疯了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这副本掉落真多，还采到些稀有草药，哇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '累死累活，总算找着件亮闪闪的新东西');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哇，我们终于在祖尔法拉克干掉加兹瑞拉了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '厄运之槌刚打完，耗了一整天，不过披风到手了哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁能再给我讲讲奥达曼的背景故事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '这卡顿要命，连矿都挖不顺畅');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我们终于从黑石深渊拿到那戒指了，好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '%level打黑石塔下层真遭罪，但太值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '干得好各位，这趟挺有意思。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '终于拿到魔纹布的图纸了，该去刷材料了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谁把玛拉顿设计成这么个迷宫的');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '哈哈，这就是为啥别一个人冲进阿塔哈卡神庙');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还在黑石深渊刷金买坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我发誓今天掉落的rng跟我有仇');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '沉没的神庙总是有挑战，不过掉落是真的好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从暗月马戏团拿到5%经验加成，谢谢rng');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '祖尔法拉克我们20分钟就打完了，第一次算不错了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼的刷新时间太离谱，一只巨魔要2分钟');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石深渊难道没个办法避开卡顿吗');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于学会制皮了，谢谢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '拿到新坦克专精了？2.9秒无敌');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '我让45%的怪来打我，一点都不意外');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '从沉没的神庙弄了把新武器，我要剑不要钓鱼竿');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '玛拉顿我们团灭了5次，不过拿到装备了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从黑石塔下层弄到只坐骑');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁喜欢厄运之槌那种卡顿感');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '奥达曼第一次打通，终于拿到泰坦遗物，53级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '黑石塔钥匙到手了，还差2个人开打');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚从玛拉顿拿到邪纹披风，真是一场硬磨');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人要治疗打祖尔法拉克吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '恭喜大家，通关干得漂亮。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚弄到泰坦锻造符文剑，58级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '谢谢邀请，黑石塔下层这趟打得漂亮');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '马上回来，现实里有事');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '有人有厄运之槌的队吗，就差收尾了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '找到那个新披风的图纸了，多谢');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '法师怎么老爱在战斗中开传送门，哈哈');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刚拿到无尽寒冬权杖，49级');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '真希望宠物能好点，猎人啥都得要');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '刷了5趟，终于把黑石深渊那个稀有掉落拿到手');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '求个玛拉顿的队，有人有空吗？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次来哀嚎洞穴，挺好玩的。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '好消息，我们换了个新打法把黑石塔下层清了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '大家好，看到这儿这么多活跃玩家真不错');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '嗨，去奥达曼最好的路线是哪条？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '在沉没的神庙发现个隐藏箱子，太值了');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '终于摸到坦克的门道了，感觉真好');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '第一次在黑石深渊出那个稀有掉落，那感觉真是没得比');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '还有谁觉得玛拉顿特别容易迷路？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 3, 0, 0, 0, 0, 10, '你们在奥达曼怎么刷更多经验？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我搞到第一只坐骑了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '死亡矿井超爽，就是卡得有时候挺难受。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '6级，城堡那边需要帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚在怒焰干掉个boss，太爽了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '这趟挺顺，谢谢帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈怒焰裂谷的一号boss干掉了，%level能有这成绩不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '真不敢信我们在这波小怪上灭了两次。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '摸到好货就该一起跳个舞哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈我们成了！第一次真把死亡矿井打通，终于啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '记得把血瓶留着清小怪用。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '恭喜拿到绿武器。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '战术对了，死亡矿井以后就轻松多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁觉得晚上怪打得更疼？可能是我错觉。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '下次影牙城堡我们肯定能打得更好。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '得练练群体伤害，清小怪才快。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢分赃建议，帮了大忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '天呐刚掉了第一件绿装，5级靴子 :D');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于拿到死亡矿井的任务了，我都快以为自己被诅咒了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '感谢在怒焰第一个扛伤害的人，让我能跳个舞。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嘿，找影牙城堡的队伍，新手也欢迎，我%level。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '多谢采矿的建议，第一次挖到100铜总是特别有纪念意义。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '太开心了，碰到个不抢影牙城堡所有东西的猎人。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚打完死亡矿井拿到第一个任务，谢谢大家帮忙。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从训练师那儿学了新法术，%level总算能放寒冰箭了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于刷够布做靴子了，5级装备做出来真爽。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈谢谢哀嚎洞穴的掉落。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '没事，就是需要人来给我当坦克。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚在城堡跟个10级的成了朋友。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢帮忙，我去睡了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '猎人怎么总这么贪啊。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哈哈我等刷新，不过我猜你得等一阵。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于在洞穴里赚到点钱了，太刺激了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从死亡矿井弄到把亮闪闪的新武器，总算升级了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '谢谢队伍带我打影牙城堡，掉落不错。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '我想刷点金币，新手有啥建议不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于%level了，总算能离开这新手区了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷差点把我打崩，不过拿到了几件好绿装。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一个法术练到30了，终于有点用了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怎么这么卡，连跑个银行都卡。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '挖矿赚到第一块金币，感觉自己像国王。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次进死亡矿井，这地方跟迷宫似的，我喜欢。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '终于有坐骑了，世界一下子大多了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '看见个猎人在拍卖行啥都要，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '那些精英怪的刷新速度简直离谱。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚从食谱书里学到第一个配方，感觉自己高级了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '怒焰裂谷掉落烂透了，不过一小时不到就通了，也不算太糟。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁需要帮忙做暴风城的烹饪任务？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '第一次打完怒焰裂谷，太好玩了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人知道死亡矿井咋打吗？我刚来。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '哀嚎洞穴太疯了，一堆毒蜘蛛。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '嘿，%level练级有啥技巧不？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '打完影牙城堡感觉自己像英雄，哈哈。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁喜欢暴风城的背景故事和氛围？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '还有谁打完怒焰裂谷觉得自己特猛？');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '刚拿到第一只坐骑，骑着到处跑太爽了。');
INSERT INTO playerbots_coa_night_lines (source, channel, event, locale, race, class, level_band, zone, thread, step, speaker, weight, text) VALUES (1, 1, 'idle_brag', 4, 0, 0, 1, 0, 0, 0, 0, 10, '有人知道哪儿刷草药最好吗？我得练炼金。');
